(window.GIM_TS=window.GIM_TS||{})["Shabbat.3"]={"from":72,"a":[["\u0003שכח\u0004 אדם \u0003קדירה\u0004 בערב שבת \u0003על גבי כירה ובשלה בשבת, מהו\u0004 הדין בכגון זה, האם מותר לאכול מתבשיל זה, או לא? \u0003אישתיק\u0004 \u0005[שתק]\u0006 \u0003ולא אמר להו\u0004 \u0005[להם]\u0006 \u0003ולא מידי\u0004 \u0005[דבר\u0006\u0005].\u0006 \u0003למחר נפק\u0004 \u0005[יצא]\u0006 ו\u0003דרש להו\u0004 \u0005[להם\u0006\u0005]\u0006 בציבור והודיע הלכה זו: \u0003המבשל בשבת,\u0004 אם בישל \u0003בשוגג\u0004 — \u0003יאכל,\u0004 ואם בישל \u0003במזיד\u0004 — \u0003לא יאכל, ולא שנא\u0004 \u0005[ואין\u0006 הדין \u0005שונה\u0006\u0005]\u0006 גם בשוכח. שתי המלים האחרונות בדרשת ר' חייא בר אבא לא היו מובנות.","ושאלו: \u0003מאי\u0004 \u0005[מה\u0006 הפירוש\u0005]\u0006 הלכה למעשה של \u0003\"ולא שנא\"\u0004 \u0005[\u0006\u0005\"ואינו שונה\"]?\u0006 \u0003רבה ורב יוסף דאמרי תרווייהו להיתירא\u0004 \u0005[שאמרו שניהם\u0006 לפרש את הדבר \u0005ל\u0006צד \u0005היתר\u0006\u0005]\u0006 הסבר הדבר הוא: \u0003מבשל הוא\u0004 שמאחר \u0003דקא עביד\u0004 \u0005[שהוא עושה]\u0006 \u0003מעשה\u0004 על כן אם עשה זאת \u0003במזיד\u0004 — \u0003לא יאכל, אבל האי\u0004 \u0005[זה]\u0006 ששכח את הקדירה על גבי האש ש\u0003לא קא עביד\u0004 \u0005[עושה הוא]\u0006 \u0003מעשה,\u0004 אם כן אף אם השאיר את הקדירה \u0003במזיד\u0004 מערב שבת \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003יאכל.\u0004 ואילו \u0003רב נחמן בר יצחק\u0004 אמר שיש לפרש את \"ולא שנא\" \u0003לאיסורא\u0004 \u0005[לאיסור\u0006\u0005]\u0006 ובאופן זה: \u0003מבשל הוא\u0004 ש\u0003לא אתי לאיערומי\u0004 \u0005[יבוא להערים],\u0006 שאין אנו חושדים באדם שיבשל בשבת במזיד, ומשום כך \u0003אם בישל בשוגג\u0004 — \u0003יאכל, אבל האי דאתי לאיערומי\u0004 \u0005[זה שיבוא להערים]\u0006 וישאיר קדירה ויאמר \"שכחתיה\" קנסו חכמים כי גם אם נעשה הדבר \u0003בשוגג נמי\u0004 \u0005[גם כן]\u0006 \u0003לא יאכל.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים\u0006\u0005]\u0006 על הדברים הללו ממה ששנינו בברייתא: \u0003שכח קדירה על גבי כירה ובישלה בשבת,\u0004 אם היה זה \u0003בשוגג\u0004 — \u0003יאכל, במזיד\u0004 — \u0003לא יאכל. במה דברים אמורים\u0004 — \u0003ב\u0004שאותה קדירה מכילה מים \u0003חמין ש\u0004עדיין \u0003לא הוחמו כל צורכן\u0004 או \u0003תבשיל ש\u0004עדיין \u0003לא בישל\u0004 (נתבשל) \u0003כל צורכו. אבל\u0004 אם היו בה מים \u0003חמין ש\u0004כבר \u0003הוחמו כל צורכן ותבשיל ש\u0004כבר \u0003בישל כל צורכו, בין\u0004 שהשאיר את הקדירה \u0003בשוגג, בין במזיד\u0004 — \u0003יאכל,\u0004 אלו \u0003דברי ר' מאיר.\u0004","\u0003ר' יהודה אומר,\u0004 יש לחלק: \u0003חמין ש\u0004כבר \u0003הוחמו כל צורכן\u0004 — \u0003מותרין מפני ש\u0004באופן כזה המשך השהייתן על גבי האש גורם לכך שהן \u0003מצטמק ורע לו,\u0004 ובאופן כזה ודאי יימנע מלהוסיף חום למים חמים, שלא יאבד את המים. \u0003ו\u0004אולם \u0003תבשיל שבישל כל צורכו\u0004 — \u0003אסור\u0004 להמשיך ולהשהותו על גבי האש \u0003מפני ש\u0004באופן כזה הוא \u0003מצטמק ויפה לו,\u0004 ויש חשש שיחתה בגחלים להוסיף חום לתבשיל, \u0003ו\u0004כלל הוא \u0003שכל המצטמק ויפה לו, כגון כרוב ופולים ובשר טרוף\u0004 (חתוך לחתיכות קטנות) — \u0003אסור, וכל המצטמק ורע לו\u0004 — \u0003מותר.\u0004","\u0003קתני מיהא\u0004 \u0005[על כל פנים שנינו\u0006\u0005]\u0006 בברייתא שב\u0003תבשיל שלא בישל כל צורכו\u0004 אם היה זה בשוגג — מותר, ומעתה, \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רב נחמן בר יצחק לא קשיא\u0004 \u0005[אין\u0006 זו \u0005קושיה\u0006\u0005]\u0006 שאף שאסר רב נחמן קדירה ששכחוה בשוגג, ובברייתא לא נאסר אלא כאשר היה זה במזיד, יכול הוא להסביר כי \u0003כאן\u0004 בברייתא שהתירו הרי זה \u0003קודם\u0004 ה\u0003גזרה\u0004 שגזרו שמא יבוא אדם להערים, ואילו \u0003כאן\u0004 בהלכה המאוחרת לפירוש רב נחמן — הרי זה \u0003לאחר\u0004 ה\u0003גזרה\u0004 שבגללה אסרו גם שוגג. \u0003אלא רבה ורב יוסף דאמרי להיתירא\u0004 \u0005[שאמרו\u0006 שניהם \u0005להיתר\u0006\u0005]\u0006 בשוגג ובמזיד, אם כן \u0003אי\u0004 \u0005[אם]\u0006 בבברייתא זו מדובר \u0003קודם\u0004 ה\u0003גזרה\u0004 — \u0003קשיא\u0004 \u0005[קשה]\u0006 בכל אופן מדין \u0003מזיד,\u0004 שבברייתא נאסר, ואילו רבה ורב יוסף התירו. ומצד אחר \u0003אי\u0004 \u0005[אם]\u0006 בברייתא זו מדובר \u0003לאחר\u0004 ה\u0003גזרה\u0004 — \u0003קשיא נמי\u0004 \u0005[קשה גם כן ענין]\u0006 \u0003שוגג,\u0004 שהרי התירו רבה ורב יוסף בכל מקרה. לקושיה זו לא נמצאה תשובה וסוכם כי אכן \u0003קשיא\u0004 \u0005[קשה\u0006\u0005].\u0006","לגופו של דבר שואלים: \u0003מאי גזירתא\u0004 \u0005[מהי הגזירה\u0006\u0005]\u0006 שהזכרנו, ודברנו על הזמן שלפני הגזירה? ואומרים: זוהי הגזירה עליה דיבר רב, ש\u0003רב יהודה בר שמואל\u0004 שכך \u0003אמר ר' אבא\u0004 שכך \u0003אמר רב כהנא\u0004 שכך \u0003אמר רב: בתחילה היו אומרים\u0004 כי \u0003המבשל בשבת,\u0004 אם היה זה \u0003בשוגג\u0004 — \u0003יאכל, במזיד\u0004 — \u0003לא יאכל, והוא הדין לשוכח\u0004 את הקדירה מערב \u0003שבת על גבי הכירה ונתבשלה בשבת. משרבו\u0004 האנשים שהיו \u0003משהין\u0004 את קדירותיהן \u0003במזיד ואומרים\u0004 כדי להצדיק את עצמם \u0003\"שכחים אנו\",\u0004 שמחמת השכחה נעשה הדבר, \u0003חזרו וקנסו על השוכח,\u0004 שאף השוכח בשוגג לא יאכל. בתוספתא זו שהובאה מקודם בענין זה ששכח קדירה על גבי הכירה ונתבשלה בשבת שנינו שמיקל ר' מאיר ומתיר בחמין שהוחמו כל צורכם, וכן בתבשיל מבושל כל צורכו, אפילו כאשר השאירו אותו במזיד על גבי כירה. ור' יהודה מחמיר ומבדיל בין מקרים שונים. ואולם בתוספתא שהובאה מקודם שבה שנינו שנחלקו ר' מאיר ור' יהודה בשיטת בית הלל ובית שמאי בענין השהייה על גבי כירה בשבת, שר' מאיר אומר שאסור להשהות תבשיל לכתחילה כלל, אפילו לדברי בית הלל המקילים. ור' יהודה הקל והתיר.","ואם כן \u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003ר' מאיר\u0004 על דברי \u0003ר' מאיר\u0004 עצמם, וכן \u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003ר' יהודה\u0004 על דברי \u0003ר' יהודה\u0004 עצמם! ומשיבים: מדברי \u0003ר' מאיר\u0004 על דברי \u0003ר' מאיר לא קשיא\u0004 \u0005[קשה\u0006\u0005],\u0006 שכן יש לומר: \u0003הא\u0004 \u0005[זו\u0006\u0005]\u0006 ששנינו שאסר ר' מאיר להשהות תבשיל כלל מדובר היה \u0003לכתחילה,\u0004 ואילו \u0003הא\u0004 \u0005[וזו\u0006\u0005]\u0006 שהתיר אפילו במזיד מדובר ב\u0003דיעבד,\u0004 שכבר נעשה מעשה. ומדברי \u0003ר' יהודה\u0004 על דברי \u0003ר' יהודה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא קשיא\u0004 \u0005[קשה\u0006\u0005],\u0006 שכן יש לומר: \u0003כאן\u0004 כשהתיר — היה זה \u0003ב\u0004כירה \u0003גרופה וקטומה,\u0004 ואילו \u0003כאן\u0004 כשנטה לאיסור — מדובר \u0003ב\u0004כירה \u0003שאינה גרופה וקטומה.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 לתלמידים\u0005]\u0006 שאלה זו: \u0003עבר ושהה\u0004 קדירתו בשבת על גבי האש \u0003מאי\u0004 \u0005[מה\u0006 דינו\u0005]?\u0006 \u0003מי\u0004 \u0005[האם]\u0006 \u0003קנסוהו רבנן\u0004 \u0005[חכמים]\u0006 ואסרו עליו לאכול את התבשיל, \u0003או לא\u0004 קנסוהו? \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ש\u0003אמר שמואל בר נתן\u0004 שכך \u0003אמר ר' חנינא: כשהלך ר' יוסי ל\u0004עיר \u0003ציפורי מצא חמין שנשתהו על גבי כירה ולא אסר להן\u0004 להשתמש בהם, ומצא \u0003ביצים מצומקות שנשתהו על גבי כירה\u0004 בשבת, \u0003ואסר להן. מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה שהתיר \u0003ואסר להם לאותה שבת?\u0004 ואם כן נראה שאסר לאכול תבשיל שהושהה במזיד בשבת. את ההנחה הזו דוחים מיד: \u0003לא,\u0004 אלא אסר להם \u0003לשבת הבאה\u0004 לעשות כן לכתחילה, אבל לאותה שבת לא אסר.","ותמהים: \u0003מכלל\u0004 הדברים למדים כי \u0003ביצים מצומקות מצטמקות\u0004 כאשר הן שוהות זמן ממושך על גבי האש \u0003ויפה להן נינהו\u0004 \u0005[הינן],\u0006 שלכן חילק ר' יוסי בין חמין שמותר להשהותם, וביצים שאסור להשהותן? ומשיבים: \u0003אין\u0004 \u0005[כן\u0006\u0005],\u0006 יפה הצימוק לביצים. וכפי ש\u0003אמר רב חמא בר חנינא: פעם אחת נתארחתי אני ורבי למקום אחד והביאו לפנינו ביצים מצומקות\u0004 שנצטמקו עד לגודלם של \u0003עוזרדין ואכלנו מהן הרבה.\u0004 הרי שביצים מצומקות טובות הן, ויש איפוא מקום לחשש שכאשר הן מונחות בשבת על גבי האש יחתה בגחלים כדי לצמק אותן יותר.","שנינו במשנה ש\u0003בית הלל אומרים\u0004 ש\u0003אף מחזירין\u0004 את הקדירה שהוסרה מן הכירה בשבת אליה. \u0003אמר רב ששת: לדברי האומר\u0004"],["\u0003מחזירין,\u0004 מותר לעשות זאת \u0003אפילו ב\u0004משך יום ה\u0003שבת,\u0004 ולא רק בליל שבת. \u0003ואף ר' אושעיא סבר\u0004 \u0005[סבור]\u0006 ש\u0003\"אף מחזירין\"\u0004 משמעו \u0003אפילו בשבת.\u0004 ש\u0003אמר ר' אושעיא: פעם אחת היינו עומדים\u0004 בשבת \u0003לעילא\u0004 \u0005[לפני\u0006\u0005]\u0006 \u0003מר' חייא רבה\u0004 \u0005[הגדול\u0006\u0005]\u0006 \u0003והעלנו לו קומקמוס\u0004 (קומקום) \u0003של\u0004 מים \u0003חמין מדיוטא\u0004 \u0005[מהקומה\u0006\u0005]\u0006 \u0003התחתונה לדיוטא\u0004 \u0005[לקומה]\u0006 \u0003העליונה, ומזגנו לו את הכוס, והחזרנוהו למקומו\u0004 על גבי הכירה, \u0003ולא אמר לנו דבר,\u0004 והרי שלדעתו מותר להחזיר את הקדירה לכירה אפילו בשבת.","\u0003אמר ר' זריקא\u0004 שכך \u0003אמר ר' אבא\u0004 שכך \u0003אמר ר' תדאי: לא שנו\u0004 שמותר להחזיר \u0003אלא\u0004 כ\u0003ש\u0004אותם כלים בהם התבשיל \u0003עודן בידו, אבל\u0004 אם כבר \u0003הניחן\u0004 לאותם כלים \u0003על גבי\u0004 ה\u0003קרקע\u0004 הרי זה ודאי שהתחרט על שהניחן על גבי האש, ו\u0003אסור\u0004 לו לחזור ולהניחן על גבי הכירה. \u0003אמר ר' אמי : ר' תדאי\u0004 מה \u0003דעבד\u0004 \u0005[שעשה]\u0006 ואמר — \u0003לגרמיה\u0004 \u0005[לעצמו]\u0006 \u0003הוא דעבד\u0004 \u0005[הוא שעשה\u0006\u0005],\u0006 ואין דבריו מחייבים כהלכה כללית. \u0003אלא הכי\u0004 \u0005[כך\u0006\u0005]\u0006 \u0003אמר ר' חייא\u0004 שכך \u0003אמר ר' יוחנן: אפילו הניחה\u0004 לאותה קדירה \u0003על גבי\u0004 ה\u0003קרקע\u0004 — \u0003מותר\u0004 להחזירה לכירה.","ומעירים כי \u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003בה\u0004 בבעיה זו \u0003רב דימי ורב שמואל בר יהודה, ותרוייהו משמיה\u0004 \u0005[ושניהם משמו]\u0006 של \u0003ר' אלעזר אמרי\u0004 \u0005[אמרו].\u0006 \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 כי כאשר \u0003עודן בידו\u0004 — \u0003מותר\u0004 להחזירן על גבי הכירה, אבל כאשר כבר \u0003הניחן על גבי קרקע\u0004 — \u0003אסור. וחד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 כי כאשר \u0003הניחן על גבי קרקע נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 \u0003מותר. אמר חזקיה משמיה\u0004 \u0005[משמו]\u0006 של \u0003אביי: הא\u0004 \u0005[זה]\u0006 ש\u0003אמרת\u0004 כי כאשר \u0003עודן בידו\u0004 — \u0003מותר\u0004 להחזיר לכירה, \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 הלכה זו \u0003אלא\u0004 כ\u0003שדעתו\u0004 היתה מראש \u0003להחזיר\u0004 לכירה, \u0003אבל\u0004 כאשר \u0003אין דעתו\u0004 מראש \u0003להחזיר\u0004 והתחרט ורצה בכל זאת להחזיר — \u0003אסור\u0004 בכגון זה להחזיר. \u0003מכלל\u0004 הדברים אפשר ללמוד שאם הניחן \u0003על גבי\u0004 ה\u0003קרקע אף על פי שדעתו\u0004 היתה \u0003להחזיר\u0004 — \u0003אסור.\u0004","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים\u0006\u0005]\u0006 דברים אלה בגרסה שונה, שכך \u0003אמר חזקיה משמיה\u0004 \u0005[משמו]\u0006 של \u0003אביי : הא\u0004 \u0005[זה]\u0006 ש\u0003אמרת\u0004 שאם כבר הניחן \u0003על גבי\u0004 ה\u0003קרקע\u0004 — \u0003אסור, לא אמרן\u0004 \u0005[אמרנו\u0006\u0005]\u0006 דבר זה \u0003אלא\u0004 כ\u0003שאין דעתו\u0004 מראש \u0003להחזיר, אבל\u0004 אם היתה \u0003דעתו להחזיר\u0004 — \u0003מותר.\u0004 ו\u0003מכלל\u0004 הדברים אתה למד כי כאשר \u0003עודן בידו, אף על פי שאין דעתו להחזיר\u0004 — \u0003מותר.\u0004 בענין זה \u0003בעי\u0004 \u0005[שאל\u0006\u0005]\u0006 \u0003ר' ירמיה:\u0004 במקרה שלא הניחן על גבי קרקע ולא אחזן בידו, אלא \u0003תלאן במקל מהו\u0004 הדין בכגון זה? וכן במקרה ש\u0003הניחן על גבי מטה מהו\u0004 הדין\u0003?\u0004 וכן \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אשי:\u0004 אם \u0003פינה\u0004 את המים \u0003ממיחם למיחם מהו\u0004 הדין? לשאלות אלה לא נמצאה תשובה ועל כן \u0003תיקו\u0004 \u0005[תעמודנה\u0006\u0005]\u0006 במקומן.","ההלכות שנאמרו בדיני כירה היו מיוחדות לכירה בלבד בשל המבנה המיוחד שלה, והאופן בו היא שומרת חום. ואולם בכלי אפייה אחרים כגון תנור או כופח יש דינים אחרים. ומפרטים: \u0003תנור שהסיקוהו\u0004 אפילו \u0003בקש\u0004 או \u0003בגבבא\u0004 — \u0003לא יתן\u0004 קדירה עליו בשבת, \u0003בין מתוכו בין מעל גביו.\u0004 ואילו \u0003כופח,\u0004 אם \u0003הסיקוהו בקש\u0004 או \u0003בגבבא\u0004 — \u0003הרי זה\u0004 דינו \u0003ככיריים,\u0004 ומותר להניח עליו קדירה בשבת. ואם הסיקוהו \u0003בגפת\u0004 או \u0003בעצים\u0004 — \u0003הרי הוא כתנור,\u0004 ואסור.","על מה ששנינו במשנה כי \u0003תנור שהסיקוהו\u0004 אפילו בקש או בגבבה לא יתן עליו אדם קדירה בין מתוכו בין על גביו, \u0003סבר\u0004 \u0005[סבור היה]\u0006 \u0003רב יוסף למימר\u0004 \u0005[לומר]\u0006 שמה שנאמר במשנה \u0003\"תוכו\"\u0004 הכוונה היא — \u0003תוכו ממש,\u0004 ומה שנאמר \u0003\"על גביו\"\u0004 הכוונה \u0003— על גביו ממש, אבל לסמוך\u0004 קדירה לתנור \u0003שפיר דמי\u0004 \u0005[יפה הוא,\u0006 מותר\u0005].\u0006 \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי\u0004 ממה ששנינו במשנתנו: \u0003כופח שהסיקוהו בקש\u0004 או \u0003בגבבא\u0004 — \u0003הרי הוא ככיריים, בגפת\u0004 או \u0003בעצים\u0004 — \u0003הרי הוא כתנור, ואסור.\u0004 ומעתה נדייק: \u0003הא\u0004 \u0005[הרי]\u0006 אם היה \u0003ככירה\u0004 — \u0003שרי\u0004 \u0005[\u0006היה \u0005מותר].\u0006 ואם כן נברר \u0003במאי עסקינן\u0004 \u0005[במה\u0006 בדיוק \u0005אנו עוסקים\u0006\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 כי אנו עוסקים בנתינה \u0003על גביו, ובמאי\u0004 \u0005[ובמה,\u0006 באיזה מקרה\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר \u0003כשאינו גרוף וקטום, אלא\u0004 אף \u0003כירה כי\u0004 \u0005[כאשר]\u0006 \u0003אינה גרופה וקטומה, על גביו מי שרי\u0004 \u0005[האם מותר]\u0006 לתת קדירה בשבת? \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 ודאי הכוונה היא רק לענין \u0003לסמוך\u0004 על גבי הכופח קדירה, \u0003וקתני\u0004 \u0005[ושנה]:\u0006 \u0003הרי הוא כתנור, ו\u0004משמעו ש\u0003אסיר\u0004 \u0005[אסור]!\u0006","על דברים אלה \u0003אמר רב אדא בר אהבה: הכא\u0004 \u0005[כאן]\u0006 \u0003בכופח גרוף וקטום, ותנור גרופה וקטומה עסקינן\u0004 \u0005[עוסקים אנו],\u0006 וכך יש להבין: \u0003הרי הוא כתנור\u0004 — \u0003דאף על גב\u0004 \u0005[שאף על פי]\u0006 שהוא \u0003גרוף וקטום\u0004 מכל מקום \u0003על גביו אסור ליתן\u0004 את הקדירה, \u0003דאי\u0004 \u0005[שאם]\u0006 היה דינו \u0003ככירה\u0004 הרי \u0003כי\u0004 \u0005[כאשר]\u0006 היא \u0003גרופה וקטומה\u0004 — \u0003שפיר דמי\u0004 \u0005[יפה\u0006 הדבר, מותר\u0005].\u0006 ומעירים כי אכן \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003אביי: תנור שהסיקוהו בקש\u0004 או \u0003בגבבא אין סומכין לו\u0004 קדירה, \u0003ואין צריך לומר\u0004 שאין נותנים \u0003על גביו, ואין צריך לומר\u0004 שאין נותנים \u0003לתוכו, ואין צריך לומר\u0004 שאם הוא מוסק בקש או בגבבא אסור, ודאי שאם הוא מוסק \u0003בגפת\u0004 או \u0003בעצים\u0004 אסור. ואילו \u0003כופח שהסיקוהו בקש\u0004 או \u0003בגבבא\u0004 — \u0003סומכין לו, ו\u0004אולם \u0003אין נותנין על גביו.\u0004 ואם הסיקוהו \u0003בגפת\u0004 או \u0003בעצים\u0004 — \u0003אין סומכין לו.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי: האי\u0004 \u0005[זה]\u0006 ה\u0003כופח היכי דמי\u0004 \u0005[כיצד הוא בדיוק],\u0006 למה הוא בעצם נחשב? \u0003אי\u0004 \u0005[אם]\u0006 \u0003ככירה דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 אם כן, \u0003אפילו\u0004 הסיקוהו \u0003בגפת\u0004 או \u0003בעצים נמי\u0004 \u0005[גם כן]\u0006 יהא מותר, ו\u0003אי\u0004 \u0005[אם]\u0006 \u0003כתנור דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 אם כן \u0003אפילו בקש\u0004 או \u0003בגבבא נמי\u0004 \u0005[גם כן]\u0006 \u0003לא! אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: הכופח עומד מבחינה הלכתית באמצע, \u0003נפיש הבליה\u0004 \u0005[מרובה הבלו,\u0006 חומו\u0005]\u0006 \u0003מ\u0004זה של \u0003כירה ו\u0004אולם \u0003זוטר הבליה\u0004 \u0005[מועט הבלו]\u0006 \u0003מ\u0004זה של \u0003תנור.\u0004","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 \u0003כופח, היכי דמי\u0004 \u0005[כיצד היא בדיוק]\u0006 \u0003כירה\u0004 בתורת כלים? \u0003אמר ר' יוסי בר חנינא: כופח\u0004 הוא כלי קטן הדומה לכירה, ואולם יש בו חור רק כדי מקום \u0003שפיתת\u0004 (הנחת) \u0003קדרה אחת.\u0004 ואילו \u0003כירה\u0004 היא ככופח כפול ויש בה \u0003מקום שפיתת שתי קדרות. אמר אביי: ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' ירמיה: אף אנן נמי תנינא\u0004 \u0005[אנחנו שנינו גם כן]\u0006 דברים אלה, ששנינו במשנה בדיני טומאה וטהרה: \u0003כירה\u0004 טמאה \u0003שנחלקה לאורכה\u0004 — \u0003טהורה,\u0004 כיון ששוב איננה יכולה להיחשב ככלי אלא כשבר כלי, ושבר כלי אינו מיטמא. ואולם אם נחלקה הכירה \u0003לרחבה\u0004 בין מקום שפיתת הקדירות — הרי היא \u0003טמאה,\u0004 שנעשתה כעין שתי כירות קטנות. ואילו \u0003כופח בין\u0004 שנחלק \u0003לאורכו\u0004 ו\u0003בין\u0004 שנחלק \u0003לרוחבו\u0004 — הריהו \u0003טהור,\u0004 ששוב אינו בר שימוש, שכן בכל דרך שהיא אין אפשרות לשפות עליו אף קדירה אחת. והרי למדים אנו מכאן מה ההבדל בין הכופח והכירה.","על ההלכות הדנות בבישול ממש על גבי אש בשבת הוסיפו הלכות אחדות בדברים הקרובים לנושא זה. ואמרו: \u0003אין נותנין ביצה חיה\u0004 (בלתי מבושלת) \u0003בצד המיחם\u0004 המלא מים חמים \u0003בשביל שתתגלגל\u0004 (תתבשל מעט). \u0003ו\u0004אף \u0003לא יפקיענה בסודרין,\u0004 כלומר, שלא יחמם אותה בתוך סודר שהתחמם קודם בשמש. \u0003ור' יוסי מתיר\u0004 במקרה זה. \u0003ו\u0004כמו כן \u0003לא יטמיננה בחול\u0004 או \u0003באבק דרכים\u0004 שנתחממו בשמש \u0003בשביל שתצלה,\u0004 כי אף שאין כאן בישול באש ממש, מכל מקום הדבר דומה לבישול כזה, וגזרו חכמים שלא לעשות כן.","לחיזוק הדברים מביאים \u0003מעשה שעשו אנשי\u0004 העיר \u0003טבריא\u0004 (טבריה) \u0003והביאו סילון\u0004 (צינור) \u0003של צונן לתוך אמה\u0004 (תעלה) \u0003של\u0004 מים \u0003חמין\u0004 מחמי טבריא, וחשבו שבאופן זה יוכלו לחמם את המים הצוננים הראויים לשתיה אף בשבת. \u0003אמרו להם חכמים: אם\u0004 העבירו את המים \u0003בשבת\u0004 הרי דינם \u0003כחמין שהוחמו בשבת, ואסורין\u0004 המים לשימוש הן \u0003ברחיצה ו\u0004הן \u0003בשתיה.\u0004 ו\u0003אם\u0004 העבירו את הסילון \u0003ביום טוב\u0004 — הרי דינם \u0003כחמין שהוחמו ביום טוב, ואסורין ברחיצה, ו\u0004אולם \u0003מותרין בשתיה,\u0004 שהרי ביום טוב מותר לבשל ולחמם מים באש ממש לצורך שתיה ואכילה.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 לתלמידים שאלה זו\u0005]:\u0006 עבר אדם על דברי המשנה ו\u0003גלגל\u0004 ביצה בסודר \u0003מאי\u0004 \u0005[מה\u0006 דינו\u0005]?\u0006 \u0003אמר רב יוסף: גלגל\u0004 — \u0003חייב חטאת,\u0004 שהדבר נחשב למלאכת בישול שנעשתה בשבת, והאסורה מן התורה. \u0003אמר מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רבינא: אף אנן נמי תנינא\u0004 \u0005[אנחנו שנינו גם כן]\u0006 מעין דברים אלה במשנה:"],["\u0003כל\u0004 דבר מלוח \u0003שבא\u0004 (נתבשל) כבר \u0003בחמין מלפני השבת\u0004 — \u0003שורין אותו בחמין\u0004 אף \u0003בשבת, וכל ש\u0004עדיין \u0003לא בא בחמין מלפני השבת\u0004 — \u0003מדיחין\u0004 (רוחצים) \u0003אותו בחמין בשבת,\u0004 אך אין שורים. \u0003חוץ מן המליח\u0004 ה\u0003ישן\u0004 או הדג \u0003קולייס האיספנין שהדחתן\u0004 בחמין \u0003זו היא גמר מלאכתן,\u0004 שאם מדיחן בחמין הרי זה כאילו בישלם בשבת, לפי שאינם צריכים לבישול נוסף. ומכאן נלמד לענייננו, שביצה שנתגלגלה, כיון שנעשתה בכך ראויה לאכילה הרי עובר בכך משום בישול. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכן היא משמעות הדברים.","שנינו במשנה שלדעת התנא הראשון \u0003לא יפקיענה\u0004 (יעטוף אותה) את הביצה \u0003בסודרין\u0004 שנתחממו בשמש כדי לחממה, ור' יוסי מתיר. ושואלים: \u0003והא דתנן\u0004 \u0005[וזו ששנינו\u0006 במשנה\u0005]\u0006 \u0003נותנין תבשיל לתוך הבור\u0004 בשבת \u0003בשביל שיהא שמור\u0004 מן החום, \u0003ו\u0004כן נותנים \u0003את המים היפים\u0004 (הטובים) לשתיה \u0003ב\u0004תוך המים ה\u0003רעים\u0004 (שאינם ראיים לשתיה) \u0003בשביל שיצננו\u0004 בתוכם. \u0003ו\u0004כן \u0003את הצונן\u0004 (מים צוננים) מותר להניח \u0003בחמה בשביל שיחמו\u0004 המים. \u0003לימא\u0004 \u0005[האם נאמר]\u0006 שמשנה זו כשיטת \u0003ר' יוסי\u0004 במשנתנו \u0003היא ולא\u0004 כשיטת \u0003רבנן\u0004 \u0005[חכמים,\u0006 התנא הראשון\u0005]?\u0006","שהרי חכמים אסרו לחמם דברים מכוח השמש! \u0003אמר רב נחמן: בחמה\u0004 עצמה — \u0003דכוליה עלמא לא פליגי דשרי\u0004 \u0005[הכל אינם חלוקים\u0006 ודעתם \u0005שמותר]\u0006 להניח דברים לחמם בה, שהרי ודאי אין זו אש, ואין זו דרך בישול. \u0003וכן בתולדות האור\u0004 (האש), דברים שנתחממו מכוח האש \u0003כוליה עלמא לא פליגי דאסיר\u0004 \u0005[הכל אינם חלוקים שאסור]\u0006 לחמם בהם, שהמחמם בהם הרי הוא כמבשל באש עצמה. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה \u0003בתולדות החמה\u0004 (בדברים שנתחממו מחום השמש). \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 חכמים \u0005סבור]\u0006 כי \u0003גזרינן\u0004 \u0005[גוזרים אנו\u0006 לאסור\u0005]\u0006 חימום באמצעות \u0003תולדות החמה אטו\u0004 \u0005[משום]\u0006 \u0003תולדות האור\u0004 \u0005[האש]\u0006 שהן אסורות, שהרי אין הרואים יודעים במה נתחמם כלי הבשול, ואם יתירו את השימוש בתולדות החמה יבואו להתיר את השימוש אף בתולדות האור. \u0003ומר סבר\u0004 \u0005[וחכם זה\u0006 ר' יוסי \u0005סבור]\u0006 כי \u0003לא גזרינן\u0004 \u0005[אין אנו גוזרים],\u0006 ואף שאסור לחמם בתולדות האור, מותר לחמם בתולדות החמה.","שנינו במשנה: \u0003ולא יטמיננה\u0004 לביצה \u0003בחול\u0004 ובאבק דרכים שהם חמים. ושואלים: \u0003וליפלוג נמי\u0004 \u0005[ושיחלוק גם כן]\u0006 \u0003ר' יוסי בהא\u0004 \u0005[ב\u0006הלכה \u0005זו],\u0006 שהרי אם סבור הוא שמותר לבשל בשבת בדברים שנתחממו על ידי השמש, הרי יש להתיר גם חימום על ידי חול! לכך נתנו שתי תשובות. \u0003רבה אמר:\u0004 אף ר' יוסי מקבל דעת חכמים במקרה זה, לפי ש\u0003גזרה\u0004 גזרו חכמים על דבר זה מתוך החשש שאם יתירו לו להטמין בחול ובאבק דרכים \u0003שמא\u0004 יבוא ו\u0003יטמין ברמץ\u0004 (אפר חם) שזהו ודאי איסור גמור, לפי שההטמנה בחול וההטמנה ברמץ נראות דומות מאד. ואילו \u0003רב יוסף אמר:\u0004 ר' יוסי מסכים לאסור במקרה זה \u0003מפני ש\u0004בשעה שטומנו בחול הריהו \u0003מזיז עפר ממקומו\u0004 והרי זה כחופר בחול, ואסור. ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל למעשה \u0005ביניהם]?\u0006 שהרי לכאורה שני ההסברים מגיעים למסקנה מעשית אחת. ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל למעשה במקרה של \u0003עפר תיחוח.\u0004 שבעפר זה אין צורך בחפירת גומה ומטעם זה אין לאסור. ואילו גזירה משום הטמנה ברמץ עדיין קיימת כאן.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא, ש\u0003רבן שמעון בן גמליאל אומר: מגלגלין ביצה על גבי גג רותח\u0004 שנתחמם מכוח השמש, \u0003ו\u0004אולם \u0003אין מגללין ביצה על גבי סיד רותח.\u0004 ומעתה, \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 כי הטמנה בחול אסורה משום \u0003גזרה שמא יטמין ברמץ\u0004 — על גג \u0003ליכא למיגזר\u0004 \u0005[אין לגזור],\u0006 שאין זה דומה להטמנה ברמץ. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 שהטעם הוא \u0003מפני שמזיז עפר ממקומו, ליגזר\u0004 \u0005[יגזור]\u0006 ויאסור גם על גבי הגג, שלעיתים יש עליו מעט עפר. ומשיבים: אין זו קושיה, כי \u0003סתם גג לית ביה\u0004 \u0005[אין בו]\u0006 \u0003עפר,\u0004 ואין מקום לגזור משום מקרה שאינו מצוי.","כיון שנדחתה ההוכחה \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון אחר לדבר ממה שסופר במשנתנו: \u0003מעשה שעשו אנשי טבריא והביאו סילון\u0004 (צינור) \u0003של צונן לתוך אמה של חמין\u0004 ואסרו להם חכמים להשתמש בצינורם. \u0003בשלמא למאן דאמר\u0004 \u0005[נניח לשיטת האומר]\u0006 שהאיסור הוא משום \u0003גזרה שמא יטמין ברמץ\u0004 — \u0003היינו דדמיא\u0004 \u0005[זוהי\u0006 הסיבה שנאסר הדבר משום \u0005שדומה]\u0006 היא \u0003להטמנה,\u0004 שכן מכניסים את המים הצוננים (כעין הטמנה) בתוך מים חמים יותר. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 שהטעם הוא \u0003מפני שמזיז עפר ממקומו מאי איכא למימר\u0004 \u0005[מה יש לומר]\u0006 להסברת הדבר?","ומשיבים: \u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006 כי \u0003מעשה טבריא\u0004 (טבריה) \u0003אסיפא קאי\u0004 \u0005[על סופה\u0006 של המשנה הוא \u0005עומד,\u0006 מתייחס\u0005]?\u0006 לא, אלא \u0003ארישא קאי\u0004 \u0005[על ראשה\u0006 הוא \u0005עומד,\u0006 מתייחס\u0005].\u0006 וכך יש להבין את הדברים: \u0003לא יפקיענה בסודרין ורבי יוסי מתיר\u0004, נחלקו חכמים ור' יוסי בענין הפקעה בסודרים, \u0003והכי קאמרי ליה רבנן\u0004 \u0005[וכך אמרו לו חכמים]\u0006 לר' יוסי: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003מעשה\u0004 זה שהיה ב\u0003אנשי טבריא\u0004 ב\u0003תולדות חמה הוא\u0004 שהיה, שהרי לא נתחממו חמי טבריה בחום האש, \u0003ו\u0004אף על פי כן \u0003אסרי להו רבנן\u0004 \u0005[אסרו להם חכמים]!\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 ר' יוסי: אין הדבר כן אלא המעשה \u0003ההוא\u0004 ב\u0003תולדות\u0004 ה\u0003אור הוא\u0004 שהיה, שכן חמי טבריה חמים הם משום \u0003דחלפי אפיתחא דגיהנם\u0004 \u0005[ש\u0006הם \u0005חולפים על פתח הגיהנם\u0006 ומתחממים מאשו\u0005]\u0006 ולמעשה הם מתחממים מאש של ממש, אלא שהיא אש תת־קרקעית, מה שאין כן בחמה.","באותי ענין \u0003אמר רב חסדא:\u0004"],["\u0003ממעשה\u0004 זה \u0003שעשו אנשי טבריא ואסרי להו רבנן\u0004 \u0005[ואסרו\u0006 \u0005להם חכמים]\u0006 למדנו להלכה כי \u0003בטלה\u0004 ואסורה \u0003הטמנה\u0004 של קדירה בשבת \u0003בדבר המוסיף הבל\u0004 (חום) במשך השבת, \u0003ו\u0004לא נאסרה רק ביום השבת עצמו \u0003אלא אפילו מבעוד יום.\u0004 שהרי העברת הסילונות הצוננים במים המתחממים והולכים דומה בכל להטמנה בחומר המוסיף הבל. \u0003אמר עולא: הלכה כאנשי טבריא. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן: כבר תברינהו אנשי טבריא לסילונייהו\u0004 \u0005[כבר שברו אנשי טבריה את צינורותיהם]\u0006 ואף הם חזרו בהם.","שנינו במשנה את ה\u0003מעשה שעשו אנשי טבריא,\u0004 והוזכר בדרך אגב שהמים שנתחממו בחמי טבריה דינם כחמין שהוחמו בשבת ואסורים ברחיצה. ומבררים את הענין: \u0003מאי\u0004 \u0005[מה,\u0006 מאיזה סוג\u0005]\u0006 היא \u0003רחיצה\u0004 זו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהמדובר ב\u0003רחיצת כל גופו\u0004 — \u0003אלא\u0004 אם כן יש לתמוה שמכאן משמע שרק \u0003חמין שהוחמו בשבת הוא\u0004 ש\u0003אסורין\u0004 ברחיצה כזו, \u0003הא\u0004 \u0005[הרי,\u0006 אבל\u0005]\u0006 \u0003חמין שהוחמו מערב שבת מותרין,\u0004 והדבר לא יתכן, שכן \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003חמין שהוחמו מערב שבת, למחר רוחץ בהן\u0004 את \u0003פניו ידיו ורגליו, אבל לא\u0004 את \u0003כל גופו! אלא\u0004 יש לומר כי הרחיצה שנאסרה במשנה במים שהוחמו בשבת אכן היתה רחיצת \u0003פניו ידיו ורגליו.\u0004","ואולם אם כן \u0003אימא סיפא\u0004 \u0005[אמור את סופה\u0006 של המשנה\u0005],\u0006 ששנינו בה שאם היה זה \u0003ביום טוב,\u0004 הרי דין המים \u0003כחמין שהוחמו ביום טוב\u0004 באמצעות האש, \u0003ואסורין ברחיצה ומותרין בשתיה,\u0004 הרי שאף ביום טוב אסורה רחיצת פניו ידיו ורגליו בחמין אלה. אם כן \u0003לימא תנן סתמא\u0004 \u0005[האם לומר שנשנתה סתם משנה]\u0006 \u0003כ\u0004שיטת \u0003בית שמאי? דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003בית שמאי אומרים: לא יחם אדם חמין לרגליו\u0004 ביום טוב \u0003אלא אם כן ראויין\u0004 הם אף \u0003לשתיה, ובית הלל מתירין.\u0004 הרי שמותר לדעת בית הלל לחמם מים ביום טוב לצורך רחיצת רגלים, ולפי הפירוש שפירשנו את המלה \"רחיצה\" במשנה (פניו ידיו ורגליו), נמצא שמשנתנו היא כדעת בית שמאי. והדבר תמוה ביותר, שכן נדחתה שיטה זו מן ההלכה ואינה מוזכרת אלא לעתים רחוקות כמשנה סתמית!","\u0003אמר רב איקא בר חנניא:\u0004 במים שהוחמו \u0003להשתטף\u0004 (לשטוף) \u0003בהן\u0004 את \u0003כל גופו עסקינן\u0004 \u0005[עוסקים אנו]\u0006 במשנתנו, ודבר זה אין דינו כרחיצה, \u0003ו\u0004מה ששנינו במשנה שאלה שהוחמו בשבת אסורים ברחיצה ומשמע שאלה שהוחמו בערב שבת מותרים ברחיצה בשבת, הרי כשיטת \u0003האי תנא\u0004 \u0005[תנא זה]\u0006 \u0003הוא,\u0004 שיטת ר' שמעון בתוספתא. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בתוספתא\u0005]:\u0006 \u0003לא ישתטף אדם כל גופו בין בחמין\u0004 אף שהוחמו מערב שבת \u0003ובין בצונן,\u0004 אלו \u0003דברי ר' מאיר,\u0004 ו\u0003ר' שמעון מתיר\u0004 בשניהם, אף בחמים, כיון שהוחמו מערב שבת. \u0003ר' יהודה אומר: בחמין\u0004 — \u0003אסור, בצונן\u0004 — \u0003מותר.\u0004 ולדעת ר' שמעון במים שהוחמו בשבת עצמה אסורה הרחיצה כלל, ואם כן משנתנו שאינה מבחינה בין חמין וצונן כשיטת ר' שמעון היא.","\u0003אמר רב חסדא: מחלוקת\u0004 זו שאמרו בענין רחיצה במים שהוחמו מערב שבת, הרי היא דווקא \u0003בכלי,\u0004 שהיו המים החמים בתוך כלי, שאז אפשר לחשוב שחממו אותם בשבת, ויש לחשוש שיבואו להתיר מים שנתחממו בשבת על גבי האש. \u0003אבל\u0004 כאשר אותם מים נמצאים \u0003בקרקע\u0004 — ל\u0003דברי הכל מותר.\u0004 על כך מקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003מעשה\u0004 זה ב\u0003אנשי טבריא בקרקע הוה\u0004 \u0005[היה]\u0006 \u0003ו\u0004עם כל זה \u0003אסרי להו רבנן\u0004 \u0005[אסרו להם חכמים]!\u0006 \u0003אלא אי איתמר, הכי איתמר\u0004 \u0005[אם נאמר\u0006 הדבר בנושא זה, \u0005כך נאמר]\u0006 וזו היא הגרסה הנכונה: \u0003מחלוקת\u0004 זו היא דווקא כאשר המים נמצאים \u0003בקרקע, אבל\u0004 כאשר הם \u0003ב\u0004תוך \u0003כלי\u0004 — ל\u0003דברי הכל אסור.\u0004","\u0003אמר רבה בר בר חנה אמר ר' יוחנן: הלכה\u0004 במחלוקת זו \u0003כר' יהודה. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יוסף:\u0004 האם \u0003בפירוש שמיע לך\u0004 \u0005[שמעת]\u0006 דברי ר' יוחנן אלה, \u0003או מכללא שמיע לך\u0004 \u0005[מכלל\u0006 דברים אחרים שאמר \u0005שמעת]?\u0006 ומעירים: \u0003מאי כללא\u0004 \u0005[ומהם\u0006 דברי ר' יוחנן \u0005מכללם]\u0006 אפשר היה להוציא ממנו מסקנה כזו? — ש\u0003אמר רב תנחום\u0004 שכך \u0003אמר ר' יוחנן\u0004 שכך \u0003אמר ר' ינאי\u0004 שכך \u0003אמר רב: כל מקום שאתה מוצא שנים חלוקין\u0004 וכל אחד מהם קובע דעתו בשורה של מקרים, \u0003ואחד\u0004 החכמים, שלישי, \u0003מכריע\u0004 ואומר שבמקצת הדברים הלכה כאחד מהם, ובמקצתם הלכה כחבירו — \u0003הלכה כדברי המכריע. חוץ מ\u0004המקרה של \u0003קולי מטלניות\u0004 (היתר השמוש בטהרה בבלויי מטליות), \u0003שאף על פי שר' אליעזר מחמיר ור' יהושע מיקל, ור' עקיבא מכריע\u0004 — \u0003אין הלכה כדברי המכריע.\u0004 וטעמו של דבר — \u0003חדא\u0004 \u0005[\u0006טעם \u0005אחד]:\u0006 ש\u0003ר' עקיבא תלמיד הוא\u0004 ואין כוחו גדול עד כדי הכרעה בין רבותיו. \u0003ועוד: הא\u0004 \u0005[הרי]\u0006"],["\u0003הדר ביה\u0004 \u0005[חזר בו]\u0006 \u0003ר' עקיבא לגביה\u0004 \u0005[אצלו,\u0006 לשיטתו\u0005]\u0006 של \u0003ר' יהושע.\u0004 ואף במחלוקת שבדיני רחיצה צריך היה לפסוק כשיטת ר' יהודה כיון שהוא המכריע, ולכן שאל רב יוסף אם הפסק כר' יהודה לא נסמך רק על כלל זה. ושואלים: \u0003ואי מכללא, מאי\u0004 \u0005[ואם\u0006 למדנו הלכה זו \u0005מן הכלל, מה\u0006 הפגם בדבר\u0005]?\u0006 הרי יפה אפשר להסיק דברים אלה מן הכלל! ומשיבים: \u0003דילמא הני מילי במתניתין\u0004 \u0005[שמא דברים אלה\u0006 אמורים שיש תוקף לכלל \u0005רק במשנתנו],\u0006 \u0003אבל בברייתא\u0004 — \u0003לא\u0004 שמא אין הברייתא מהימנת למדי כדי לסמוך הכרעות הלכתיות על סגנונה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה בר בר חנה לרב יוסף: \u0003אנא בפירוש שמיע לי\u0004 \u0005[אני בפירוש שמעתי\u0006 דבר זה\u0005]\u0006.","\u0003אתמר\u0004 \u0005[נאמר]\u0006 שיש מחלוקת אמוראים בדבר: \u0003חמין שהוחמו מערב\u0004 שבת, \u0003רב אמר: למחר\u0004 ביום השבת \u0003רוחץ בהן כל גופו,\u0004 ואולם לא כאחד, אלא כל \u0003אבר\u0004 ו\u0003אבר\u0004 לעצמו, כדי לעשות שינוי ולהזכיר ששבת היום. \u0003ושמואל אמר: לא התירו לרחוץ\u0004 בחמין אף שהוחמו מערב שבת \u0003אלא\u0004 רק את \u0003פניו ידיו ורגליו,\u0004 אבל לא את כל גופו. \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו: \u0003חמין שהוחמו מערב שבת, למחר רוחץ בהן פניו ידיו ורגליו אבל לא כל גופו.\u0004 והרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על \u0003רב! אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רב:\u0004 מה שנאמר בברייתא \u0003\"לא כל גופו\"\u0004 כוונתו לא כל גופו \u0003בבת אחת, אלא אבר אבר\u0004 לעצמו. ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"פניו ידיו ורגליו\" קתני\u0004 \u0005[שנה]\u0006 ולא יותר! ומשיב רב: הכוונה היא שרוחץ אבר אבר, \u0003כעין פניו ידיו ורגליו,\u0004 שכל אחד מהם הוא אבר נפרד לעצמו, והובאו אלה כדי לשמש דוגמא לרחיצת אבר אבר. ושוב מנסים להביא ראייה ממקור אחר.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בברייתא: \u0003לא התירו לרחוץ בחמין שהוחמו מערב שבת אלא פניו ידיו ורגליו,\u0004 וקשים הדברים לרב! ומשיב רב: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 כפי שאמרנו קודם, הכוונה היא שרוחץ אבר אבר, \u0003כעין פניו ידיו ורגליו.\u0004","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003שמואל: חמין שהוחמו מערב שבת, למחר רוחץ בהן פניו ידיו ורגליו, אבל לא\u0004 את \u0003כל גופו\u0004 ואפילו \u0003אבר אבר. ואין צריך לומר\u0004 שהוא הדין ב\u0003חמין שהוחמו ביום טוב. רבה מתני לה להא שמעתא\u0004 \u0005[היה שונה הלכה זו]\u0006 של \u0003רב בהאי לישנא\u0004 \u0005[בלשון זו]:\u0006 \u0003חמין שהוחמו מערב שבת\u0004 רוצה לרחוץ בהם \u0003למחר, אמר רב: רוחץ בהן כל גופו ומשייר אבר אחד\u0004 כדי לזכור ששבת היום. \u0003איתיביה כל הני תיובתא\u0004 \u0005[הקשה עליו כל אותן הקושיות]\u0006 שהקשינו על הגרסה הקודמת של דברי רב, ומסכמים: \u0003תיובתא\u0004 \u0005[\u0006אכן \u0005קושיה חמורה]\u0006 היא.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יוסף לאביי: רבה מי קא עביד כשמעתיה\u0004 \u0005[האם הוא עושה,\u0006 נוהג \u0005כהלכתו]\u0006 זו של \u0003רב? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא ידענא\u0004 \u0005[איני יודע].\u0006 ושואלים: \u0003מאי תיבעי ליה\u0004 \u0005[מה תסתפק לו]?\u0006 \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 ש\u0003לא עביד\u0004 \u0005[עשה]\u0006 רבה כדברי רב, \u0003דהא איתותב\u0004 \u0005[שהרי הושארו דבריו\u0006 של רב \u0005בקושיה חמורה].\u0006 ומשיבים: \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003לא שמיעא ליה\u0004 \u0005[שמע,\u0006 ידע\u0005],\u0006 או לא החשיב את הקושיות הללו, ולדעתו אם כן עדיין יתכן לפסוק כדברי רב.","ואומרים: אם כן, הרי שוב אין מקום לשאלה, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא שמיעא ליה\u0004 \u0005[שמע]\u0006 קושיה זו — \u0003ודאי עביד\u0004 \u0005[עשה]\u0006 כרב. שכן \u0003אמר אביי: כל מילי דמר עביד\u0004 \u0005[הדברים של אדוני,\u0006 רבה, \u0005היה עושה,\u0006 נוהג\u0005]\u0006 \u0003כ\u0004שיטת \u0003רב, בר מהני תלת דעביד\u0004 \u0005[חוץ משלושה אלה שעשה]\u0006 \u0003כ\u0004שיטת \u0003שמואל.\u0004 ש\u0003מטילין\u0004 ומעבירים את הציצית \u0003מבגד לבגד, ומדליקין\u0004 בנרות חנוכה \u0003מנר לנר, ו\u0004מה שפסק \u0003הלכה כר' שמעון\u0004 בדיני שבת \u0003בגרירה,\u0004 שלדעתו מותר לגרור כלים כבדים, ואין לחשוש שמא יתהווה חריץ בקרקע מחמת כן. ומכל מקום ודאי מסתבר לומר שנהג כמו רב גם בענין הרחיצה בשבת, שכן הלכה כמותו אף בענין זה! ומשיבים: שאין זו ראייה גמורה, כי שמא נהג רבה, ש\u0003כחומרי\u0004 \u0005[כחומרותיו]\u0006 של \u0003רב\u0004 — \u0003עביד\u0004 \u0005[עשה],\u0006 \u0003כקולי\u0004 \u0005[כהקלותיו]\u0006 של \u0003רב\u0004 — \u0003לא עביד\u0004 \u0005[עשה],\u0006 והרי ההיתר לרחוץ בחמין בשבת הוא מן ההקלות של רב, ואם כן לא ברור כיצד נהג רבה למעשה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003מרחץ שפקקו\u0004 את \u0003נקביו\u0004 (פתחיו) \u0003מערב שבת,\u0004 כדי שלא יפוג חומו, \u0003למוצאי שבת רוחץ בו מיד.\u0004 ואם \u0003פקקו נקביו מערב יום טוב, למחר\u0004 ביום טוב עצמו \u0003נכנס ומזיע\u0004 בהבל המים החמים, \u0003ויוצא ומשתטף\u0004 במים צוננים \u0003בבית\u0004 (בחדר) \u0003החיצון\u0004 של בית המרחץ.","\u0003אמר ר' יהודה: מעשה במרחץ של בני ברק שפקקו נקביו מערב יום טוב, למחר\u0004 ביום טוב \u0003נכנס ר' אלעזר בן עזריה ור' עקיבא והזיעו בו ויצאו ונשתטפו בבית החיצון. אלא\u0004 שמרחץ זה מיוחד היה לפי \u0003ש\u0004המים ה\u0003חמין שלו\u0004 היו \u0003מחופין\u0004 (מכוסים) \u0003בנסרים\u0004 של עץ, ולא היה מקום לחשוש שמא ירחצו במים החמים. \u0003כשבא הדבר לפני חכמים אמרו: אף על פי שאין חמין שלו מחופין בנסרין\u0004 מותר להזיע בהבל המרחץ. \u0003ומשרבו עוברי עבירה התחילו לאסור.\u0004 ואולם \u0003אמבטיאות\u0004 שהן מרחצאות גדולים \u0003של כרכין\u0004 — \u0003מטייל בהן\u0004 כדרכו \u0003ואינו חושש\u0004 לאיסורי שבת, אף בתוך כך הוא מזיע בתוכן.","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 הם\u0005]\u0006 \u0003\"עוברי עבירה\"\u0004 שאמרנו? ומשיבים: ש\u0003אמר ר' שמעון בן פזי אמר ר' יהושע בן לוי משום\u0004 (בשם) \u0003בר קפרא: בתחילה היו רוחצין בחמין שהוחמו מערב שבת\u0004 אף בשבת, ו\u0003התחילו הבלנים להחם בשבת,\u0004 ומשקרים היו \u0003ואומרים: מערב שבת הוחמו.\u0004 על כן \u0003אסרו את ה\u0004רחיצה ב\u0003חמין והתירו את הזיעה. ועדיין היו\u0004 אנשים \u0003רוחצין בחמין ואומרים: \"מזיעין אנחנו\",\u0004 ולשם כך נכנסנו למרחץ. ולכן \u0003אסרו להן\u0004 אף \u0003את הזיעה\u0004 אך \u0003התירו\u0004 לרחוץ ב\u0003חמי טבריה. ועדיין היו רוחצין בחמי האור\u0004 \u0005[מים חמים שנתחממו באש],\u0006 \u0003ואומרים: בחמי טבריה רחצנו.\u0004 ולכך \u0003אסרו להן\u0004 אף \u0003חמי טבריה. ו\u0004עדיין נשאר ש\u0003התירו להן את הצונן. ראו שאין הדבר עומד להן,\u0004 כי אין גזירות אלה מתקיימות בידי הציבור מפני חומרתן, \u0003התירו להן\u0004 לרחוץ ב\u0003חמי טבריה\u0004 והגזירה על איסור \u0003זיעה במקומה עומדת.\u0004","ובהקשר לכך \u0003אמר רבא: האי מאן דעבר אדרבנן, שרי למיקרי ליה \"עבריינא\"\u0004 \u0005[מי שעובר על דברי חכמים, מותר לקרא לו \"עבריין\"],\u0006 ואין אומרים שרק מי שעבר עבירה חמורה על דברי תורה ממש הוא שקוראים לו כך. ומעירים: \u0003כמאן\u0004 \u0005[כמי]\u0006 אמר רבא דברים אלה —"],["\u0003כי האי תנא\u0004 \u0005[כמו תנא זה]\u0006 ששנינו דבריו בברייתא, כשקורא לאלה שעברו על תקנת חכמים: \"עוברי עבירה\".","בתוספתא שנינו ש\u0003אמבטיאות של כרכים מטייל בהן ואינו חושש\u0004 אף אם בתוך כך הוא מזיע. \u0003אמר רבא:\u0004 זהו \u0003דוקא\u0004 באמבטיאות של \u0003כרכין, אבל\u0004 של \u0003כפרים\u0004 — \u0003לא. מאי טעמא\u0004 \u0005[מה טעם\u0006 ההבדל\u0005]\u0006 — \u0003כיון דזוטרין נפיש הבלייהו\u0004 \u0005[שקטנים\u0006 הם \u0005מרובה הבלם],\u0006 ואף בדרך הילוך בלבד אפשר להגיע בהם לידי זיעה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 \u0003מתחמם אדם כנגד המדורה\u0004 בשבת, \u0003ויוצא\u0004 ממקומו, \u0003ומשתטף\u0004 אחר כך \u0003בצונן. ובלבד שלא ישתטף בצונן\u0004 תחילה \u0003ויתחמם\u0004 אחר כך \u0003כנגד המדורה.\u0004 וטעם האיסור: \u0003מפני שמפשיר\u0004 (מחמם עד כדי פושרים) את ה\u0003מים שעליו.\u0004 ועוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מיחם אדם\u0004 החש במיעיו \u0003אלונטית\u0004 \u0005[מגבת]\u0006 \u0003ומניחה על בני מעים\u0004 שלו אף \u0003בשבת, ובלבד שלא יביא קומקומוס של מים חמין ויניחנו על בני מעים בשבת\u0004 שמא ישפכו המים ויבוא לסוחטם (תוספות) ויעשה דבר האסור בשבת. \u0003ודבר זה אפילו בחול אסור, מפני\u0004 חשש \u0003הסכנה,\u0004 שאם המים חמים ביותר עשויים הם לגרום כוויה לכשישפכו עליו.","מעין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מביא אדם קיתון\u0004 (ספל קטן) מלא \u0003מים ומניחו כנגד המדורה\u0004 בשבת. \u0003לא בשביל שיחמו\u0004 המים, שהרי אסור לבשל בשבת, \u0003אלא בשביל שתפיג צינתן,\u0004 שמותר לגרום למים שלא יהיה קרים כל כך בשבת. \u0003ר' יהודה אומר: מביאה אשה פך של שמן ומניחתו כנגד המדורה. לא בשביל שיבשל\u0004 (יתבשל) השמן, \u0003אלא בשביל שיפשר. רבן שמעון בן גמליאל אומר: אשה סכה ידה\u0004 ב\u0003שמן ומחממתה\u0004 אחר כך \u0003כנגד המדורה, וסכה\u0004 אחר כך בשמן מחומם זה \u0003לבנה\u0004 ה\u0003קטן, ואינה חוששת\u0004 משום בישול בשבת.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 לבני הישיבה\u0005]\u0006 שאלה זו: חימום \u0003שמן\u0004 בדרך זו בשבת \u0003מה הוא\u0004 דינו \u0003לתנא קמא\u0004 \u0005[הראשון]\u0006 המתיר במים, האם גם בו התיר? \u0003רבה ורב יוסף דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 שדעת התנא הראשון \u0003להתירא\u0004 \u0005[להתיר]\u0006 בשמן, \u0003רב נחמן בר יצחק אמר\u0004 שדעת התנא הראשון \u0003לאיסורא\u0004 \u0005[לאסור].\u0006 ולהבנת הדברים מסבירים: \u0003רבה ורב יוסף דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 שדעת התנא הראשון \u0003להתירא\u0004 \u0005[להתיר].\u0006 מסבירים את המשנה כך: \u0003שמן אף על פי\u0004 שהתחמם עד כדי \u0003שהיד סולדת בו\u0004 (שהיד נרתעת ממנו מפני חומו) — \u0003מותר.\u0004 וטעמו של דבר, כי \u0003סבר\u0004 \u0005[סבור]\u0006 ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 ש\u0003שמן אין בו משום בשול,\u0004 שכדי לבשל שמן עד כדי רתיחה יש צורך בחום גבוה מאד, וחימום בלבד אין בו משום בישול. \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003ר' יהודה למימר\u0004 \u0005[לומר]\u0006 ש\u0003שמן יש בו משום בשול, ו\u0004אולם \u0003הפשרו לא זה הוא בשולו.\u0004 ועל כן מותר להניח פך שמן כנגד המדורה כדי להפשירו, אף שאסור לחממו לכדי בישול. \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003רבן שמעון בן גמליאל למימר\u0004 \u0005[לומר]\u0006 ש\u0003שמן יש בו משום בשול, והפשרו זהו בשולו.\u0004 והתיר רק במקרה המיוחד שהאשה סכה ידה בשמן, ומחממתה וסכה בו את בנה.","ואילו \u0003רב נחמן בר יצחק אמר:\u0004 שדעת התנא הראשון היא \u0003לאיסורא\u0004 \u0005[לאיסור],\u0006 והוא מפרש את המחלוקת בצורה הבאה: לדעת התנא הראשון \u0003שמן אף על פי שאין היד סולדת בו,\u0004 שעדיין ניתן לגעת בו על אף חומו — \u0003אסור\u0004 לחממו יותר. \u0003קסבר\u0004 \u0005[סבור]\u0006 ש\u0003שמן יש בו משום בשול, והפשרו זהו בשולו. ואתא\u0004 \u0005[ובא]\u0006 \u0003ר' יהודה\u0004 להקל ו\u0003למימר\u0004 \u0005[לומר]\u0006 ש\u0003הפשרו לא זהו בשולו. ואתא\u0004 \u0005[ובא]\u0006 \u0003רבן שמעון בן גמליאל\u0004 לחלוק על ר' יהודה ו\u0003למימר\u0004 \u0005[לומר]\u0006 ש\u0003שמן יש בו משום בשול, והפשרו זהו בשולו.\u0004 על כך מקשים: הרי לדרך הסברה זו דעת \u0003רבן שמעון בן גמליאל היינו\u0004 \u0005[זוהי]\u0006 בדיוק דעת ה\u0003תנא קמא\u0004 \u0005[הראשון],\u0006 ומה ההבדל ביניהם? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל למעשה אם עושים זאת \u0003כלאחר יד\u0004 ולא בדרך הרגילה, שלדעת תנא קמא אסור לחמם את השמן בכל צורה, ואילו לדעת רבן שמעון בן גמליאל מותר להפשירו על ידי שינוי.","להלכה \u0003אמר רב יהודה אמר שמואל: אחד שמן ואחד מים\u0004 אם מחמם אותם עד שתהא \u0003יד סולדת בו\u0004 — \u0003אסור.\u0004 ולחממו באופן ש\u0003אין יד סולדת בו\u0004 — \u0003מותר.\u0004 ושואלים: \u0003והיכי דמי\u0004 \u0005[וכיצד הוא\u0006 בדיוק\u0005]\u0006 \u0003יד סולדת בו?\u0004 שהרי אין כל הידים שוות ברגישותן לחום. \u0003אמר\u0004 החכם \u0003רחבא: כל שכריסו של תינוק נכוית\u0004 בו הוא שנקרא \"יד סולדת בו\".","מענין זה \u0003אמר רב יצחק בר אבדימי: פעם אחת נכנסתי אחר רבי לבית המרחץ\u0004 בשבת לשמשו, \u0003ובקשתי להניח לו פך של שמן באמבטי\u0004 כדי שיתחמם השמן מעט לצורך סיכה. \u0003ואמר לי: טול\u0004 מן המים שבמרחץ \u0003בכלי שני ותן\u0004 בו את השמן. ומעירים: \u0003שמע מינה תלת\u0004 \u0005[למד ממנה,\u0006 מהערתו זו של רבי, \u0005שלוש\u0006 הלכות\u0005].\u0006 \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 כי \u0003שמן יש בו משום בשול,\u0004 שמשום כך אסר להניחו באמבטי. \u0003ושמע מינה\u0004 \u0005[ולמד ממנה]\u0006 ש\u0003כלי שני\u0004 בכל מקרה אינו חם ו\u0003אינו מבשל. ושמע מינה\u0004 \u0005[ולמד ממנה]\u0006 כי בשמן \u0003הפשרו\u0004 — \u0003זהו בשולו.\u0004","על סיפור זה תוהים: \u0003היכי עביד הכי\u0004 \u0005[איך עשה\u0006 רבי \u0005כך]\u0006 להורות לתלמידו הלכה בהיותו בבית המרחץ, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבה בר בר חנה\u0004 שכך \u0003אמר ר' יוחנן: בכל מקום מותר להרהר\u0004 בדברי תורה \u0003חוץ מבית המרחץ ובית הכסא! וכי תימא\u0004 \u0005[ואם תאמר]\u0006 כי \u0003בלשון חול אמר ליה\u0004 \u0005[לו],\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003אביי: דברים של חול מותר לאומרן\u0004 אף בבית המרחץ \u0003בלשון קודש,\u0004 ודברים \u0003של קודש אסור לאומרן\u0004 במרחץ אפילו \u0003בלשון חול!\u0004 ומשיבים: \u0003אפרושי מאיסורא שאני\u0004 \u0005[להפריש מאיסור\u0006 דינו \u0005שונה],\u0006 ומותר.","\u0003תדע\u0004 שכן הוא, שכן \u0003אמר רב יהודה אמר שמואל: מעשה בתלמידו של ר' מאיר שנכנס אחריו לבית המרחץ\u0004 בשבת \u0003ובקש להדיח\u0004 את ה\u0003קרקע\u0004 לנקותה. \u0003ואמר לו\u0004 ר' מאיר: \u0003אין מדיחין\u0004 את הקרקע בשבת. ביקש התלמיד \u0003לסוך לו\u0004 את \u0003קרקע\u0004 בשמן. \u0003אמר לו: אין סכין. אלמא\u0004 \u0005[מכאן]\u0006 כי \u0003אפרושי מאיסורא שאני\u0004 \u0005[להפריש מאיסור שונה],\u0006 \u0003הכא נמי לאפרושי מאיסורא שאני\u0004 \u0005[כאן גם כן,\u0006 במקרה של רבי \u0005להפריש מאיסור שונה],\u0006 ומותר.","\u0003אמר רבינא: שמע מינה\u0004 \u0005[למד ממנה]\u0006 כי \u0003המבשל בחמי טבריה בשבת\u0004 — \u0003חייב. דהא\u0004 \u0005[שהרי]\u0006 \u0003מעשה\u0004 שהיה ב\u0003רבי לאחר גזירה הוה\u0004 \u0005[היה],\u0006 \u0003ואמר ליה\u0004 \u0005[לו]\u0006 לתלמידו: \u0003טול\u0004 מים חמים \u0003בכלי שני ותן\u0004 בו את השמן. והרי שאם היה מבשל במים החמים עצמם היה בכך איסור מדין תורה. ומאחר שמעשה רבי היה לאחר שגזרו שלא לרחוץ בשבת בחמין, מוכרחים לומר שרחיצה זו באמבטי היתה בחמי טבריה. ומקשים: \u0003איני\u0004 \u0005[וכי כן הוא]?!\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב חסדא\u0004 כי \u0003המבשל בחמי טבריה בשבת\u0004 — \u0003פטור!\u0004 ומשיבים: אין כאן סתירה, אלא \u0003מאי\u0004 \u0005[מה]\u0006 משמעות \u0003\"חייב\" נמי דקאמר\u0004 \u0005[גם כן שאמר\u0006 רבינא\u0005]\u0006 — לא שיהא חייב סקילה או קרבן חטאת על בישול בחמי טבריה כעובר על דברי תורה, אלא \u0003מכת מרדות,\u0004 שמלקים כל העובר על דברי חכמים במזיד.","\u0003אמר ר' זירא: אנא חזיתיה\u0004 \u0005[אני ראיתיו]\u0006 את \u0003ר' אבהו\u0004 ש\u0003שט באמבטי\u0004 בשבת, \u0003ולא ידענא\u0004 \u0005[ידעתי]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003עקר\u0004 רגליו ושחה ממש במים, \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא עקר.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 ש\u0003לא עקר\u0004 רגליו, \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003לא ישוט אדם\u0004 בשבת \u0003בבריכה מלאה מים, ואפילו עומדת\u0004 הבריכה \u0003בחצר\u0004 שאין מקום לחשוש לאיסור, בכל זאת אסרו חכמים! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זו]\u0006 שאסרו לשוט בשבת בבריכה הרי זה בבריכה"],["\u0003דלית ליה גידודי\u0004 \u0005[שאין לה מחיצות\u0006 סביב\u0005],\u0006 שכיון שאין לה מחיצות נראית היא כים או כנהר, \u0003הא דאית ליה גידודי\u0004 \u0005[זו שיש לה מחיצות]\u0006 שנראית ככלי — לא אסרו בה.","מכיון שעסקנו במה שסיפר ר' זירא על ר' אבהו מביאים עוד מה ש\u0003אמר ר' זירא: אנא חזיתיה\u0004 \u0005[אני ראיתיו]\u0006 את \u0003ר' אבהו ש\u0004בשעת רחיצה \u0003הניח ידיו כנגד פניו שלמטה\u0004 (ערוותו) משום צניעות, \u0003ולא ידענא אי\u0004 \u0005[ואיני יודע אם]\u0006 \u0003אי נגע אי\u0004 \u0005[אם]\u0006 \u0003לא נגע.\u0004 על כך מקשים: וכי מה מקום יש לשאול בענין זה? \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 ש\u0003לא נגע\u0004 \u0005[נגע],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 ש\u0003ר' אליעזר אומר: כל האוחז באמה\u0004 (באברו) \u0003ומשתין\u0004 — \u0003כאילו מביא מבול לעולם.\u0004 שהוא עשוי להביא עצמו לידי גירוי על ידי מגע זה וחמורה העבירה ביותר כבדור המבול.","\u0003אמר אביי:\u0004 בכל זאת אין להוכיח מכאן לענייננו, כי שמא \u0003עשאוה כ\u0004דין \u0003בולשת. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003בולשת\u0004 (יחידת צבא) \u0003שנכנסה לעיר,\u0004 אם נכנסה \u0003בשעת שלום,\u0004 הרי ה\u0003חביות\u0004 ה\u0003פתוחות\u0004 של יין שנמצאו אחר שיצאו ממנה \u0003אסורות\u0004 בשתיה כי חוששים שמא ניסכו אנשי הצבא הגויים את היין שבחביות לעבודה זרה. ואילו חביות \u0003סתומות\u0004 — \u0003מותרות.\u0004 ואולם אם נכנסה הבולשת \u0003בשעת מלחמה\u0004 — \u0003אלו ואלו מותרות.\u0004 וטעמו של דבר — \u0003לפי ש\u0004בשעת מלחמה \u0003אין פנאי לנסך\u0004 ובוודאי שלא ניסכו. \u0003אלמא\u0004 \u0005[מכאן]\u0006 כי \u0003כיון דבעיתי לא מנסכי\u0004 \u0005[ש\u0006הם \u0005מפחדים אינם מנסכים].\u0006 \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003כיון דבעית לא אתי להרהורי\u0004 \u0005[ש\u0006הוא \u0005מפחד אינו בא\u0006 לידי \u0005הרהור].\u0006 ושואלים: \u0003והכא מאי ביעתותא\u0004 \u0005[וכאן מה פחד]\u0006 יש המונע את המתרחץ מהרהור? ומשיבים: \u0003ביעתותא דנהרא\u0004 \u0005[פחד הנהר]\u0006 שכיון שעליו להיזהר שלא ישטפוהו המים, אינו מהרהר בדברים אחרים.","על עצם המעשה מקשים: \u0003איני\u0004 \u0005[וכי כן הוא]?!\u0006 האם מותר במקרה כל שהוא לכסות ערוותו כשרוחץ? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אבא\u0004 שכך \u0003אמר רב הונא\u0004 שכך \u0003אמר רב: כל המניח ידיו כנגד פניו של מטה\u0004 הריהו \u0003כאילו כופר בבריתו של אברהם אבינו,\u0004 שנראה שהוא מכסה עצמו מפני שרצונו להסתיר שהוא נימול! ומתרצים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 שכן יש לחלק ולומר כי \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שאסור לכסות הרי זה \u0003כי נחית\u0004 \u0005[כאשר\u0006 הוא \u0005יורד]\u0006 אל הנהר שאין מולו אנשים ואינו צריך לחשוש לצניעות, הרי אסור לו להראות כאילו הוא כופר בברית אברהם, \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שאין בכך באופנים מסויימים איסור הרי זה \u0003כי סליק\u0004 \u0005[כאשר\u0006 הוא \u0005עולה]\u0006 מן הנהר, כי כאשר הוא עולה ופניו מול אנשים הנמצאים על שפת הנהר מותר לו לכסות עצמו, משום צניעות, ואכן \u0003כי הא\u0004 \u0005[כמו זה]\u0006 שהיה נוהג \u0003רבא\u0004 שכאשר היה ערום היה \u0003שחי\u0004 \u0005[שוחה,\u0006 מתכופף\u0005].\u0006 ואילו \u0003ר' זירא זקיף\u0004 \u0005[היה עומד זקוף],\u0006 משום שחשש לדברי רב שאסור להיראות ככופר בברית אברהם. ואילו \u0003רבנן דבי\u0004 \u0005[החכמים מבית\u0006 מדרשו\u0005]\u0006 של \u0003רב אשי, כי קא נחתי\u0004 \u0005[כאשר היו יורדים]\u0006 לנהר — \u0003זקפי\u0004 \u0005[היו זקופים],\u0006 \u0003כי קא סלקי\u0004 \u0005[כאשר היו עולים]\u0006 ממנו — \u0003שחי\u0004 \u0005[היו שוחים,\u0006 כפופים\u0005].\u0006","וכיון שדובר ברחיצה ובדיניה, מסופר: \u0003ר' זירא הוה קא משתמיט\u0004 \u0005[היה משתמט]\u0006 שלא להפגש עם \u0003רב יהודה,\u0004 מפני \u0003דבעי למיסק לארעא דישראל\u0004 \u0005[שרצה\u0006 ר' זירא \u0005לעלות לארץ ישראל],\u0006 \u0003דאמר\u0004 \u0005[שהיה אומר]\u0006 \u0003רב יהודה: כל העולה מבבל לארץ ישראל עובר\u0004 על מצוות \u0003עשה, שנאמר: \"בבלה יובאו ושמה יהיו\u0004 עד יום פקדי אותם נאום ה', והעליתים והשבתים אל המקום הזה\u0003\"\u0004 (ירמיהו כז, כב). שלדעת רב יהודה כיון שגלות בבל היתה בדבר ה', אין רשות לעלות מבבל אלא בדבר ה' כאמור בפסוק. ולכן לא רצה ר' זירא לפגשו, כדי שלא יאמר לו רב יהודה את דעתו על העלייה לארץ ויצטרך להמרות את פיו במפורש. בכל זאת, לפני צאתו \u0003אמר: איזיל\u0004 \u0005[אלך]\u0006 \u0003ואשמע מיניה מילתא ואיתי ואיסק\u0004 \u0005[ממנו דבר ואז אעלה].\u0006 \u0003אזל אשכחיה דקאי בי באני וקאמר ליה לשמעיה\u0004 \u0005[הלך ומצאו\u0006 את רב יהודה \u0005שעומד במרחץ ואומר לשמשיו]:\u0006 \u0003הביאו לי נתר\u0004 לרחוץ בו, \u0003הביאו לי מסרק, פתחו פומייכו ואפיקו הבלא, ואשתו ממיא דבי באני\u0004 \u0005[פתחו פיכם והוציאו הבל, ושתו ממי בית המרחץ]\u0006 \u0003אמר\u0004 ר' זירא: \u0003אילמלא באתי אלא לשמוע דבר זה\u0004 מרב יהודה \u0003דיי.\u0004","ומעתה באים לנתח מה הם הדברים שאפשר היה ללמוד ממעשה זה. \u0003בשלמא\u0004 \u0005[נניח\u0006 לענין\u0005]\u0006 שאמר \u0003הביאו נתר הביאו מסרק קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 כי \u0003דברים של חול מותר לאומרם\u0004 בבית המרחץ אף \u0003בלשון קדש.\u0004 ומה שאמר \u0003פתחו פומייכו ואפיקו הבלא\u0004 \u0005[פתחו פיכם והוציאו הבל]\u0006 הרי זה \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003כ\u0004דברי \u0003שמואל,\u0004 ש\u0003אמר שמואל: הבלא מפיק הבלא\u0004 \u0005[הבל מוציא הבל],\u0006 וההבל שיכנס דרך הפה גורם לזיעה שתצא מהר יותר. \u0003אלא \"אשתו מיא דבי באני\" מאי מעליותא\u0004 \u0005[\"שתו מים של בית המרחץ\" מה המעלה\u0006 בדבר\u0005]?\u0006 ומשיבים: \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 \u0003אכל\u0004 אדם \u0003ולא שתה\u0004 כלל — \u0003אכילתו\u0004 נעשית \u0003דם, וזהו\u0004 הגורם ל\u0003תחילת חולי\u0004 ה\u0003מעיים. אכל ולא הלך ארבע אמות\u0004 אחר האוכל — \u0003אכילתו מרקבת, וזהו תחילת ריח רע\u0004 בפה. \u0003הנצרך לנקביו ואכל\u0004 — \u0003דומה לתנור שהסיקוהו על גבי אפרו,\u0004 שלא גרפו מתוכו את אפר ההסקה הקודמת אלא הניחו עצים חדשים על הישנים, והדבר מפריע לבעירה ומלכלך את התנור, ובאדם \u0003זהו תחילת ריח זוהמא,\u0004 שכל גופו מלא ריח רע. ולענייננו \u0003רחץ בחמין ולא שתה מהן דומה\u0004 הוא \u0003לתנור שהסיקוהו מבחוץ ולא הסיקוהו מבפנים,\u0004 שאין ההסקה מועלת ואינה מחממת כראוי, ומטעם זה אמר רב יהודה לשמשיו לשתות מים חמים בשעת הרחיצה, שיתחממו מבפנים ומבחוץ. ועוד ממשיכה הברייתא: \u0003רחץ בחמין ולא נשתטף\u0004 אחר כך \u0003בצונן\u0004 — \u0003דומה לברזל שהכניסוהו לאור\u0004 (אש) \u0003ולא הכניסוהו\u0004 אחר כך \u0003לצונן,\u0004 שהדבר גורם לברזל להתרכך. וכן מי ש\u0003רחץ ולא סך\u0004 בשמן אחר כך — \u0003דומה למים\u0004 שנשפכים \u0003על גבי חבית,\u0004 שאינם נכנסים בתוכה אלא נשארים מחוצה לה.","במשנה זו דנו חכמים בשני כלים ששימשו לחימום מים, ואמרו: \u0003מוליאר,\u0004 שהוא כלי נחושת ששמים בתוכו גחלים, ובצידו שמים מים, שהוא \u0003גרוף\u0004 מגחליו — \u0003שותין הימנו\u0004 (ממנו) \u0003בשבת. אנטיכי\u0004 שהיא כלי חימום הבנוי בצורה שונה, \u0003אף על פי שגרופה\u0004 היא מן הגחלים \u0003אין שותין הימנה\u0004 בשבת.","שואלים: \u0003היכי דמי\u0004 \u0005[כיצד הוא\u0006 בדיוק\u0005]\u0006 \u0003מוליאר הגרוף?\u0004 ומשיבים: \u0003תנא\u0004 מוליאר הוא הכלי שנתפרש בתוספתא למשנה, שיש בו \u0003מים מבפנים וגחלים מבחוץ.\u0004 ואילו לגבי זהותה של \u0003אנטיכי\u0004 נחלקו הדעות. \u0003רבה אמר\u0004 שהכוונה היא ל\u0003בי כירי,\u0004 כלומר, חלל שעושים בדופן כירה וממלאים אותו במים, וכיון שרב חומה של הכירה אסרו להשתמש במים אלה. \u0003רב נחמן בר יצחק אמר:\u0004 אנטיכי הוא \u0003בי דודי,\u0004 כלי המורכב משני דוודים המונחים זה על גבי זה, בתחתון גחלים, ובעליון מים. וחילוקי הגדרה אלה יש להם מסקנות הלכתיות. \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שאסור להשתמש בכלי המורכב כ\u0003בי דודי\u0004 \u0005[\u0006שני \u0005הדוודים]\u0006 \u0003כל שכן\u0004 שהוא אוסר להשתמש בחלל \u0003בי כירי\u0004 \u0005[הכיריים],\u0006 \u0003ומאן דאמר בי כירי\u0004 \u0003אבל בי דודי\u0004 \u0005[שני דוודים]\u0006 — \u0003לא\u0004 אסר. \u0003תניא כוותיה\u0004 \u0005[שנוייה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב נחמן: אנטיכי אף על פי שגרופה וקטומה אין שותין הימנה\u0004 (ממנה) בשבת \u0003מפני שנחושתה\u0004 (קרקעיתה) \u0003מחממתה,\u0004 הרי שדרך החימום באנטיכי הינה על ידי גחלים שמתחת למים.","בדיני השהייה ובישול בשבת הוסיפו חכמים: \u0003המיחם שפינהו\u0004 בשבת מן המים החמים \u0003לא יתן לתוכו צונן בשביל שיחמו\u0004 המים הצוננים. \u0003אבל נותן הוא\u0004 מים צוננים \u0003לתוכו או לתוך הכוס\u0004 שהיו בה מים חמים \u0003כדי להפשירן\u0004 ולא לחממן.","דברי המשנה נראים כסותרים זה את זה. במשפט הראשון נאסר במוחלט לשים מים במיחם, ואחר כך הותרו הדברים במקצת, ושואלים: \u0003מאי קאמר\u0004 \u0005[מה אמר]?\u0006 \u0003אמר רב אדא בר מתנא, הכי קאמר\u0004 \u0005[כן אמר,\u0006 כך התכוון לומר\u0005]:\u0006 \u0003המיחם שפינה ממנו מים חמין לא יתן לתוכן מים מועטים כדי שיחמו\u0004 המים חום רב, \u0003אבל נותן לתוכו מים מרובים\u0004 שעל ידי כך לא יוכלו המים להתחמם ממש אלא רק \u0003כדי להפשירן.\u0004"],["על עצם ההיתר מקשים: \u0003והלא\u0004 על ידי נתינת המים לתוכו הריהו \u0003מצרף\u0004 את הכלי! שהרי כלי מתכת שנתחמם ושופכים לתוכו מים קרים מתחזק על ידי המים, וזו חלק ממלאכת הצורף, וכיצד התירו לעשות מלאכה כעין זו בשבת? ומשיבים: משנה זו כדעת \u0003ר' שמעון היא\u0004 ש\u0003אמר\u0004 כלל בהלכות שבת: \u0003דבר שאין מתכוין\u0004 לעשותו, ונעשית המלאכה בלא שיתכוון לכך — \u0003מותר.\u0004 והרי אף כאן אין כוונתו לחזק את הכלי אלא לחמם את המים. \u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 \u0003אביי\u0004 על סברה זו: \u0003מידי\u0004 \u0005[וכי]\u0006 \u0003מיחם שפינה ממנו מים קתני\u0004 \u0005[שנינו]\u0006 שמזה אתה למד כי \u0005רצה למלאות בו מים אחרים כדי לחממם?!\u0006 והלא \u0003מיחם שפינהו קתני\u0004 \u0005[שנינו],\u0006 ומשמעות הדבר שפינה את המיחם מן האש ולא פינה את המים ממנו!","\u0003אלא אמר אביי, הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003המיחם שפינהו\u0004 מעל האש \u0003ויש בו מים חמין\u0004 — \u0003לא יתן לתוכו מים מועטין בשביל שיחומו\u0004 המים, \u0003אבל נותן לתוכו מים מרובים כדי להפשירן\u0004 בלבד. \u0003ומיחם שפינה ממנו מים\u0004 — \u0003לא יתן לתוכו מים כל עיקר, מפני שמצרף\u0004 את הכלי על ידי נתינת צוננים בכלי חם. \u0003ו\u0004לפי זה משנתנו כשיטת \u0003ר' יהודה היא,\u0004 ש\u0003אמר\u0004 כי אף \u0003דבר שאין מתכוין\u0004 לעשות בו מלאכה, אף אם המלאכה נעשית מעצמה \u0003אסור\u0004 לעשותו בשבת.","לגוף הדבר \u0003אמר רב: לא שנו,\u0004 שמותר לשים מים צוננים במיחם שהוסר מעל גבי האש ויש בו מים חמים \u0003אלא\u0004 כשכוונתו \u0003להפשיר\u0004 את אותם מים צוננים, \u0003אבל\u0004 אם רוצה לעשות כן כדי \u0003לצרף\u0004 את הכלי — \u0003אסור.\u0004 ואילו \u0003שמואל אמר: אפילו\u0004 כדי \u0003לצרף נמי\u0004 \u0005[גם כן]\u0006 \u0003מותר.\u0004 ותוהים: \u0003לצרף לכתחילה מי שרי\u0004 \u0005[האם מותר]?!\u0006 והלא זו מלאכה גמורה בשבת! \u0003אלא, אי איתמר הכי איתמר\u0004 \u0005[אם נאמרו\u0006 הדברים \u0005כך,\u0006 בסגנון זה, \u0005נאמרו],\u0006 \u0003אמר רב: לא שנו\u0004 שמותר להוסיף מים \u0003אלא שיעור\u0004 שיש בו רק כדי \u0003להפשיר,\u0004 וכגון שמילאהו רק בחלקו, \u0003אבל\u0004 למלאותו כולו שהוא \u0003שיעור\u0004 שיש בו כדי \u0003לצרף\u0004 את הכלי — \u0003אסור. ושמואל אמר: אפילו שיעור\u0004 שיש בו כדי \u0003לצרף\u0004 —"],["\u0003מותר,\u0004 כיון שאינו מתכוון למלאכה זו.","על הדברים הקודמים שואלים: \u0003למימרא\u0004 \u0005[האם נאמר]\u0006 כי \u0003שמואל,\u0004 המתיר להוסיף מים אפילו בכדי שיעור לצרף \u0003כ\u0004שיטת \u0003ר' שמעון\u0004 המתיר בכל מלאכה שאין מתכוין \u0003סבירא ליה\u0004 \u0005[סבור הוא]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003שמואל: מכבין גחלת של מתכת\u0004 (חתיכת מתכת לוהטת) \u0003ברשות הרבים\u0004 בשבת \u0003בשביל שלא יזוקו בה רבים.\u0004 כי המתכת הלוהטת אינה אש ממש ואין בכיבויה איסור מן התורה אלא מגזירת חכמים (\"שבות\"), ובכל מקום שיש חשש היזק לרבים לא גזרו חכמים. \u0003אבל לא\u0004 מכבים \u0003גחלת של עץ\u0004 שכיבויה אסור מן התורה. \u0003ואי סלקא דעתך סבר לה\u0004 \u0005[ואם עולה על דעתך\u0006 כי \u0005הוא סבור]\u0006 \u0003כ\u0004שיטת \u0003ר' שמעון אפילו של עץ נמי\u0004 \u0005[גם כן]\u0006 יהא מותר לכבות! שהרי בשעת כיבוי הגחלת אינו מתכוון לעשות מלאכה, או ליהנות מכיבוי זה, אלא רק למנוע את הגחלת מלהזיק והוא הנקרא \"מלאכה שאין צריכה לגופה\", והרי אמר ר' שמעון שמלאכה שאינה צריכה לגופה פטור עליה!","ומשיבים: \u0003בדבר שאין מתכוין סבר לה\u0004 \u0005[סבור הוא]\u0006 שמואל \u0003כ\u0004שיטת \u0003ר' שמעון,\u0004 ובהלכה \u0003ב\u0004ענין \u0003מלאכה שאינה צריכה לגופה\u0004 — \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כ\u0004שיטת \u0003ר' יהודה\u0004 האוסר. \u0003אמר רבינא: הלכך,\u0004 לפי הדברים שאמרנו, אם נמצא \u0003קוץ ברשות הרבים\u0004 ועלול להזיק \u0003מוליכו\u0004 משם בשבת \u0003פחות פחות מארבע אמות\u0004 בשבת. שאף שמן התורה אסור לטלטל חפץ ארבע אמות ברשות הרבים, הרי בפחות מארבע אמות יש רק איסור מדברי סופרים, ומדברי שמואל למדנו שבכל דבר שיש בו כדי להזיק לרבים לא גזרו בו חכמים. ומשום כך, אם היה הקוץ \u0003בכרמלית\u0004 שעיקר איסור הטלטול בה הוא מדברי סופרים מותר לטלטל את הקוץ \u0003אפילו טובא\u0004 \u0005[יותר]\u0006 מארבע אמות.","שנינו במשנה: \u0003אבל נותן\u0004 אדם מים למיחם בשביל שיפשירו. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003נותן אדם חמין לתוך הצונן, ו\u0004אולם \u0003לא\u0004 את \u0003הצונן לתוך החמין,\u0004 אלו \u0003דברי בית שמאי,\u0004 שלדעתם מתחממים המים הצוננים מן המים החמים שמתחתם. \u0003ובית הלל אומרים בין חמין לתוך הצונן ובין צונן לתוך החמין מותר.\u0004 ואולם לא בכל אופן התירו בית הלל, אלא \u0003במה דברים אמורים\u0004 — \u0003בכוס. אבל באמבטי\u0004 שמרובים בה המים מותר לשפוך \u0003חמין לתוך הצונן, ו\u0004אולם \u0003לא צונן לתוך החמין. ור' שמעון בן מנסיא אוסר\u0004 אפילו בנתינת החמין לצונן. \u0003אמר רב נחמן: הלכה כר' שמעון בן מנסיא\u0004 בדבר זה.","\u0003סבר\u0004 \u0005[סבור היה]\u0006 \u0003רב יוסף למימר\u0004 \u0005[לומר]\u0006 ש\u0003ספל\u0004 שהוא כלי המשמש לרחיצה \u0003הרי הוא כאמבטי\u0004 ואסור למזוג בו מים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: תני\u0004 \u0005[שנה]\u0006 \u0003ר' חייא\u0004 בברייתא: \u0003ספל\u0004 לענין נתינת מים לתוכו \u0003אינו כאמבטי.\u0004 ושואלים: \u0003ולמאי דסליק אדעתא מעיקרא\u0004 \u0005[ולפי מה שעלה על הדעת מתחילה]\u0006 ש\u0003ספל\u0004 לענין הלכה זו \u0003הרי הוא כאמבטי ואמר רב נחמן\u0004 כי \u0003הלכה\u0004 בענין זה \u0003כר' שמעון בן מנסיא, אלא\u0004 אם כן נמצא ש\u0003בשבת\u0004 איסור \u0003רחיצה בחמין ליכא\u0004 \u0005[אין],\u0006 שלא שמענו איסור רחיצה כולל בחמין בשבת!","ומשיבים: \u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006 כי \u0003ר' שמעון אסיפא קאי\u0004 \u0005[על סוף\u0006 המשנה הוא \u0005עומד,\u0006 מתייחס\u0005],\u0006 לא, אלא \u0003ארישא קאי\u0004 \u0005[על ראשה\u0006 הוא \u0005עומד,\u0006 מתייחס\u0005],\u0006 ששנינו בה ש\u0003בית הלל מתירין בין\u0004 נתינת \u0003חמין לתוך צונן ובין\u0004 נתינת \u0003צונן לתוך החמין, ו\u0004על כך אמרו ש\u0003ר' שמעון בן מנסיא אוסר\u0004 נתינת \u0003צונן לתוך חמין.\u0004 ומקשים: אם כן \u0003לימא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 כי \u0003ר' שמעון בן מנסיא\u0004 ש\u0003אמר\u0004 דבריו כ\u0003בית שמאי\u0004 אמר? והלא נפסקה הלכה כללית כבית הלל! ומפרשים: \u0003הכי קאמר\u0004 \u0005[כך אמר,\u0006 כך נתכוון לומר\u0005]:\u0006 \u0003לא נחלקו בית שמאי ובית הלל בדבר זה,\u0004 שהיתה לר' שמעון מסורת אחרת בדבר שיטות בית שמאי ובית הלל.","\u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: חזינא ליה\u0004 \u0005[ראיתי אותו]\u0006 את \u0003רבא דלא קפיד אמנא\u0004 \u0005[שאינו מקפיד על כלי]\u0006 ואינו מבחין בענין זה בין חמין לצונן. ומנין לו היתר זה — \u0003מדתני\u0004 \u0005[ממה ששנה]\u0006 \u0003ר' חייא: נותן אדם קיתון של מים לתוך ספל של מים, בין חמין לתוך צונן, ובין צונן לתוך חמין. אמר רב הונא לרב אשי:\u0004 הרי יש חולשה בהוכחה זו, \u0003דילמא שאני התם דמיפסק\u0004 \u0005[שמא שונה שם שמפסיק]\u0006 \u0003כלי,\u0004 שאינו שופך מים צוננים בספל עצמו אלא מכניס את הקיתון לתוכה ודפנותיו מפסיקות! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 הלא באותה ברייתא לשון \u0003\"מערה\" איתמר\u0004 \u0005[\u0006\u0005נאמרה],\u0006 וכך היא הגרסה הנכונה: \u0003מערה אדם קיתון של מים לתוך ספל של מים, בין חמין לתוך צונן, בין צונן לתוך חמין.\u0004 ואם כן אין מקום להבדיל בדבר.","בהמשך לדיון באותם הדברים שיש בהם משום בישול, אף על פי שאינם מצויים ממש על האש, נקבע במשנה: \u0003האילפס והקדרה שהעבירן\u0004 מן האש בעודם \u0003מרותחין\u0004 (רותחים) אפילו לפני שבת — \u0003לא יתן לתוכן תבלין\u0004 ביום השבת עצמו, שכן יכול לבוא לידי בישול בקדירה הרותחת שהיא כלי ראשון."],["\u0003אבל נותן\u0004 אדם \u0003לתוך הקערה או לתוך התמחוי\u0004 (קערה גדולה ששופכים לתוכה מן האילפס או הקדירה), שהם כלי שני, ואין בהם כדי לבשל. \u0003ר' יהודה אומר: לכל הוא נותן\u0004 את התבלין בשבת, \u0003חוץ מ\u0004לתוך כלי שיש בו \u0003דבר שיש בו חומץ\u0004 או \u0003ציר\u0004 של דגים מלוחים.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 ללומדים\u0005]:\u0006 \u0003ר' יהודה\u0004 בהערתו החולקת, האם \u0003ארישא קאי, ולקולא\u0004 \u0005[על ראש\u0006 המשנה \u0005הוא עומד,\u0006 דבריו מוסבים, ובא \u0005להקל],\u0006 שבמשנה נאסר לשים תבלין לכל קדירה רותחת, ור' יהודה סבור שיש להקפיד רק אם היו שם ציר או חומץ. \u0003או דילמא אסיפא קאי, ולחומרא\u0004 \u0005[שמא לסוף\u0006 המשנה \u0005הוא מתכוון, ו\u0006בא \u0005להחמיר],\u0006 שאמרו חכמים שמותר לתת הכל לתוך קערה או תמחוי, ובא ר' יהודה להחמיר שלתוך חומץ או ציר אין לתת תבלין.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו ממה ששנינו בברייתא במפורש ש\u0003ר' יהודה אומר: לכל אילפסין הוא נותן\u0004 תבלין בשבת, \u0003לכל הקדירות\u0004 אף ה\u0003רותחות הוא נותן, חוץ מדבר שיש בו חומץ\u0004 או \u0003ציר,\u0004 הרי שחלק ר' יהודה על המשנה להקל.","\u0003סבר\u0004 \u0005[סבור היה]\u0006 \u0003רב יוסף למימר\u0004 \u0005[לומר]\u0006 כי \u0003מלח הרי הוא כתבלין\u0004 שדינו ש\u0003בכלי ראשון\u0004 שהיה על האש \u0003בשלה\u0004 \u0005[מתבשל]\u0006 המלח ולכך אסור לשים מלח בו בשבת. \u0003ובכלי שני\u0004 ששפכו אליו מן הכלי הראשון \u0003לא בשלה,\u0004 אין המלח מתבשל. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 הלא כבר \u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' חייא\u0004 ש\u0003מלח אינה כתבלין,\u0004 וודאי כוונתו ש\u0003בכלי שני נמי בשלה\u0004 \u0005[גם כן מתבשל]!\u0006 \u0003ו\u0004מעירים כי מסקנה זו \u0003פליגא\u0004 \u0005[חולקת]\u0006 על דברי \u0003רב נחמן,\u0004 ש\u0003אמר רב נחמן: צריכא מילחא בישולא כבשרא דתורא\u0004 \u0005[צריך מלח להתבשל\u0006 משך זמן \u0005כמו בשר שור],\u0006 כלומר, בישול ממושך ומרובה.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאמרו]\u0006 דברים אלה בגירסה שונה מאד: \u0003סבר\u0004 \u0005[סבור היה]\u0006 \u0003רב יוסף למימר\u0004 \u0005[לומר]\u0006 כי \u0003מלח הרי הוא כתבלין,\u0004 ש\u0003בכלי ראשון\u0004 — \u0003בשלה\u0004 \u0005[מתבשל],\u0006 ואילו \u0003בכלי שני\u0004 — \u0003לא בשלה\u0004 \u0005[אינו מתבשל].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 והלא כבר \u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' חייא\u0004 ש\u0003מלח אינה כתבלין,\u0004 וכוונת הדברים ש\u0003בכלי ראשון נמי לא בשלה\u0004 \u0005[גם כן אינו מתבשל],\u0006 \u0003והיינו\u0004 \u0005[וזהו]\u0006 בדיוק ש\u0003אמר רב נחמן: צריכא מילחא בישולא כבישרא דתורא\u0004 \u0005[צריך מלח להתבשל\u0006 משך זמן \u0005כמו בשר שור].\u0006","מדינים אלה ששנינו שעיקרם בדיני הטמנה וההכנה לשבת (ואגב כך דובר קצת בדיני מלאכת הבישול בשבת) עוברים לדיון קצר במקצת איסורי טלטול המוקצה, הקשורים בנר שבת. ואמרו חכמים: \u0003אין נותנין\u0004 בשבת \u0003כלי תחת הנר\u0004 (בית קיבול לשמן ופתילה) כדי \u0003לקבל בו את השמן\u0004 הנוטף מפתילת הנר. \u0003ואם נתנוה\u0004 את הכלי הנוסף בערב שבת \u0003מבעוד יום\u0004 — \u0003מותר. ו\u0004אולם בכל אופן \u0003אין ניאותין\u0004 (נהנים ומשתמשים) \u0003ממנו\u0004 מן השמן בשבת \u0003לפי שאינו מן המוכן\u0004 מראש מערב שבת לשימוש אחר בשבת. ולפיכך כבר הוקצה השמן שבנר והוקצב לצורך הדלקה בלבד.","בקשר לדברי המשנה \u0003אמר רב חסדא: אף על פי שאמרו\u0004 חכמים ש\u0003אין נותנין\u0004 בשבת \u0003כלי תחת תרנגולת\u0004 העומדת להטיל ביצתה והיא במדרון כדי \u0003לקבל\u0004 בו את \u0003ביצתה\u0004 שתישמר בו הביצה ולא תשבר בנפילתה, \u0003אבל\u0004 התירו אף בשבת להיות \u0003כופה\u0004 (הופך) \u0003עליה,\u0004 על הביצה \u0003כלי,\u0004 כדי \u0003ש\u0004לא ידרכו עליה ו\u0003לא תשבר. אמר רבה: מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 של \u0003רב חסדא\u0004 — \u0003קסבר\u0004 \u0005[הוא סבור]\u0006 ש\u0003תרנגולת עשויה להטיל ביצתה באשפה\u0004 ועשויים אנשים או בעלי חיים לדרוך עליה, \u0003ו\u0004אולם \u0003אינה עשויה\u0004 כרגיל \u0003להטיל ביצתה במקום מדרון,\u0004 שיכולה הביצה להתגלגל ולהשבר. \u0003ו\u0004לכן, \u0003הצלה מצויה התירו\u0004 חכמים, ולכן מותר לכפות את הכלי על הביצה שבמקום האשפה לשומרה משבירה \u0003ו\u0004אילו \u0003הצלה שאינה מצויה,\u0004 כגון לשים כלי תחת התרנגולת לקבל ביצה שלא תתגלגל במדרון \u0003לא התירו.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי: ו\u0004כי \u0003הצלה שאינה מצויה לא התירו\u0004 בשבת?! \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 : מי ש\u0003נשברה לו\u0004 בשבת \u0003חבית של טבל\u0004 (תבואה שעדיין לא הופרש ממנה מעשר האסורה באכילה עד להפרשה) הנמצאת \u0003בראש גגו, מביא כלי ומניח תחתיה\u0004 כדי שלא יאבד הטבל. ואף שהטבל אסור באכילה בשבת, מכל מקום התירו לטלטל כלי לצורכו אף במקרה בלתי רגיל של חבית שפקעה. והרי שהצלה שאינה מצויה הותרה! ענה לו רבה: אף זו הצלה מצויה היא, כי המדובר כאן \u0003בגולפי חדתי דשכיחי דפקעי\u0004 \u0005[בחביות חדשות שמצוי ש\u0006הן \u0005פוקעות].\u0006","ועוד \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 אביי ממה ששנינו במשנה: \u0003נותנין כלי תחת הנר\u0004 כדי \u0003לקבל\u0004 בו את ה\u0003ניצוצות\u0004 הבוערים של שמן המנטפים מן הפתילה הדולקת אף שאין זה רגיל? וענה רבה: כאן \u0003ניצוצות נמי שכיחי\u0004 \u0005[גם כן מצויים]\u0006 והצלה מצוייה היא זו."],["\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 אביי לרבה ממה ששנינו: \u0003כופין קערה על הנר\u0004 כדי \u0003שלא יאחז\u0004 להב הנר \u0003בקורה.\u0004 הרי שהתירו להשתמש בכלי, אף שאין זו הצלה מצויה! ענה לו רבה: כאן מדובר \u0003בבתי גחיני דשכיח בהו\u0004 \u0005[בבתים נמוכים שמצויה בהם]\u0006 \u0003דליקה.\u0004","\u0003וכן\u0004 קשה ממה ששנינו במשנה: \u0003קורה\u0004 של גג \u0003שנשברה, סומכין אותה\u0004 שלא תיפול \u0003בספסל\u0004 או \u0003בארוכות המטה\u0004 (המוטות הארוכים של מסגרת המיטה), והרי שאף הצלה שאינה מצויה הותרה! ענה רבה: המדובר הוא \u0003בכשורי חדתי דעבידי דפקעי\u0004 \u0005[בקורות חדשות שעשויות להשבר]\u0006 והרי זו הצלה מצויה.","ועוד הקשה לו ממה ששנינו: \u0003נותנין כלי תחת הדלף\u0004 הנוטף מן התקרה \u0003בשבת,\u0004 והרי שאף הצלה שאינה מצויה \u0003הותרה!\u0004 ענה רבה: המדובר כאן \u0003בבתי חדתי דשכיחי דדלפי\u0004 \u0005[בבתים חדשים שמצוי שידלפו].\u0006","\u0003רב יוסף אמר: היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 של \u0003רב חסדא\u0004 שהתיר לכסות ביצה תרנגולת, אך לא לשים תחת התרנגולת כדי לקלוט את הביצה בעת ההטלה: \u0003משום\u0004 שיש לחשוש \u0003דקא\u0004 \u0005[שהוא]\u0006 \u0003מבטל כלי מהיכנו.\u0004 שהכלי שהיה מוכן מקודם לכל מלאכה, מאחר שיש בתוכו עתה ביצה שאסור להשתמש בה ולטלטלה, אף הכלי אינו מוכן עוד לטלטול, והרי זה כאילו היה שובר את הכלי.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי\u0004 כדרך שהקשה לרבה ממה ששנינו: \u0003חבית של\u0004 יין \u0003טבל שנשברה\u0004 — \u0003מביא כלי אחר ומניח תחתיה\u0004 כדי לקלוט את היין שלא יאבד. ואף שהיין אסור בשתיה בשבת שהרי אסור לעשרו בשבת, והרי בכך הוא מבטל כלי מהיכנו! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: אין זו קושיה, כי ביסודו של דבר \u0003טבל מוכן הוא אצל\u0004 (מבחינת דין) \u0003שבת,\u0004 שכן \u0003שאם עבר ותקנו\u0004 (הפריש ממנו מעשר) בשבת — הריהו \u0003מתוקן\u0004 ומותר באכילה, וראוי לטלטול.","ועוד הקשה לו ממה ששנינו: \u0003נותנין כלי תחת הנר\u0004 כדי \u0003לקבל\u0004 בו את ה\u0003ניצוצות\u0004 הבוערים של שמן המנטפים מן הפתילה. והרי הכלי שהתמלא בנטפי שמן זעירים יתבטל על ידי כך מהיכנו! \u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: ניצוצות אין בהן ממש,\u0004 שהם כלים ונשרפים בנפילתם לקערה, ואינם מצטברים להיות כמות של שמן, וממילא אין הכלי נאסר בשימוש.","\u0003וכן\u0004 הקשה לו מענין \u0003קורה שנשברה,\u0004 ששנינו ש\u0003סומכין אותה בספסל או בארוכות המטה.\u0004 והרי מבטל אותם בכך מהיכנם! ותירץ: כאן מדובר באופן \u0003דרפי\u0004 \u0005[שרפה,\u0006 רופף\u0005]\u0006 משא הקורות על הספסל ואינו נשען כולו עליו\u0005],\u0006 \u0003דאי בעי שקיל ליה\u0004 \u0005[שאם ירצה יקח אותו,\u0006 את הספסל\u0005]\u0006 ולפיכך לא נתבטל הספסל מהיכנו.","ועוד הקשה לו ממה ששנינו: \u0003נותנין כלי תחת הדלף בשבת.\u0004 והרי אותו דלף שאינו ראוי לשימוש מוקצה הוא ובכך הוא מבטל את הכלי מהיכנו! ענה לו: מדובר כאן \u0003בדלף הראוי\u0004 לשתיה, וכיון שמותר לטלטל את המים שבכלי, אינו מתבטל כלל מהיכנו.","ועוד הקשה לו ממה ששנינו בתוספתא: \u0003כופין\u0004 (הופכים) \u0003את הסל לפני האפרוחין\u0004 כדי \u0003שיעלו וירדו\u0004 בו. ואם כן מבטל את הכלי מהיכנו בשל האפרוחים, שהרי האפרוחים אסורים בטלטול בשבת! ומשיבים: \u0003קסבר\u0004 רב יוסף שסל זה \u0003מותר לטלטלו\u0004 בשבת. ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 ש\u0003אסור לטלטלו?\u0004 ומשיבים: איסור זה נאמר \u0003בעודן עליו,\u0004 ואולם אם ירדו האפרוחים מן הסל — הותר בטלטול מיד. ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 ש\u0003אף על פי שאין עודן עליו\u0004 — \u0003אסור\u0004 לטלטלו, והרי אם כן מתבטל בכך הכלי מהיכנו! \u0003אמר ר' אבהו:\u0004 באותה ברייתא מדובר במקרה מיוחד: \u0003בעודן עליו כל בין השמשות\u0004 של ערב שבת, וכאן נוהגים לפי הכלל, ש\u0003מיגו דאיתקצאי\u0004 \u0005[מתוך שהוקצה]\u0006 משימוש בשעת \u0003בין השמשות\u0004 בערב שבת, \u0003איתקצאי לכולי יומא\u0004 \u0005[הוקצה לכל יום\u0006 השבת\u0005],\u0006 כי בין השמשות הוא הזמן הקובע לגבי כל כלי, אם משתמשים בו או אין משתמשים בו בשבת.","שיטה אחרת בהלכה היסודית של תרנגולת מטילה וביצתה בשבת \u0003אמר ר' יצחק,\u0004 ולדעתו \u0003כשם שאין נותנין כלי תחת תרנגולת\u0004 בשבת כדי \u0003לקבל ביצתה\u0004 — \u0003כך אין כופין עליה,\u0004 על הביצה \u0003כלי בשביל שלא תשבר.\u0004 ומסבירים: \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 ש\u0003אין כלי ניטל\u0004 בשבת \u0003אלא ל\u0004צורך \u0003דבר הניטל בשבת,\u0004 וכיון שהביצה אסורה בטלטול בשבת, אסור גם לטלטל עבורה כלי. \u0003מיתיבי כל הני תיובתא\u0004 \u0005[מקשים\u0006 עליו \u0005כל הקושיות הללו]\u0006 שהקשינו על דברי רב חסדא מהן משמע כי הדבר מותר. \u0003ושני\u0004 \u0005[ותירץ]:\u0006 בכל אותן הלכות מדובר \u0003ב\u0004אופן שהוא \u0003צריך\u0004 בין כה וכה מטעם אחר \u0003ל\u0004הזיז את הכלי שנהיה בית קיבול למוקצה בשבת כיון שהוא צריך את \u0003מקומו.\u0004 וכלל בידינו, שכיון שהותר הכלי בטלטול כלשהו ממקומו, מותר להוסיף ולטלטלו ולהניחו בכל מקום.","כדי לברר האם נכונה שיטת ר' יצחק אומרים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003אחת ביצה שנולדה בשבת, ואחת ביצה שנולדה ביום טוב אין מטלטלין\u0004 אותה \u0003לא לכסות בה את הכלי ו\u0004לא \u0003לסמוך בה\u0004 את \u0003כרעי המטה. אבל כופה\u0004 הוא \u0003עליה כלי בשביל שלא תשבר.\u0004 והרי זה שלא כדברי ר' יצחק! ומשיבים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003ב\u0004כלי שמונח במקום מסויים והוא רוצה להזיזו בכל אופן משם כיון שהוא \u0003צריך למקומו,\u0004 וכיון שמטלטלו ממקומו בהיתר, רשאי אף לכסות בו את הביצה.","ועוד \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראייה לדבר ממה ששנינו: \u0003פורסין מחצלות על גבי אבנים בשבת.\u0004 והרי שנוטלים כלי לצורך דבר שאינו ניטל בשבת! ומשיבים: מדובר כאן \u0003באבנים מקורזלות\u0004 (מחודדות) \u0003דחזיין\u0004 \u0005[שראויות]\u0006 \u0003ל\u0004שימוש ב\u0003בית הכסא,\u0004 ולכן הן מותרות לטילטול בשבת.","ועוד \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראייה לדבר ממה ששנינו: \u0003פורסין מחצלות על גבי לבנים בשבת.\u0004 והרי הלבנים אינן ראויות לשימוש בשבת, ובכל זאת נוטלים אותם לצורך דבר שאינו ניטל בשבת! ומשיבים: מדובר כאן בלבנים שאינן מוקצות למלאכה אלא \u0003דאישתיור מבנינא, דחזיין למיזגא עלייהו\u0004 \u0005[שנשארו מבנין וראויות להשען עליהן],\u0006 ואם כן הרי הן כשאר כלים שבבית ומותרות בטילטול.","ועוד \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראייה לדבר ממה ששנינו: \u0003פורסין מחצלת על גבי כוורת דבורים בשבת, בחמה\u0004 — \u0003מפני החמה,\u0004 שלא תזיק להם, \u0003ובגשמים\u0004 — \u0003מפני הגשמים. ובלבד שלא יתכוין לצוד\u0004 את הדבורים על ידי כיסוי זה. ועל כל פנים למדנו שמותר לטלטל מחצלת לצורך הכוורת אף שהיא עצמה אינה ניטלת בשבת! ודוחים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003דבש\u0004 בכוורת, ולצורך הדבש מותר לכסותה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב עוקבא ממישן לרב אשי: תינח\u0004 \u0005[נניח]\u0006 שאתה יכול לומר כן \u0003ב\u0004יחס ל\u0003ימות החמה\u0004"],["\u0003דאיכא\u0004 \u0005[ש\u0006כן בימות החמה \u0005יש]\u0006 \u0003דבש\u0004 בכוורת, ואולם \u0003ב\u0004יחס ל\u0003ימות הגשמים דליכא\u0004 \u0005[שאין]\u0006 \u0003דבש\u0004 בכוורת, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]\u0006 כדי להתיר, לדעת ר' יצחק, את כיסוי הכוורת? ומשיבים: \u0003לא נצרכא\u0004 הלכה זו \u0003אלא\u0004 כדי להתיר \u0003לאותן שתי חלות\u0004 דבש אותן משאירים בתוך הכוורת אף בימות הגשמים כדי שיתפרנסו מהן הדבורים, ולצורך דבש זה מותר לכסות את הכוורת. ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003מוקצות נינהו\u0004 \u0005[הן]\u0006 החלות הללו, שהרי הן מיועדות עבור הדבורים בלבד! ומשיבים: מדובר באופן \u0003דחשיב עלייהו\u0004 \u0005[שחשב עליהן]\u0006 עוד מלפני שבת והכינן לצורך אכילתו. ושואלים: \u0003הא\u0004 \u0005[הרי]\u0006 אם כן נבין כי אם \u0003לא חשיב עלייהו\u0004 \u0005[חשב עליהן]\u0006 \u0003מאי\u0004 \u0005מה]\u0006 יהא הדין בכגון זה — \u0003אסור\u0004 יהיה לכסות את הכוורת?","\u0003אי הכי, הא דתני\u0004 \u0005[זה ששנה]\u0006 התנא באותה ברייתא \u0003\"ובלבד שלא יתכוין לצוד\", לפלוג ולתני בדידה\u0004 \u0005[שיחלק וישנה\u0006 באותה הלכה \u0005עצמה],\u0006 ובאופן זה: \u0003במה דברים אמורים\u0004 שמותר לכסות את הכוורת — \u0003כשחישב עליהן, אבל לא חישב עליהן\u0004 — \u0003אסור!\u0004 ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[זה השמיע לנו],\u0006 חידוש נוסף בדברים ש\u0003אף על פי שחישב עליהן,\u0004 מכל מקום התירו לו ו\u0003בלבד שלא יתכוין לצוד.\u0004","לגופו של דבר שואלים: \u0003מני\u0004 \u0005[\u0006ברייתא זו דעת \u0005מי היא]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 כשיטת \u0003ר' שמעון\u0004 — הרי \u0003לית ליה\u0004 \u0005[אין לו,\u0006 אינו מקבל\u0005]\u0006 את איסור \u0003מוקצה,\u0004 ואין אם כן מקום לחלק בין כוורת לכוורת. \u0003אי\u0004 \u0005[אם]\u0006 כשיטת \u0003ר' יהודה כי\u0004 \u0005[כאשר]\u0006 הוא \u0003לא מתכוין מאי הוי\u0004 \u0005[מה יש]?\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 ר' יהודה אינו מחלק, ולשיטתו אף מלאכה ב\u0003דבר שאין מתכוין\u0004 — \u0003אסור!\u0004 ומשיבים: \u0003לעולם\u0004 יש לפרש שברייתא זו \u0003כר' יהודה.\u0004 אלא \u0003מאי\u0004 \u0005[מה,\u0006 כיצד יש לפרש\u0005]\u0006 \u0003\"ובלבד שלא יתכוין לצוד\"\u0004 — \u0003שלא יעשנה\u0004 את המחצלת \u0003כמצודה,\u0004 אלא \u0003דלישבוק להו רווחא כי היכי דלא ליתצדו ממילא\u0004 \u0005[שישאיר להם רווח כדי שלא ייצודו מעצמם].\u0006","\u0003רב אשי אמר\u0004 אפשר לתרץ באופן אחר: \u0003מי קתני\u0004 \u0005[האם שנה]\u0006 \u0003\"בימות החמה ו\"בימות הגשמים\"?\u0004 למעשה נאמר שם רק \u0003\"בחמה מפני החמה ובגשמים מפני הגשמים\",\u0004 ויש אפשרות לפרש זאת \u0003ביומי\u0004 \u0005[בימי]\u0006 ניסן \u0003וביומי\u0004 \u0005[ובימי]\u0006 \u0003תשרי, דאיכא\u0004 \u0005[שיש\u0006 \u0003חמה ואיכא\u0004 \u0005ויש]\u0006 \u0003צינה ואיכא\u0004 \u0005[ויש]\u0006 \u0003גשמים ואיכא\u0004 \u0005[ויש]\u0006 \u0003דבש\u0004 בכוורות.","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב ששת\u0004 לחכמים: \u0003פוקו\u0004 \u0005[צאו]\u0006 \u0003ואמרו ליה\u0004 \u0005[לו]\u0006 \u0003לר' יצחק\u0004 בארץ ישראל: \u0003כבר תרגמא\u0004 \u0005[פירש]\u0006 \u0003רב הונא לשמעתיך\u0004 \u0005[להלכה\u0006 זו \u0005שלך]\u0006 \u0003בבבל,\u0004 שאין אתה מחדש דבר בתוספת הכלל שקבעת שכלי אינו ניטל בשבת אלא לצורך דבר הניטל. ש\u0003אמר רב הונא: עושין מחיצה למת בשביל חי, ואין עושין מחיצה למת בשביל מת.\u0004 כלומר, שלצורך המת אסור לטלטל דברים, כיון שהמת עצמו אסור בטלטול בשבת.","ושואלים: \u0003מאי היא\u0004 \u0005[מה היא\u0006 דרך שימושה של הלכה זו\u0005]?\u0006 — ש\u0003אמר רב שמואל בר יהודה, וכן תנא\u0004 \u0005[שנה]\u0006 \u0003שילא מרי\u0004 בברייתא: \u0003מת המוטל בחמה\u0004 וחוששים שמא יסריח, \u0003באים שני בני אדם ויושבין בצדו.\u0004 לאחר זמן, כאשר \u0003חם להם מלמטה, זה מביא מטה ויושב עליה וזה מביא מטה ויושב עליה,\u0004 משני צידי המת, שהרי לצורך עצמם מותר לטלטל מיטות. \u0003חם להם מלמעלה, מביאים מחצלת ופורסין עליהן,\u0004 על ראשם. אחר כך \u0003זה זוקף מטתו\u0004 שתשאר המחצלת מונחת עליה \u0003ונשמט והולך לו, וזה,\u0004 השני \u0003זוקף מטתו ונשמט והולך לו, ונמצאת מחיצה\u0004 על המת \u0003עשויה\u0004 כאילו \u0003מאליה\u0004 בלא שיעשו אותה בגלוי לצורך המת. ומכאן למדנו שלא התירו לטלטל מחצלת כדי לכסות את המת לצורך עצמו, אלא בעקיפין, ולצורך החיים.","אגב הזכרת הלכות הקשורות במת בשבת, מביאים את זה ש\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים מה עושים ב\u0003מת המוטל בחמה. רב יהודה אמר\u0004 בשם \u0003שמואל: הופכו ממטה למטה\u0004 עד שיגיע בדרך זו לצל. ורב \u0003חנינא בר שלמיא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב אמר: מניח עליו ככר\u0004 לחם \u0003או תינוק ומטלטלו,\u0004 שנעשה המת כאילו בסיס לדבר המותר בטלטול בשבת, ונושאים אותו אגב הדבר המותר. ומוסיפים: \u0003היכא דאיכא\u0004 \u0005[היכן שיש]\u0006 \u0003ככר או תינוק כולי עלמא לא פליגי דשרי\u0004 \u0005[הכל אינם חלוקים שמותר]\u0006 להשתמש בדרך זו לטלטל את המת. \u0003כי פליגי דלית ליה\u0004 \u0005[כאשר נחלקו\u0006 הרי זה במקרה \u0005שאין לו\u0006 ככר או \u0005תינוק].\u0006 \u0003מר סבר\u0004 \u0005[חכם זה\u0006 רב \u0005סבור]\u0006 כי \u0003טלטול מן הצד,\u0004 שאינו נעשה כדרכו אלא כבדרך אגב, ובאופן שונה מן המקובל, \u0003שמיה\u0004 \u0005[שמו,\u0006 נחשב\u0005]\u0006 \u0003טלטול,\u0004 ולכן לדעתו אין לטלטלו בדרך העברה ממיטה למיטה. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 שמואל \u0005סבור]\u0006 כי טלטול מן הצד \u0003לא שמיה\u0004 \u0005[אין שמו],\u0006 \u0003טלטול,\u0004 ולכן לדעתו מותר לטלטל את המת כבדרך אגב ממיטה למיטה.","על מחלוקת זו של רב ושמואל מעירים: \u0003לימא כתנאי\u0004 \u0005[האם לומר\u0006 שמחלוקת זו היא כמחלוקת \u0005תנאים]\u0006 במקום אחר? שבתוספתא נחלקו בדבר. שאמרו חכמים: \u0003אין מצילין את המת מפני הדליקה\u0004 בשבת. \u0003אמר ר' יהודה בן לקיש: שמעתי שמצילין את המת מפני הדליקה.\u0004 ומבררים את הדבר: \u0003היכי דמי\u0004 \u0005[איך\u0006 בדיוק \u0005היה הדבר],\u0006 \u0003אי דאיכא\u0004 \u0005[אם\u0006 מדובר באופן \u0005שיש]\u0006 \u0003ככר או תינוק, מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 שאסר להוציאו מפני הדליקה? \u0003אי דליכא\u0004 \u0005[אם\u0006 מדובר באופן \u0005שאין]\u0006 ככר או תינוק, אם כן \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהודה בן לקיש\u0004 המתיר? \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 ש\u0003בטלטול מן הצד פליגי\u0004 \u0005[חלוקים\u0006 הם\u0005],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה\u0006 חכמים \u0005סבור]\u0006 ש\u0003טלטול מן הצד שמיה\u0004 \u0005[שמו,\u0006 נחשב\u0005]\u0006 \u0003טלטול,\u0004 ולכן אסר להוציא את המת אף בדרך זו. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' יהודה בן לקיש \u0005סבור]\u0006 כי \u0003לא שמיה\u0004 \u0005[אין שמו,\u0006 אינו נחשב\u0005]\u0006 \u0003טלטול,\u0004 ולכן לדעתו מותר להוציא את המת בדרך זו. ואם כן הרי שכבר נחלקו תנאים במחלוקת אמוראים זו! ודוחים: \u0003לא, דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003טלטול מן הצד שמיה\u0004 \u0005[שמו,\u0006 נחשב\u0005]\u0006 \u0003טלטול, ו\u0004אולם \u0003היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 של \u0003ר' יהודה בן לקיש:\u0004 ש\u0003מתוך שאדם בהול על מתו\u0004 וחושש מאד לכבוד המת"],["\u0003אי\u0004 \u0005[אם]\u0006 \u0003לא שרית ליה\u0004 \u0005[תתיר לו\u0006\u0005]\u0006 על ידי טלטול מן הצד \u0003אתי לכבויי\u0004 \u0005[יבוא לכבות\u0006 את הדליקה\u0005],\u0006 והתירו חכמים איסור מדברי סופרים כדי שלא יעבור אדם על דברי תורה. \u0003אמר ר' יהודה בן שילא\u0004 שכך \u0003אמר רב אסי\u0004 שכך \u0003אמר ר' יוחנן: הלכה כר' יהודה בן לקיש ב\u0004ענין הצלת \u0003מת\u0004 מדליקה.","שנינו במשנה ש\u0003אין ניאותין\u0004 (נהנים ומשתמשים) \u0003הימנו\u0004 (ממנו) מן השמן הנוטף מן הנר בשבת, \u0003לפי שאינו מן המוכן\u0004 מראש מערב שבת לשימוש בשבת. ובאותו ענין \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003מותר השמן שבנר ושבקערה\u0004 שהדליקו בה פתילה \u0003אסור\u0004 בשימוש בשבת. ואילו \u0003ר' שמעון מתיר,\u0004 כיון שלשיטתו אין כמעט איסורי מוקצה.","במשנה זו מצויה מחלוקת השייכת לכאורה רק לבעייה אחת. ואולם היא מפתח לכמה הלכות בדיני מוקצה. שאמרו: \u0003מטלטלין נר חדש\u0004 בשבת \u0003אבל לא\u0004 נר \u0003ישן\u0004 שהשתמשו בו כבר, כי נר שהשתמשו בו הריהו מפוייח ומלוכלך, ואינו ראוי לשימוש ונחשב משום כך כמוקצה מחמת המיאוס שבדבר. \u0003ר' שמעון אומר: כל הנרות מטלטלין\u0004 בשבת, \u0003חוץ מן הנר הדולק\u0004 עדיין \u0003בשבת\u0004 מחשש שמא יכבה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא אותה מחלוקת שבמשנה ביתר פירוט: \u0003מטלטלין\u0004 בשבת \u0003נר חדש, אבל לא ישן,\u0004 אלו \u0003דברי ר' יהודה.\u0004 ואילו \u0003ר' מאיר אומר: כל הנרות מטלטלין\u0004 אותם בשבת, \u0003חוץ מן הנר שהדליקו בו ב\u0004אותה \u0003שבת,\u0004 שאף שאינו סבור שפורשים ממוקצה מחמת מיאוס, אך כיון שהיה הנר דולק בשבת הריהו נאסר כמוקצה מחמת איסור לכל השבת. \u0003ר' שמעון אומר:\u0004 כל הנרות מותרים בטלטול, \u0003חוץ מן הנר הדולק\u0004 עדיין \u0003בשבת. כבתה\u0004 הנר — \u0003מותר לטלטלה. אבל כוס וקערה ועששית\u0004 המלאים שמן ופתילה דולקת בהם \u0003לא יזיזם ממקומם. ור' אליעזר בר' שמעון אומר: מסתפק\u0004 (משתמש) \u0003מן הנר הכבה, ומן השמן המטפטף\u0004 מן הנר, \u0003ואפילו בשעה שהנר דולק.\u0004","\u0003אמר אביי: ר' אליעזר בר' שמעון סבר לה כאבוה בחדא ופליג עליה בחדא\u0004 \u0005[סבור הוא כאביו\u0006 ר' שמעון \u0005ב\u0006דבר \u0005אחד וחלוק עליו ב\u0006דבר \u0005אחד].\u0006 \u0003סבר לה כאבוה בחדא\u0004 \u0005[סבור הוא כאביו ב\u0006דבר \u0005אחד]\u0006 — \u0003דלית ליה\u0004 \u0005[שאין לו,\u0006 אינו מקבל\u0005]\u0006 את איסור \u0003מוקצה. ופליג עליה בחדא\u0004 \u0005[וחלוק עליו ב\u0006דבר \u0005אחד],\u0006 ש\u0003אילו אבוה סבר\u0004 \u0005[אביו סבור]\u0006 שרק אם \u0003כבה\u0004 הנר — \u0003אין\u0004 \u0005[כן]\u0006 מותר לטלטלו, אבל אם \u0003לא כבה\u0004 — \u0003לא\u0004 הותר לטלטלו, \u0003ואיהו סבר\u0004 \u0005[והוא סבור]\u0006 כי \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא כבה\u0004 הנר מותר לטלטלו ולהשתמש בשמן הנוטף ממנו, ואין בכך לדעתו משום סיוע לכיבוי או מלאכה הדומה לכיבוי.","שנינו בתוספתא זו לאחר דברי ר' שמעון: \u0003אבל כוס וקערה ועששית לא יזיזם ממקומם.\u0004 ושואלים: \u0003מאי שנא הני\u0004 \u0005[מה שונים אלה]\u0006 שבהם אוסר אף ר' שמעון? \u0003אמר עולא: סיפא אתאן\u0004 \u0005[בסוף,\u0006 במשפט זה, \u0005באנו]\u0006 שוב \u0003ל\u0004פרש את שיטת \u0003ר' יהודה\u0004 האוסר במוקצה.","\u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 \u0003מר זוטרא: אי הכי, מאי\u0004 \u0005[אם כך, מה]\u0006 פירוש הביטוי \u0003\"אבל\u0004 כוס וקערה \u0003\"\u0004וכו', שהרי אסר ר' יהודה גם בנר ומה שינוי יכול להיות ביחס לדין הקערה? \u0003אלא אמר מר זוטרא: לעולם\u0004 יש לפרש אחרת ולומר כי דברים אלה מדברי \u0003ר' שמעון\u0004 הם. \u0003ו\u0004אולם \u0003כי קשרי\u0004 \u0005[כאשר התיר]\u0006 \u0003ר' שמעון\u0004 בנר היה זה \u0003בנר זוטא, דדעתיה עלויה\u0004 \u0005[בנר קטן שדעתו עליו]\u0006 והוא בטוח שיכבה הנר בשבת, ובדעתו להשתמש בשמנו באותו יום, \u0003אבל הני דנפישי\u0004 \u0005[אלה,\u0006 הקערה והעששית, \u0005שמרובים]\u0006 בשמן — \u0003לא\u0004 חשב שיכבו, והקצה אותן מדעתו לכל השבת.","ומקשים: \u0003והתניא\u0004 \u0005[והרי\u0006 שנינו בברייתא\u0005]:\u0006 \u0003מותר השמן שבנר ושבקערה\u0004 — \u0003אסור, ור' שמעון מתיר,\u0004 והרי שלא חילק ר' שמעון בדין זה בין נר לקערה! ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 שהתיר ר' שמעון ב\u0003קערה\u0004 הרי זה דווקא \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003נר,\u0004 כלומר, קערה קטנה ששמנה כלה מהר, ואולם \u0003הכא\u0004 \u0005[כאן]\u0006 מדובר ב\u0003קערה דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003כוס\u0004 שהיא גדולה.","\u0003אמר ר' זירא: פמוט\u0004 של מתכת \u0003שהדליקו בו בשבת, לדברי\u0004 ר' שמעון \u0003המתיר\u0004 בנר — \u0003אסור,\u0004 לפי שהוא גדול. ואילו \u0003לדברי\u0004 ר' יהודה \u0003האוסר\u0004 בנר — \u0003מותר\u0004 בפמוט, כי הפמוט אינו מאוס (ר\"ח). ומקשים: \u0003למימרא\u0004 \u0005[האם נאמר]\u0006 כי \u0003ר' יהודה\u0004 דין \u0003מוקצה מחמת מיאוס אית ליה\u0004 \u0005[יש לו,\u0006 הוא מקבל\u0005],\u0006 ואילו \u0003מוקצה מחמת איסור לית ליה\u0004 \u0005[אין לו,\u0006 אינו מקבל\u0005]\u0006 ומתיר בפמוט? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 ש\u0003ר' יהודה אומר: כל הנרות של מתכת מטלטלין\u0004 בשבת, \u0003חוץ מן הנר שהדליקו בו בשבת\u0004 עצמה. הרי שהוא אוסר את הנר של מתכת לא מחמת מיאוס, כי אם מאחר שהוקצה מחמת איסור! \u0003אלא, אי איתמר הכי איתמר\u0004 \u0005[אם נאמר, כך נאמר],\u0006 \u0003אמר ר' זירא: פמוט שהדליקו עליו בשבת\u0004 — ל\u0003דברי הכל אסור. לא הדליקו עליו\u0004 — ל\u0003דברי הכל מותר,\u0004 כיון שאין בו אף משום מוקצה מחמת מיאוס.","\u0003אמר רב יהודה אמר רב: מטה שיחדה ל\u0004הניח עליה \u0003מעות\u0004 — \u0003אסור לטלטלה\u0004 בשבת משום מוקצה, אף שאין עליה כעת מעות. \u0003מיתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב נחמן בר יצחק\u0004 ממה ששנינו במשנתנו: \u0003מטלטלין\u0004 בשבת \u0003נר חדש אבל לא ישן!\u0004"],["ומסביר את קושייתו: \u0003ומה נר דלהכי עבידא\u0004 \u0005[שלכך,\u0006 להדלקה, הוא \u0005נעשה],\u0006 ובכל זאת \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003לא הדליק בה שרי לטלטולה\u0004 \u0005[מותר לטלטלו],\u0006 \u0003מטה דלאו להכי עבידא\u0004 \u0005[שלא לכך,\u0006 להנחת כסף היא \u0005עשוייה]\u0006 \u0003לא כל שכן\u0004 שעל ידי קביעתה לצורך זה לא תיאסר?! \u0003אלא, אי איתמר, הכי איתמר\u0004 \u0005[אם נאמר, כך נאמר],\u0006 \u0003אמר רב יהודה אמר רב: מטה שיחדה ל\u0004הניח עליה \u0003מעות,\u0004 אם באחד הימים \u0003הניח עליה מעות —\u0004 הריהי נעשתה מיוחדת לכך, ו\u0003אסור לטלטלה. לא הניח עליה מעות\u0004 — \u0003מותר לטלטלה.\u0004 ואילו מיטה ש\u0003לא יחדה למעות\u0004 רק אם \u0003יש עליה מעות\u0004 בשבת עצמה \u0003אסור לטלטלה, אין עליה מעות\u0004 — \u0003מותר לטלטלה. והוא שלא היו עליה\u0004 מעות בשעת \u0003בין השמשות\u0004 שבין ערב שבת לשבת. שאם היו מעות עליה באותה שעה, נעשתה אף המיטה מוקצה מחמת איסור לכל אותה שבת, אף אם נפלו ממנה המעות במשך היום.","\u0003אמר עולא: מתיב\u0004 \u0005[מקשה]\u0006 \u0003ר' אליעזר\u0004 ממה ששנינו במשנה על דברי רב. ומשנה זו העוסקת בעיקרה בדיני טומאה דנה ביחס בין עגלה לבין המוכני (מערכת הגלגלים והבסיס לתיבתה של העגלה). ואמרו חכמים: \u0003מוכני שלה,\u0004 של העגלה, \u0003בזמן שהיא נשמטת\u0004 מן העגלה \u0003אין\u0004 היא נחשבת \u0003חיבור לה\u0004 להיחשב כיחידה אחת לא לענין קבלת טומאה ולא לענין טהרה מטומאה. \u0003ואין נמדדת עמה\u0004 לשיעור ארבעים סאה. כי כלי הגדול משיעור זה שוב אינו מקבל טומאה, ולכן המוכני של עגלה אינו נמדד עמה לצורך זה. \u0003ו\u0004כן \u0003אין מצלת עמה באהל המת,\u0004 כי עגלה גדולה נחשבת כאוהל (בית) לעצמו, והכלים שבתוך העגלה אינם נטמאים אם העגלה מאהילה על המת, ואולם המוכני של העגלה אינו מצטרף עמה לצורך זה. ואם יש בעגלה עצמה נקב אין סתימתו על ידי המוכני סותמתו לענין טומאה. \u0003ו\u0004כן \u0003אין גוררין אותה,\u0004 את המוכני, \u0003בשבת בזמן שיש עליה מעות.\u0004","ואם נדייק בלשון נלמד מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003אין עליה מעות\u0004 — \u0003שריא\u0004 \u0005[מותרת]\u0006 העגלה בטלטול, \u0003אף על גב דהוו עליה\u0004 \u0005[אף על פי שהיו עליו]\u0006 המעות \u0003בין השמשות,\u0004 שהרי במשנה זו תנאי האיסור הוא רק מציאות הכסף על העגלה באותה שעה! ומתרצים: המשנה \u0003ההיא\u0004 שיטת \u0003ר' שמעון היא דלית ליה\u0004 \u0005[שאין לו,\u0006 שאינו מקבל\u0005]\u0006 דין \u0003מוקצה, ו\u0004אילו \u0003רב כר' יהודה סבירא ליה\u0004 \u0005[סבור],\u0006 וכיון שלדעת ר' יהודה קיים דין מוקצה, הוקצתה העגלה משימוש עם שעת בין השמשות, ונשארת אסורה לכל השבת כולה."],["\u0003הכי נמי מיסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לומר ש\u0003רב כר' יהודה סבירא ליה\u0004 \u0005[סבור הוא],\u0006 שכן \u0003אמר רב: מניחין נר\u0004 בערב שבת \u0003על גבי דקל\u0004 שיבער \u0003בשבת, ו\u0004אולם \u0003אין מניחין נר על גבי דקל ביום טוב. אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 כי \u0003רב כר' יהודה סבירא ליה\u0004 \u0005[סבור הוא],\u0006 \u0003היינו דשני\u0004 \u0005[זוהי\u0006 הסיבה \u0005ששונה,\u0006 שיש הבדל\u0005]\u0006 לענין זה \u0003בין שבת ליום טוב,\u0004 שמאחר שהנר מוקצה בשבת לא יבוא לטלטלו, ואילו ביום טוב, כיוון שמותר לטלטל את הנר יש לחשוש שמא יבוא לטפס בדקל או להשתמש בו ביום טוב, ויעבור על האיסור שמדברי חכמים להשתמש בדבר המחובר לקרקע ביום טוב. \u0003אלא אי אמרת\u0004 \u0005[אלא אם אומר אתה]\u0006 רב \u0003כר' שמעון סבירא ליה\u0004 \u0005[סבור הוא],\u0006 שלדעתו אין הנר מוקצה כי אף בשבת, אם כן \u0003מה לי שבת ומה לי יום טוב?\u0004 שלכאורה אין הבדל בין זה לזה.","ומקשים: האם אמנם סבור \u0003רב כר' יהודה\u0004 שאסור לטלטל מוקצה? \u0003והא בעו מיניה\u0004 \u0005[והרי שאלו ממנו]\u0006 מ\u0003רב: מהו\u0004 הדין לענין שיהא מותר \u0003לטלטולי שרגא דחנוכתא מקמי חברי בשבתא\u0004 \u0005[לטלטל נר חנוכה מלפני החברים,\u0006 הכמרים הפרסיים, \u0005בשבת]?\u0006 שהיו אותם כמרים אוסרים להדליק כל אש בימים מסויימים, וכדי שלא יבחינו שהודלקו נרות חנוכה היה צורך למהר ולהזיזם ממקומם. \u0003ואמר להו\u0004 \u0005[להם]:\u0006 \u0003שפיר דמי\u0004 \u0005[יפה,\u0006 נכון \u0005הדבר\u0006 לעשותו\u0005].\u0006 והרי שאין רב מודה באיסור מוקצה! ומשיבים: אין זו ראייה, כי \u0003שעת הדחק שאני\u0004 \u0005[שונה],\u0006 ומפני הסכנה הוא שהתיר רב. וראייה לדבר, \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003רב כהנא ורב אשי לרב\u0004 על נושא זה: וכי \u0003הכי הלכתא\u0004 \u0005[כך ההלכה]?\u0006 \u0003אמר להו\u0004 \u0005[אמר להם]:\u0006 \u0003כדי\u0004 (כדאי, ראוי) \u0003הוא ר' שמעון לסמוך עליו בשעת הדחק\u0004 כגון זו.","באותו ענין \u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003ריש לקיש מר' יוחנן: חטים שזרען בקרקע\u0004 ועדיין לא השרישו ויכול עדיין ללוקטן משם, \u0003וביצים שתחת\u0004 ה\u0003תרנגולת\u0004 וכבר התחילה לדגור עליהן — \u0003מהו\u0004 הדין בכגון זה? האם יסכים ר' שמעון במקרים אלה שהדברים מוקצים משימוש בשבת? וצדדי השאלה: \u0003כי לית ליה\u0004 \u0005[כאשר אין לו]\u0006 \u0003לר' שמעון,\u0004 אינו מקבל את איסור \u0003מוקצה\u0004 — הרי זה \u0003היכא\u0004 \u0005[במקום]\u0006 ש\u0003לא דחייה\u0004 \u0005[דחאו]\u0006 לאותו דבר אותו הוא רוצה עתה לטלטל \u0003בידים,\u0004 ובכך לא הקצהו והוציאו על ידי מעשה מן השימוש, אבל \u0003היכא דדחייה\u0004 \u0005[במקום שדחאו]\u0006 \u0003בידים\u0004 — \u0003אית ליה\u0004 \u0005[יש לו,\u0006 הוא מקבל\u0005]\u0006 את דין \u0003מוקצה,\u0004 ובחיטה הרי משזרעה — דחאה בידים, וכן הביצה משעה שהניחה תחת התרנגולת לדגירה — דחאה, \u0003או דילמא לא שנא\u0004 \u0005[שמא אינו שונה],\u0006 ואין ר' שמעון מחלק בדברים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: \u0003אין\u0004 דין \u0003מוקצה לר' שמעון אלא\u0004 ב\u0003שמן שבנר בשעה שהוא דולק, הואיל והוקצה למצותו\u0004 להדליק נר בשבת, ואף \u0003הוקצה לאיסורו,\u0004 כיון שאסור משום חשש כיבוי להשתמש בו בשעת בעירתו.","ומקשים: \u0003ולית ליה\u0004 \u0005[ו\u0006כי \u0005אין לו,\u0006 אינו סובר\u0005]\u0006 איסור מוקצה בדבר ש\u0003הוקצה למצותו\u0004 בלבד בלא איסור אחר? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 סוכה ש\u0003סיככה כהלכתה ועיטרה\u0004 לשם נוי \u0003בקרמים\u0004 (בדים צבועים) \u0003ובסדינין המצויירין, ותלה בה\u0004 לקישוט \u0003אגוזין אפרסקין שקדים ורמונין ואפרכלי\u0004 (אשכולות) \u0003של ענבים, ועטרות\u0004 (זרים) \u0003של שבולין, יינות, שמנים וסלתות\u0004 — \u0003אסור להסתפק\u0004 (להשתמש) \u0003מהן עד מוצאי יום טוב האחרון\u0004 של החג, שמאחר שהוקצו כל הדברים הללו למצות הסוכה נאסרו לכל שימוש אחר. \u0003ואם התנה עליהן\u0004 בשעת תלייתם בסוכה שאינו מייחדם לצורך זה בלבד, וכוונתו גם להשתמש בהם שימושים אחרים — \u0003הכל לפי תנאו,\u0004 ומותר לו להשתמש בהם כרצונו.","\u0003וממאי\u0004 \u0005[וממה]\u0006 יודעים אנו שברייתא זו כשיטת \u0003ר' שמעון היא\u0004 אף שלא פורש שם אומרה — מתוך השוואה למה ששנה ר' חיא בר יוסף. \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003ר' חייא בר יוסף קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' יוחנן: אין נוטלין עצים מן הסוכה\u0004 שעשאוה לשם צל \u0003ב\u0004כל \u0003יום טוב,\u0004 ואפילו נפלה בחג, כיון שהוקצו משימוש מבעוד יום, שכן אסור להרוס את הסוכה ביום טוב. \u0003אלא\u0004 נוטלים עצים רק \u0003מן הסמוך לה,\u0004 שהעמיד לצידה חבילות עצים ואינם משמשים אותה, שבשעה שהניחם שם דעתו היתה להשתמש בהם ביום טוב. \u0003ור' שמעון מתיר\u0004 ליטול אף מן הסוכה עצמה, כיון שאינו מודה באיסור מוקצה. \u0003ו\u0004אולם \u0003שוין\u0004 (מסכימים) החולקים \u0003בסוכת החג\u0004 (סוכות) \u0003ב\u0004תוך ימי ה\u0003חג שהיא אסורה, ואם התנה עליה\u0004 שיוכל להשתמש בעציה בחג — \u0003הכל לפי תנאו.\u0004 הרי שאף ר' שמעון אוסר שימוש בדבר שהוקצה לצורך מצוה בלבד בלא שהוקצה משום איסור מלאכה! על כן מסבירים את דברי ר' יוחנן: \u0003כעין שמן שבנר קאמרינן\u0004 \u0005[אומרים אנו],\u0006 ולאו דווקא שיש גם איסור מלאכה וגם איסור מצוה, אלא הואיל \u0003והוקצה למצותו\u0004 בלבד הרי זה \u0003הוקצה לאיסורו. איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 כעין זה, ש\u0003אמר ר' חייא בר אבא אמר ר' יוחנן: אין\u0004 איסור \u0003מוקצה לר' שמעון אלא כעין שמן שבנר בשעה שהוא דולק,\u0004 ש\u0003הואיל והוקצה למצותו הוקצה לאיסורו.\u0004","\u0003אמר רב יהודה אמר שמואל אין\u0004 איסור \u0003מוקצה לר' שמעון אלא\u0004 ב\u0003גרוגרות וצימוקים בלבד.\u0004 שאם העלה אדם לגגו גרוגרות וצימוקים כדי לייבשם בחמה, הואיל ובשלבים הראשונים של ייבושם ריחם רע ואינם ראויים עוד לאכילה — רק באלה סבור ר' שמעון שאדם מקצה אותם מדעתו ואסורים בשבת משום מוקצה. ומקשים: \u0003ומידי אחרינא\u0004 \u0005[ודבר אחר]\u0006 \u0003לא\u0004 יכנס לגדר מוקצה? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003היה\u0004 אדם \u0003אוכל בתאנים והותיר\u0004 מהן \u0003והעלן לגג\u0004 להתייבש \u0003לעשות מהן גרוגרות,\u0004 וכן האוכל \u0003בענבים והותיר והעלן לגג לעשות מהן צימוקין\u0004 — \u0003לא יאכל\u0004 מהן בשבת \u0003עד שיזמין\u0004 ויכין אותן מבעוד יום לאכילה, שאם לא כן אסורות הן כמוקצה. \u0003וכן אתה אומר באפרסקין וחבושין ובשאר כל מיני פירות,\u0004 שהניחם להתייבש, שאסורים באכילה בשבת משום מוקצה.","ומעתה נבוא לברר \u0003מני\u0004 \u0005[\u0006שיטת \u0005מי היא]\u0006 ברייתא זו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 כי שיטת \u0003ר' יהודה\u0004 היא — והרי לברייתא זו אין משמעות, שכן \u0003ומה היכא\u0004 \u0005[במקום]\u0006 ש\u0003לא דחייה\u0004 \u0005[דחאו]\u0006 \u0003בידים\u0004 — \u0003אית ליה\u0004 \u0005[יש לו,\u0006 מקבל\u0005]\u0006 את איסור \u0003מוקצה, היכא דדחייה\u0004 \u0005[במקום שדחאו]\u0006 \u0003בידים לא כל שכן?\u0004 ואין כלל צורך להשמיענו הלכה במקרה מיוחד זה.","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 ברייתא זו כ\u0003ר' שמעון היא,\u0004 ונמצאנו למדים שהוא מרחיב את דיני מוקצה מעבר לגרוגרות וצימוקים בלבד! ודוחים: \u0003לעולם\u0004 אפשר לפרש שהלכה זו כ\u0003ר' יהודה\u0004 שלדעתו יש איסור מוקצה, \u0003ו\u0004אולם המקרה המיוחד שהיה כאן \u0003אוכל\u0004 בתאנים \u0003אצטריכא ליה\u0004 \u0005[נצרכה לו]\u0006 להשמיע בו דבר חידוש, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך\u0006 \u0003לומר]\u0004 כי \u0003כיון דקאכיל ואזיל\u0004 \u0005[שהוא אוכל והולך]\u0006 \u0003לא ליבעי\u0004 \u0005[יצטרך]\u0006 \u0003הזמנה,\u0004 ואם התחרט תוך כדי אכילתו יכול הוא מיד לקחת את הגרוגרות שהעלה לגג. על כן, \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 כי \u0003כיון\u0004 ש\u0003העלן לגג אסוחי אסחי לדעתיה מינייהו\u0004 \u0005[הסיח את דעתו מהם]\u0006 והרי הם מוקצה גמור.","ועוד בענין זה: \u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003ר' שמעון בר רבי\u0004 (רבי יהודה הנשיא) \u0003מרבי\u0004 אביו:"],["\u0003פצעילי תמרה\u0004 (תמרי בוסר שמניחים להם להבשיל בסלים, וכל עוד לא הבשילו קשה לאוכלם), \u0003ל\u0004שיטת \u0003ר' שמעון מהו\u0004 דינם לענין טלטול בשבת? האם יחשוב אותם כמוקצה? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבי: \u0003אין\u0004 איסור \u0003מוקצה לר' שמעון אלא\u0004 ב\u0003גרוגרות וצימוקין בלבד.\u0004","על עצם הענין שואלים: \u0003ו\u0004כי \u0003רבי לית ליה\u0004 \u0005[אין לו,\u0006 אינו מקבל\u0005]\u0006 את איסור \u0003מוקצה? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 שביום טוב \u0003אין משקין\u0004 את הבהמות מים לפני השחיטה, כדי שיהיה נוח להפשיטן מעורן, \u0003ו\u0004אף אין \u0003שוחטין את\u0004 הבהמות \u0003המדבריות,\u0004 שהן הבהמות הרועות בשדה במשך כל הזמן, כי מאחר שאין אנשים מטפלים בהן כרגיל נחשבות הן למוקצה, ואין להשתמש בהן. \u0003אבל משקין ושוחטין את הבייתות\u0004 (בהמות הבית). \u0003ותניא\u0004 \u0005[ו\u0006בענין זה \u0005שנוייה\u0006 ברייתא\u0005]:\u0006 \u0003אלו הן\u0004 הבהמות ה\u0003מדבריות?\u0004 — \u0003כל שיוצאות\u0004 מן הרפתות \u0003בפסח ונכנסות\u0004 לרפתות עם ה\u0003רביעה\u0004 (עונת הגשמים). ו\u0003בייתות\u0004 הן \u0003כל\u0004 אותן בהמות \u0003שיוצאות ורועות חוץ לתחום\u0004 העיר, \u0003ובאות ולנות בתוך התחום.\u0004 ואילו \u0003רבי אומר: אלו ואלו בייתות הן. ואלו הן מדבריות\u0004 שנאסרו משום מוקצה: \u0003כל שרועות באפר ואין נכנסות לישוב לא בימות החמה ולא בימות הגשמים,\u0004 והן אלה האסורות בהשקייה ובשחיטה ביום טוב. הרי שרבי סבור שיש אף בבהמות משום איסור מוקצה!","לסתירה זו ניתנים תירוצים אחדים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 כי \u0003הני נמי\u0004 \u0005[אלה\u0006 המדבריות הרועות באפר בכל ימות השנה \u0005גם כן]\u0006 \u0003כגרוגרות וצימוקין דמיין\u0004 \u0005[\u0006הן \u0005נחשבות]\u0006 ואף ר' שמעון יודה בכך. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר לסתירה: שמה שענה רבי לבנו — \u0003לדבריו,\u0004 על פי שיטתו של \u0003ר' שמעון קאמר ליה\u0004 \u0005[אמר לו],\u0006 \u0003וליה לא סבירא ליה\u0004 \u0005[ו\u0006אולם \u0005לו,\u0006 הוא עצמו, רבי, \u0005אינו סבור כך].\u0006","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר: שבאותה ברייתא \u0003לדבריהם דרבנן קאמר להו\u0004 \u0005[של חכמים אמר להם],\u0006 וכך יש להבין את דבריו: \u0003לדידי לית\u0004 \u0005[לשיטתי\u0006 אני \u0005אין]\u0006 \u0003לי,\u0004 איני סובר איסור \u0003מוקצה כלל,\u0004 ואולם \u0003לדידכו אודו לי מיהת דהיכא\u0004 \u0005[לשיטתכם הודו לי לפחות שבמקום]\u0006 ש\u0003יוצאות\u0004 הבהמות מהרפתות \u0003בפסח ונכנסות\u0004 בחזרה אליהן \u0003ברביעה\u0004 ש\u0003בייתות נינהו\u0004 \u0005[הן].\u0006 \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה הם ענו לו? — הם \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003לא,\u0004 אלה \u0003מדבריות נינהו\u0004 \u0005[הן].\u0006","על עיקרה של המחלוקת בדיני מוקצה \u0003אמר רבה בר בר חנה\u0004 שכך \u0003אמר ר' יוחנן: אמרו הלכה כר' שמעון\u0004 שאינו מקבל את איסור מוקצה. ומקשים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' יוחנן הכי\u0004 \u0005[כך]?\u0006 \u0003והא בעא מיניה ההוא סבא\u0004 \u0005[והרי שאל ממנו זקן אחד]\u0006 מ\u0003קרויא ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שמ \u0003סרויא\u0004 את \u0003ר' יוחנן: קינה\u0004 (לול) של \u0003תרנגולת מהו\u0004 דינה לענין ה\u0003היתר לטלטולי\u0004 \u0005[לטלטלה]\u0006 \u0003בשבת? אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: \u0003כלום עשוי\u0004 הלול \u0003אלא לתרנגולין\u0004 שיהיו בו, וכיון שאינו מיועד לצורך אדם הריהו אסור בטלטול, הרי שסבר כר' יהודה בענין מוקצה! ומתרצים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — במקרה מיוחד, וכגון \u0003דאית ביה\u0004 \u0005[שיש בו\u0006 בלול\u0005]\u0006 \u0003אפרוח מת,\u0004 ומשום האפרוח שהוא מוקצה אסור לטלטל את הלול.","וממשיכים לשאול: \u0003הניחא\u0004 \u0005[זה נוח,\u0006 מובן\u0005]\u0006 \u0003ל\u0004שיטת \u0003מר בר אמימר משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב\u0004 ש\u0003אמר : מודה היה ר' שמעון בבעלי חיים שמתו\u0004 בשבת \u0003ש\u0004הם \u0003אסורין\u0004 כמוקצה בשבת. ואולם \u0003ל\u0004שיטת \u0003מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא\u0004 ש\u0003אמר : חלוק היה ר' שמעון אפילו ב\u0004ענין \u0003בעלי חיים שמתו\u0004 ואמר \u0003שהן מותרין\u0004 ואינם אסורים כמוקצה, לשיטה זו \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003בדאית ביה\u0004 \u0005[בשיש בו,\u0006 בלול\u0005]\u0006 \u0003ביצה\u0004 שנולדה בו ביום, והביצה, כיון שנולדה בשבת ולא העלה איש על דעתו להכינה מאתמול, אסורה בשימוש משום מוקצה.","ומקשים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב נחמן: מאן דאית ליה\u0004 \u0005[מי שיש לו,\u0006 מקבל\u0005]\u0006 את דין \u0003מוקצה\u0004 — \u0003אית ליה\u0004 \u0005[יש לו]\u0006 גם איסור בדבר \u0003נולד,\u0004 וזה \u0003דלית ליה\u0004 \u0005[שאין לו]\u0006 דין \u0003מוקצה\u0004 — \u0003לית ליה\u0004 \u0005[אין לו]\u0006 גם דין \u0003נולד,\u0004 ואין דינו שונה משאר מוקצה! ומשיבים: מדובר כאן באופן \u0003דאית ביה\u0004 \u0005[שיש בו,\u0006 בלול\u0005]\u0006 \u0003ביצת אפרוח,\u0004 שיש בביצה כבר אפרוח, וביצה כזו, כיון שאינה ראויה לאכילה לא לאדם ולא לבעלי חיים, אף ר' שמעון מודה שאסורה בטלטול.","דברים אלה נאמרו על מנת להסביר שיתכן שר' יוחנן סבור כר' שמעון, ואולם \u0003כי אתא\u0004 \u0005[כאשר בא],\u0006 \u0003רב יצחק בר' יוסף\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' יוחנן: הלכה כר' יהודה\u0004 שיש איסור מוקצה. \u0003ור' יהושע בן לוי אמר: הלכה כר' שמעון\u0004 שאין איסור מוקצה. \u0003אמר רב יוסף: היינו\u0004 \u0005[זהו]\u0006 ש\u0003אמר רבה בר בר חנה\u0004 שכך \u0003אמר ר' יוחנן: אמרו הלכה כר' שמעון.\u0004 והכוונה היא שהוא זה שאמר ש\u0003אמרו, ו\u0004אולם \u0003ליה לא סבירא ליה\u0004 \u0005[לו,\u0006 הוא עצמו \u0005אינו סבור כך].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לר' יוסף: ואת לא תסברא\u0004 \u0005[ו\u0006כי \u0005אתה\u0006 עצמך \u0005אינך סבור]\u0006 כי \u0003ר' יוחנן\u0004 סבור ופוסק \u0003כר' יהודה\u0004 גם לפני שבא רב יצחק וסיפר את הדברים בשמו, \u0003הא\u0004 \u0005[\u0006ו\u0005הרי]\u0006 \u0003ר' אבא ור' אסי איקלעו לבי\u0004 \u0005[הזדמנו לבית]\u0006 \u0003ר' אבא\u0004 ש\u0003מן\u0004 העיר \u0003חיפא, ונפל מנרתא על גלימיה\u0004 \u0005[ונפלה מנורה על גלימתו]\u0006 של \u0003ר' אסי ולא טילטלה.\u0004 ומעתה, \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 לא טילטלה? \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום\u0004 ש\u0003ר' אסי תלמידיה\u0004 \u0005[תלמידו]\u0006 של \u0003ר' יוחנן הוה\u0004 \u0005[היה],\u0006 \u0003ור' יוחנן כר' יהודה סבירא ליה\u0004 \u0005[סבור הוא],\u0006 \u0003דאית ליה\u0004 \u0005[שיש לו,\u0006 שמקבל\u0005]\u0006 את איסור \u0003מוקצה,\u0004 ואם כן מסיפור זה אפשר ללמוד שר' יוחנן סבור כר' יהודה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף לאביי: בענין \u0003מנרתא קאמרת\u0004 \u0005[מנורה אומר אתה]\u0006 להביא הוכחה? \u0003מנרתא שאני\u0004 \u0005[מנורה שונה]\u0006 כי בדין זה יש הלכה מיוחדת, ש\u0003אמר ר' אחא בר' חנינא\u0004 שכך \u0003אמר ר' אסי: הורה ריש לקיש בצידן: מנורה הניטלת בידו\u0004 ה\u0003אחת\u0004 — \u0003מותר לטלטלה\u0004 בשבת, ואולם אם כבידה היא עד שצריך לטלטלה \u0003בשתי ידיו\u0004 — \u0003אסור לטלטלה. ור' יוחנן אמר: אנו אין לנו\u0004 היתר טלטול \u0003אלא בנר\u0004 ו\u0003כ\u0004שיטת \u0003ר' שמעון. אבל מנורה, בין ניטלה בידו\u0004 ה\u0003אחת בין ניטלה בשתי ידיו\u0004 — \u0003אסור לטלטלה.\u0004","ושואלים: \u0003וטעמא מאי\u0004 \u0005[ומה טעם]\u0006 יהא איסור מיוחד במנורה? \u0003רבה ורב יוסף דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003הואיל ואדם קובע לה\u0004 בדרך כלל מפני גודלה ושימושה \u0003מקום\u0004 קבוע ומסויים, הרי זה כאילו היתה חלק בנוי מן הבית, שבהעברתו הריהו כהורסו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: והרי כילת חתנים\u0004 ש\u0003אדם קובע לו מקום, ו\u0004בכל זאת \u0003אמר שמואל משום\u0004 (בשם) \u0003ר' חייא: כילת חתנים\u0004"],["\u0003מותר לנטותה\u0004 (להרכיבה) \u0003ומותר לפרקה בשבת.\u0004 ואם כלי קבוע כזה מותר להרכיבו ואין חוששים משום בניה, כל שכן שאין להחשיב בניה וסתירה במנורה! \u0003אלא אמר אביי:\u0004 כאן מדובר \u0003ב\u0004מנורה מיוחדת שהיתה \u0003של חוליות,\u0004 שהמנורה מורכבת מחלקים מתפרקים, ויש לחשוש שמא מתוך טלטולה תיפול המנורה ותתפרק לחלקיה, ויבוא להרכיבה, והריהו כעושה כלי בשבת. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שבמנורה כזו מדובר, \u0003מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' שמעון בן לקיש דשרי\u0004 \u0005[שמתיר]?\u0006","ומשיבים: אכן אין מדובר כאן במנורה מתפרקת ממש, אלא \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"חוליות\"\u0004 שאמרנו — \u0003כעין חוליות, דאית\u0004 \u0005[שיש]\u0006 \u0003בה חידקי\u0004 \u0005[חריצים]\u0006 ונראית כאילו היתה עשויה פרקים. \u0003הלכך\u0004 \u0005[משום כך]\u0006 אפשר לסכם: מנורה העשויה \u0003חוליות\u0004 ממש, \u0003בין\u0004 שהיא \u0003גדולה ובין\u0004 שהיא \u0003קטנה\u0004 — \u0003אסורה לטלטלה.\u0004 ומנורה \u0003גדולה נמי דאית\u0004 \u0005[גם כן שיש]\u0006 \u0003בה חידקי\u0004 \u0005[חריצים]\u0006 — אסורה בטלטול לדעת הכל, \u0003גזירה\u0004 היא שגזרו חכמים \u0003אטו\u0004 \u0005[משום]\u0006 מנורה \u0003גדולה\u0004 שעשוייה \u0003חוליות,\u0004 כי מנורה גדולה שכיח שתהיה מורכבת מחוליות, ואם יתירו לטלטל את הגדולה בעלת החריצים, הרי מחמת דמיונן זו לזו יחשבו אנשים שהיא בעלת חוליות, ויבואו להתיר את טלטול הגדולה בעלת החוליות. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 ר' יוחנן וריש לקיש היה זה \u0003ב\u0004מנורה \u0003קטנה דאית\u0004 \u0005[שיש]\u0006 \u0003בה חידקי\u0004 \u0005[חריצים]\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' יוחנן, \u0005סבור]\u0006 כי \u0003גזרינן\u0004 \u0005[גוזרים אנו]\u0006 ואוסרים בטלטול אף את הקטנה שיש בה חריצים משום הגדולה, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ריש לקיש \u0005סבור]\u0006 כי \u0003לא גזרינן\u0004 \u0005[אין אנו גוזרים],\u0006 כי מנורה קטנה כרגיל אינה עשויה פרקים, והכל יודעים שהחריצים שבה נעשו לנוי בלבד.","ולגופו של דבר שואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' יוחנן הכי\u0004 \u0005[כך]\u0006 שהלכה כר' יהודה? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן\u0004 כלל: \u0003הלכה כסתם משנה\u0004 (כמשנה שלא נזכר שם אומרה). \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]\u0006 בענין טומאה, שעגלה שיש לה מוכני שהיא מערכת גלגלים נפרדת, ה\u0003מוכני שלה בזמן שהיא נשמטת\u0004 ונפרדת מן העגלה — \u0003אין\u0004 המוכני \u0003חיבור לה,\u0004 לעגלה, להיחשב כיחידה אחת לא לענין קבלת טומאה ולא לענין טהרה מטומאה. \u0003ואין\u0004 היא \u0003נמדדת עמה\u0004 לשיעור ארבעים סאה. כי כלי הגדול משיעור זה שוב אינו מקבל טומאה, ומוכני של עגלה אינו נמדד עמה לצורך זה. \u0003ו\u0004כן \u0003אין מצלת עמה באהל המת,\u0004 כי עגלה גדולה נחשבת כאוהל (בית) לעצמו, והכלים שבתוך העגלה אינם נטמאים אם העגלה מאהילה על המת, ואולם המוכני של העגלה אינו מצטרף עמה לצורך זה. ואם יש בעגלה עצמה נקב אין סתימתו על ידי המוכני סותמתו לענין טומאה. \u0003ו\u0004כן \u0003אין גוררין אותה,\u0004 את המוכני, \u0003בשבת בזמן שיש עליה מעות.\u0004","ומכאן נסיק: \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003אין עליה מעות\u0004 — \u0003שריא\u0004 \u0005[מותרת]\u0006 היא בטלטול, \u0003ואף על גב דהוו עליה\u0004 \u0005[ואף על פי שהיו עליה]\u0006 מעות \u0003בין השמשות,\u0004 ודבר שהיה מוקצה בין השמשות הרי הוא מוקצה לכל השבת. ומאחר ובמשנה סתמית זו הותר טלטול העגלה, וסתם משנה כשיטת ר' שמעון שאין לדעתו דין מוקצה, מדוע אם כן לא פסק כן ר' יוחנן הסובר כי הלכה בכל מקום כסתם משנה? \u0003אמר ר' זירא: תהא משנתינו\u0004 רק במקרה \u0003שלא היו עליה מעות כל\u0004 משך זמן \u0003בין השמשות,\u0004 ונקבל דוחק פרשני זה כדי \u0003שלא לשבור\u0004 ולבטל את \u0003דבריו של ר' יוחנן.\u0004","\u0003אמר ר' יהושע בן לוי: פעם אחת הלך רבי ל\u0004ישוב \u0003דיוספרא, והורה\u0004 הלכה למעשה \u0003ב\u0004שאלה שהיתה בענין \u0003מנורה כ\u0004שיטת \u0003ר' שמעון בנר.\u0004 לשון זו איננה ברורה די הצורך, ולכך \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 לחכמים\u0005]\u0006 שאלה זו: האם הכוונה כי \u0003הורה במנורה\u0004 כמו שמורה \u0003ר' שמעון בנר להיתרא\u0004 \u0005[להתיר]\u0006 בשני המקרים, גם בנר וגם במנורה, \u0003או דילמא\u0004 \u0005[שמא]\u0006 נפרש כך: ש\u0003הורה במנורה לאיסורא\u0004 \u0005[לאיסור]\u0006 \u0003ו\u0004במקרה אחר \u0003כר' שמעון בנר להיתרא\u0004 \u0005[להיתר].\u0006 לשאלה זו לא נמצא פתרון ולכן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","מסופר כי \u0003רב מלכיא איקלע לבי\u0004 \u0005[הזדמן לבית]\u0006 \u0003ר' שמלאי וטילטל שרגא\u0004 \u0005[נר\u0006 כבוי\u0005],\u0006 \u0003ואיקפד\u0004 \u0005[והקפיד]\u0006 \u0003ר' שמלאי\u0004 על שעשה כך, שלדעתו אסור טלטול הנר משום מוקצה. וכן \u0003ר' יוסי גלילאה איקלע לאתריה\u0004 \u0005[הגלילי הזדמן למקומו]\u0006 של \u0003ר' יוסי בר' חנינא\u0004 ו\u0003טילטל שרגא\u0004 \u0005[נר]\u0006 \u0003ואיקפד\u0004 \u0005[והקפיד]\u0006 \u0003ר' יוסי בר' חנינא.\u0004 וכן מסופר כי \u0003ר' אבהו כי איקלע לאתריה\u0004 \u0005[כאשר היה מזדמן למקומו]\u0006 של \u0003ר' יהושע בן לוי הוה\u0004 \u0005[היה]\u0006 \u0003מטלטל שרגא\u0004 \u0005[נר].\u0006 ואולם \u0003כי איקלע לאתריה\u0004 \u0005[כאשר היה מזדמן למקומו]\u0006 של \u0003ר' יוחנן לא הוה\u0004 \u0005[היה]\u0006 \u0003מטלטל שרגא\u0004 \u0005[נר].\u0006 ותוהים: \u0003מה נפשך?\u0004 הרי \u0003אי\u0004 \u0005[אם]\u0006 \u0003כר' יהודה סבירא ליה\u0004 \u0005[סבור הוא],\u0006 אם כן \u0003ליעבד\u0004 \u0005[שיעשה,\u0006 ינהג\u0005]\u0006 \u0003כ\u0004שיטת \u0003ר' יהודה\u0004 ולא יטלטל את הנר בשום מקום. ו\u0003אי\u0004 \u0005[אם]\u0006 \u0003כר' שמעון סבירא ליה\u0004 \u0005[סבור הוא],\u0006 אם כן \u0003ליעבד\u0004 \u0005[שיעשה]\u0006 \u0003כ\u0004שיטת \u0003ר' שמעון,\u0004 ויטלטל את הנר בכל מקום! ומשיבים: \u0003לעולם\u0004 יש לפרש כי ר' אבהו \u0003כר' שמעון סבירא ליה\u0004 \u0005[סבור הוא],\u0006 \u0003ו\u0004אולם \u0003משום כבודו של ר' יוחנן הוא\u0004 ש\u0003לא הוה עביד\u0004 \u0005[היה עושה],\u0006 כדי שלא לעשות במקומו שלא כדעתו.","בדיני טלטול הנרות בשבת \u0003אמר רב יהודה: שרגא דמשחא שרי לטלטולה\u0004 \u0005[נר של שמן מותר לטלטלו]\u0006 לאחר שכבה, ואילו \u0003דנפטא\u0004 \u0005[של נפט]\u0006 — \u0003אסור לטלטולה\u0004 \u0005[לטלטלו].\u0006 וטעם הדבר, שכיון שריחו של נפט רע אינו מיועד להדלקה ולכן אסור לטלטלו. \u0003רבה ורב יוסף דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003דנפטא נמי שרי לטלטולה\u0004 \u0005[\u0006נר \u0005של נפט גם כן מותר לטלטלו].\u0006","מסופר: \u0003רב אויא איקלע לבי\u0004 \u0005[הזדמן לבית]\u0006 \u0003רבא. הוה מאיסן בי כרעיה, בטינא, אתיבי אפוריא קמיה\u0004 \u0005[היו מלוכלכות רגליו בטיט,\u0006 ו\u0005שם אותן על המיטה לפני]\u0006 \u0003רבא. איקפד\u0004 \u0005[הקפיד]\u0006 עליו \u0003רבא\u0004 על לכלוך המטה, ולכן \u0003בעא לצעוריה\u0004 \u0005[רצה לצערו]\u0006 על ידי שאלות שלא יוכל לענות עליהן. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003רבה ורב יוסף דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 כי \u0003שרגא\u0004 \u0005[נר]\u0006 של \u0003נפט נמי שרי לטלטוליה\u0004 \u0005[גם כן מותר לטלטלו]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אויא: \u0003הואיל וחזיא לכסויי בה מנא\u0004 \u0005[וראויים לכסות בהם כלי].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003אלא מעתה\u0004 אם זהו נימוק, אם כן \u0003כל צרורות שבחצר\u0004 אבן שבחצר יהיו \u0003מטלטלין\u0004 לכתחילה בשבת, \u0003הואיל וחזיא לכסויי בהו מנא\u0004 \u0005[וראויים\u0006 הם \u0005לכסות בהם כלי].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אויא: יש להבחין בין הדברים, \u0003הא איכא\u0004 \u0005[זה\u0006 הנר \u0005יש]\u0006 \u0003תורת כלי עליה\u0004 \u0005[עליו]\u0006 ובכלים הקלו במוקצה. \u0003הני\u0004 \u0005[אלה]\u0006 האבנים \u0003ליכא\u0004 \u0005[אין]\u0006 \u0003תורת כלי עליה\u0004 \u0005[עליהם],\u0006 שהם חומרים גולמיים בלבד ואין היתר לטלטלם, אם לא הוכנו לצורך זה מבעוד יום. ו\u0003מי לא תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]\u0006 כי"],["\u0003השירים\u0004 (צמידים) \u0003והנזמים והטבעות\u0004 אף שאסור לצאת בהם לרשות הרבים, מכל מקום \u0003הרי הן ככל הכלים הנטלים בחצר,\u0004 שברשות היחיד מותר לטלטלם ואין בהם דין מוקצה. \u0003ואמר עולא: מה טעם\u0004 הותרו הנזמים בטלטול בחצר? — \u0003הואיל ואיכא\u0004 \u0005[ויש]\u0006 \u0003תורת כלי עליה\u0004 \u0005[עליו].\u0006 \u0003הכא נמי הואיל ואיכא תורת כלי עליה\u0004, והרי ש\"תורת כלי\" משמשת נימוק להתיר טלטול בשבת. \u0003אמר רב נחמן בר יצחק: בריך רחמנא\u0004 \u0005[ברוך ה']\u0006 ש\u0003לא כסיפיה\u0004 \u0005[ביישו]\u0006 \u0003רבא לרב אויא,\u0004 שהצליח רב אויא לענות יפה לשאלות רבא.","\u0003רמי ליה\u0004 \u0005[השליך,\u0006 הקשה \u0005לו]\u0006 \u0003אביי לרבה\u0004 בהבאת שני מקורות סותרים בענין דין מוקצה בשבת. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003מותר השמן ש\u0004נותר \u0003בנר\u0004 לאחר שכבה, \u0003ו\u0004כן זה \u0003שבקערה\u0004 — \u0003אסור\u0004 בטלטול בשבת, \u0003ור' שמעון מתיר. אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003לר' שמעון לית ליה\u0004 \u0005[אין לו,\u0006 אינו מקבל\u0005]\u0006 את איסור \u0003מוקצה. ורמינהו\u0004 \u0005[ומשליכים אנו,\u0006 מקשים ממקור דומה\u0005]\u0006 שעסקו חכמים בדין בכור בהמה טהורה שנפל בו מום ביום טוב, ויש לבדוק אם מום זה הוא מן המומים הפוסלים את הבכור לקרבן, ויותר הבכור בשחיטה ובאכילה לחולין לצורך יום טוב. ש\u0003ר' שמעון אומר: כל שאין מומו\u0004 של הבכור \u0003ניכר מערב יום טוב\u0004 — \u0003אין זה\u0004 נחשב כ\u0003מן המוכן\u0004 מבעוד יום, ואסור בשחיטה. ומכאן שדבר שלא הוכן מבעוד יום יש בו לדעת ר' שמעון דין מוקצה!","אמר לו רבה: \u0003הכי השתא\u0004 \u0005[כיצד אתה משווה]?\u0006 \u0003התם\u0004 \u0005[שם]\u0006 בנר, \u0003אדם יושב ומצפה אימתי תכבה נרו,\u0004 שברור לו שיכבה הנר, ויש להניח שתישאר כמות מסויימת של שמן בנר או בקערה. ואולם \u0003הכא\u0004 \u0005[כאן]\u0006 וכי \u0003אדם יושב ומצפה מתי יפול בו מום? מימר אמר\u0004 \u0005[\u0006ש\u0005אומר הוא]\u0006 בעל הבכור: \u0003מי יימר דנפיל ביה מומא\u0004 \u0005[\u0006\u0005מי יאמר שיפול בו מום],\u0006 \u0003ו\u0004אף \u0003אם תמצי\u0004 \u0005[תרצה]\u0006 \u0003לומר דנפיל ביה מומא\u0004 \u0005[ש\u0006כן \u0005יפול בו מום]\u0006 — \u0003מי יימר דנפיל ביה\u0004 \u0005[מי יאמר שיפול\u0006 \u0003בו] מום קבוע\u0004 שיהא מותר לשחטו בשל מום זה. \u0003ו\u0004אף \u0003אם תמצי\u0004 \u0005[תרצה]\u0006 \u0003לומר דנפיל ביה מומא\u0004 \u0005[שיפול בו מום]\u0006 \u0003קבוע\u0004 — \u0003מי יימר דמזדקק ליה\u0004 \u0005[מי יאמר שיזדקק לו]\u0006 \u0003חכם\u0004 לבדוק את מומו? וכיון שמרובים כל כך הספיקות בדבר, אם אין המום ניכר מערב יום טוב אין אדם מעלה בדעתו להשתמש כלל בבכור.","על נימוק אחרון זה \u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רמי בר חמא\u0004 ממה ששנינו במשנה: \u0003מפירין נדרים בשבת,\u0004 כגון שנדרה אשה שלא תאכל מאכל מסויים וכיוצא בזה, יכול בעלה להפר את נדרה בשבת. \u0003ו\u0004כן \u0003נשאלין\u0004 לחכם למצוא \"פתח\" או חרטה כדי \u0003ל\u0004התיר \u0003נדרים\u0004 שנדר אדם \u0003שהן\u0004 קשורים \u0003לצורך השבת.\u0004 וכאן יש לשאול: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 אף אחר שהפר הבעל לאשתו את נדרה, תהיה מותרת באותו מאכל? שהרי כשנדרה האשה ממאכל מסויים — כבר הקצתה אותו מדעתה, ולכן גם אם ימצא היתר לאחר מכן, יישאר האוכל בבחינת מוקצה. ועל בסיס אותו ספק שהעלינו מקודם \u0003לימא\u0004 \u0005[נאמר]:\u0006 \u0003מי יימר דמיזדקק\u0004 \u0005[מי אומר שיזדקק]\u0006 \u0003לה\u0004 ה\u0003בעל\u0004 להפר לה נדרה, \u0005ו\u0006שמא לא יפר?","ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 בנדרים יש לפרש כמו שאמר \u0003רב פנחס משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא,\u0004 שבא להסביר כמה מיסודות דיני הנדרים. ש\u0003אמר רב פנחס משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: כל\u0004 אשה \u0003הנודרת\u0004 — מראש \u0003על דעת בעלה היא נודרת.\u0004 שכיון שהיא יודעת שהבעל יכול להפרם, ממילא אין נדריה מוחלטים, ואישורם הגמור בא רק עם הסכמת הבעל. ולכן אשה שנדרה — לא הקצתה לגמרי את המאכל משימושה.","ומביאים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו בהמשך הדברים: \u0003נשאלין לנדרים של צורך השבת בשבת,\u0004 וכגון שנדר ביום השבת שלא יאכל היום. \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 מותר לאכול דבר שנדר ממנו? \u0003לימא\u0004 \u0005[נאמר]\u0006 גם כן: \u0003מי יימר דמזדקק ליה\u0004 \u0005[מי יאמר שיזדקק\u0006 \u0003לו]\u0004 ה\u0003חכם?\u0004 ומאחר שכן, ודאי הסיח את המאכל מדעתו, ויהיה אסור לאוכלו\u0003!\u0004 ומשיבים: בכל זאת יש הבדל, שכן \u0003התם\u0004 \u0005[שם,\u0006 בדיני נדרים\u0005]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא מיזדקק ליה\u0004 \u0005[יזדקק לו]\u0006 ה\u0003חכם סגיא ליה\u0004 \u0005[מספיק לו]\u0006 שיותר הנדר \u0003בשלשה הדיוטות\u0004 שאף שלכתחילה החכם הוא שמתיר את הנדר, מכל מקום בשעת הדחק אפשר לעשות בית דין המורכב משלושה אנשים סתם והם יתירוהו, ויודע כל אדם שבודאי יוכל למצוא דרך להתיר את נדרו. אבל \u0003הכא\u0004 \u0005[כאן]\u0006 בבכורות\u0005]\u0006 — \u0003מי יימר דמיזדקק ליה\u0004 \u0005[מי יאמר שיזדקק לו]\u0006 ה\u0003חכם\u0004 לבדוק את המום, שהרי בדיני בכורות רק חכם מוסמך, שקיבל היתר מיוחד לכך, רשאי לקבוע שזה מום קבוע ולהתיר את הבכור לשחיטת חולין.","\u0003רמי ליה\u0004 \u0005[השליך,\u0006 הקשה \u0005לו,\u0006 הראה סתירה\u0005]\u0006 \u0003אביי לרב יוסף: מי\u0004 \u0005[האם]\u0006 \u0003אמר ר' שמעון\u0004 כי כאשר \u0003כבתה\u0004 הנר \u0003מותר לטלטלה\u0004 בשבת. ומכאן נלמד כי כאשר \u0003כבתה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 מותר לטלטלה, ואולם כל עוד \u0003לא כבתה\u0004 — \u0003לא.\u0004 ו\u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 אסור לטלטל נר בוער? — \u0003דילמא בהדי דנקיט לה כבתה\u0004 \u0005[שמא בתוך שיטלטל אותו,\u0006 את הנר, \u0005יכבה],\u0006 ואולם האם חושש ר' שמעון לכיבוי מעין זה? \u0003הא שמעינן ליה\u0004 \u0005[הרי שמענו אותו]\u0006 את \u0003ר' שמעון\u0004 ש\u0003אומר\u0004 כלל שכל \u0003דבר\u0004 של מלאכת איסור בשבת \u0003ש\u0004נעשה בתוך כדי עשיית דבר אחר, שמאחר ו\u0003אין מתכוין\u0004 במלאכתו לעשות את דבר האיסור — \u0003מותר. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 ש\u0003ר' שמעון אומר: גורר אדם\u0004 בשבת וביום טוב \u0003כסא מטה וספסל, ובלבד שלא יתכוין לעשות חריץ\u0004 בקרקע. ואם בכל זאת נוצר חריץ, כיון שלא היתה זו כוונתו — אין בכך לדעת ר' שמעון איסור. ואם כן לדעת ר' שמעון לא יהא כל איסור בטלטול נר בוער, שאף אם עלול הוא להכבות, כיון שאין זו כוונת המטלטל, לא יהא בכך איסור!","ומשיבים, שיש להבדיל בין הדברים: \u0003כל היכא דכי מיכוין איכא איסורא דאורייתא\u0004 \u0005[בכל מקום שאם יתכוון,\u0006 לעשות את המלאכה, \u0005יש איסור מן התורה],\u0006 כגון בענין כיבוי הנר, אף \u0003כי לא מיכוין\u0004 \u0005[כאשר אינו מתכוין]\u0006 — \u0003גזר ר' שמעון\u0004 לאסור זאת \u0003מדרבנן\u0004 \u0005[מדברי סופרים],\u0006 ואולם \u0003כל היכא דכי מיכוין איכא איסורא דרבנן\u0004 \u0005[מקום ש\u0006אף \u0005כאשר\u0006 הוא \u0005מתכוון יש איסור מדברי סופרים\u0006 בלבד\u0005],\u0006 כגון בחפירת החריץ, שאיננה מלאכת חרישה גמורה האסורה מן התורה, ולא נאסרה עשיית חריץ זה אלא משום גזירת חכמים — \u0003כי לא מיכוין שרי\u0004 \u0005[כאשר אינו מתכוין מתיר]\u0006 \u0003ר' שמעון\u0004 לעשות את הדבר אף \u0003לכתחילה.\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רבא\u0004 על הסבר זה, הרי שנינו: \u0003מוכרי כסות מוכרין\u0004 אף בגדי כלאיים \u0003כדרכן\u0004 ומניחים אף בגדים אלה על גבם, למרות האיסור ללבוש בגד כלאיים, \u0003ובלבד שלא יתכוין\u0004 ללבוש את הבגד \u0003בחמה מפני החמה ובגשמים מפני הגשמים, והצנועין\u0004 המהדרים בשמירת המצוות \u0003מפשילין\u0004 בגדים אלה ותולים אותם \u0003במקל לאחוריהן. והא הכא, דכי מיכוין\u0004 \u0005[והרי כאן שכאשר\u0006 הוא \u0005מתכוין]\u0006 ללבוש — \u0003איסורא דאורייתא איכא\u0004 \u0005[יש איסור מן התורה],\u0006 ואף על פי כן \u0003כי\u0004 \u0005[וכאשר]\u0006 הוא \u0003לא מיכוין\u0004 \u0005[מתכוין]\u0006 ללבישה — \u0003שרי\u0004 \u0005[מתיר]\u0006 \u0003ר' שמעון לכתחילה.\u0004 והרי שאין ר' שמעון מחלק בדברים מבחינה זו!","\u0003אלא אמר רבא\u0004 הסבר אחר לדעת ר' שמעון בנר:"],["\u0003הנח לנר שמן ופתילה הואיל\u0004 ו\u0003נעשה בסיס לדבר האסור.\u0004 שאף ר' שמעון מודה שהשלהבת הבוערת בשבת הריהי מוקצה, ומאחר שאת הנר עצמו אין לטלטל, אף השמן והפתילה אסורים.","\u0003אמר ר' זירא\u0004 שכך \u0003אמר ר' אסי\u0004 שכך \u0003אמר ר' יוחנן\u0004 שכך \u0003אמר ר' חנינא\u0004 שכך \u0003אמר ר' רומנוס: לי התיר רבי\u0004 (ר' יהודה הנשיא) \u0003לטלטל\u0004 בשבת \u0003מחתה באפרה. אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא לר' אסי: מי\u0004 \u0005[האם]\u0006 \u0003אמר ר' יוחנן הכי\u0004 \u0005[כך]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 \u0003נוטל אדם\u0004 את \u0003בנו\u0004 בידו אף על פי שהילד מחזיק \u0003אבן בידו\u0004 שאסור לטלטלה, או נוטל \u0003כלכלה\u0004 (סל) \u0003והאבן בתוכה. ואמר רבה בר בר חנה\u0004 שכך \u0003אמר ר' יוחנן\u0004 כי \u0003בכלכלה מלאה פירות עסקינן\u0004 \u0005[עוסקים אנו],\u0006 שבשל הפירות מותר לטלטל גם את האבן. ואם כן, \u0003טעמא\u0004 \u0005[טעם]\u0006 ההיתר הוא דווקא באופן \u0003דאית\u0004 \u0005[שיש]\u0006 \u0003בה פירי\u0004 \u0005[פירות],\u0006 \u0003הא לית\u0004 \u0005[הרי אם אין]\u0006 \u0003בה פירי\u0004 \u0005[פירות]\u0006 — \u0003לא,\u0004 ומחתה זו המלאה אפר כיצד מותר לדעת ר' יוחנן לטלטלה?","\u0003\"אשתומם כשעה חדה\"\u0004 (דניאל ד, טז) \u0005[השתומם\u0006 ושתק \u0005כשעה אחת,\u0006 זמן מה\u0005]\u0006 ולא מצא תשובה. \u0003ו\u0004לבסוף \u0003אמר: הכא נמי דאית\u0004 \u0005[כאן גם כן\u0006 מדובר באופן \u0005שיש]\u0006 \u0003בה\u0004 במחתה \u0003קרטין\u0004 \u0005[פירורים\u0006 של לבונה\u0005]\u0006 שלא נשרפו עדיין, ובשל החתיכות הללו מותר לטלטל את המחתה. \u0003אמר אביי: קרטין בי\u0004 \u0005[פירורים בבית]\u0006 \u0003רבי מי חשיבי\u0004 \u0005[האם\u0006 הם \u0005חשובים]?\u0006 ומאחר שאינם נחשבים — בטלים הם אגב האפר, והכל יחד אינו חשוב וראוי לשימוש.","\u0003וכי תימא חזו\u0004 \u0005[ואם תאמר\u0006 ש\u0005ראויים]\u0006 הפירורים עבור ה\u0003עניים,\u0004 ונסביר כי חשיבותם של דברים אינה נקבעת על פי המקום שהם בו, אלא במדה שיש בהם חשיבות בכלל, \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 שאף שיש הבדל בדיני טומאה בין בגדי עניים המטמאים אפילו בשיעור קטן, ובגדי עשירים שאינם נחשבים בשיעור זה, ודרוש שיעור גדול בהרבה כדי להחשיבם, מכל מקום שיעור \u0003בגדי עניים\u0004 הוא \u0003לעניים,\u0004 ושיעור \u0003בגדי עשירים\u0004 הוא \u0003לעשירים,\u0004 אבל שיעור של \u0003עניים\u0004 לגבי \u0003עשירים לא\u0004 נחשב. ומכאן שדנים את חשיבותו של חפץ לפי מקומו ובעליו. \u0003אלא אמר אביי,\u0004 יש לתת הסבר אחר: \u0003מידי דהוה\u0004 \u0005[כדרך\u0006 שהדבר \u0005הוא]\u0006 ביחס ל\u0003גרף של ריעי\u0004 (צואה). שמשום זוהמתו התירו להוציאו מחוץ לבית, אף שודאי אין בו שימוש.","\u0003 אמר רבא: שתי תשובות\u0004 יש לדחות את ה\u0003דבר : חדא\u0004 \u0005[אחת],\u0006 \u0003גרף של ריעי מאיס\u0004 \u0005[מאוס],\u0006 \u0003והאי לא מאיס\u0004 \u0005[וזו,\u0006 \u0005המחתה,\u0006 \u0005אינה מאוסה]\u0006 \u0003ועוד, גרף של ריעי מיגלי\u0004 \u0005[מגולה]\u0006 וריחו נודף, \u0003והאי מיכסי\u0004 \u0005[\u0006\u0005וזו\u0006 המחתה \u0005מכוסה].\u0006 \u0003אלא אמר רבא:\u0004 יש לפרש זאת באופן אחר: \u0003כי הוינן בי\u0004 \u0005[כאשר היינו\u0006 לומדים \u0005בבית]\u0006 \u0003רב נחמן הוה מטלטלינן כנונא אגב קיטמא\u0004 \u0005[היינו מטלטלים מחתה אגב האפר],\u0006 \u0003ואף על גב דאיכא עליה\u0004 \u0005[ואף על פי שיש עליה]\u0006 \u0003שברי עצים,\u0004 שמאחר שאפשר להשתמש באפר כדי לכסות בו לכלוך — אינו מוקצה, ומותר לטלטל בשלו אף את המחתה. ואפילו יש עליה שברי עצים, שאינם ראויים לדבר, מכל מקום מתבטלים הם אגב האפר. על ההערה האחרונה \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה שאמרו: \u0003ושוין\u0004 (מסכימים) ר' יהודה ור' שמעון \u0003שאם יש בה\u0004 בנר \u0003שברי פתילה שאסור לטלטל\u0004 את הנר, והרי ששברים אלה אינם מתבטלים, ומקצים את הנר כולו! \u0003אמר אביי:\u0004 אין להביא מכאן ראייה כי ברייתא זו \u0003בגלילא\u0004 \u0005[בגליל]\u0006 \u0003שנו\u0004 אותה, ושם השמן מרובה וזול, ולכן אין שברי פתילה בטלים אגב השמן (ר\"נ גאון).","מסופר כי \u0003לוי בר שמואל אשכחינהו\u0004 \u0005[מצא אותם]\u0006 את \u0003ר' אבא ו\u0004את \u0003רב הונא בר חייא דהוו קיימי אפיתחא דבי\u0004 \u0005[שהיו עומדים על פתח ביתו]\u0006 של \u0003רב הונא. אמר להו\u0004 \u0005[להם]\u0006 לוי בר שמואל: \u0003מהו\u0004 הדין לענין \u0003להחזיר מטה של טרסיים\u0004 (צורפים) שהיתה כרגיל מיטה מתקפלת, ולהרכיבה \u0003בשבת? אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003שפיר דמי\u0004 \u0005[יפה,\u0006 מותר \u0005הדבר].\u0006 \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב יהודה\u0004 לשאול אותה שאלה, ו\u0003אמר\u0004 לו רב יהודה: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003המחזיר מטה של טרסיים בשבת\u0004 — \u0003חייב חטאת,\u0004 לפי שעשה מלאכה האסורה מן התורה בשבת.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על לוי בר שמואל ממה ששנינו בתוספתא: \u0003המחזיר קנה מנורה\u0004 מפורקת ומרכיבה \u0003בשבת\u0004 — \u0003חייב חטאת.\u0004 החזיר \u0003קנה\u0004 של \u0003סיידין\u0004 שעשוי ומורכב מחוליות — \u0003לא יחזיר\u0004 לכתחילה, \u0003ואם החזיר\u0004 — \u0003פטור\u0004 מחטאת, \u0003אבל אסור\u0004 לעשות כן. \u0003ר' סימאי אומר: קרן עגולה\u0004 שהיא סוג חצוצרה מתפרקת ועגולה שהרכבתה מסובכת, אם הרכיבה \u0003חייב,\u0004 אבל \u0003קרן פשוטה\u0004 שהיא ישרה והרכבתה קלה, אם הרכיבה — \u0003פטור.\u0004 ומכאן למדנו שהרכבת דבר העשוי פרקים בשבת אסורה מן התורה, וחייב עליה חטאת! ומשיבים: \u0003אינהו דאמור כי האי תנא\u0004 \u0005[הם שאמרו\u0006 והתירו כשיטת \u0005תנא זה]\u0006 \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003מלבנות המטה\u0004 שהיא מסגרת העץ שעליה אורגים את חבלי המטה (גאונים), \u0003וכרעות\u0004 (רגלי) \u0003המטה, ולווחים של סקיבס\u0004 שהם חלק מקשת ועליהם הוא מותח את החץ, אם התפרקו מן המטה או מן הקשת — \u0003לא יחזיר\u0004 וירכיבם, \u0003ואם החזיר\u0004 — \u0003פטור,\u0004"],["\u0003אבל אסור. ולא יתקע\u0004 את הפרקים בחוזק, \u0003ואם תקע\u0004 — \u0003חייב חטאת,\u0004 שעשה מלאכה האסורה מן התורה. \u0003רבן שמעון בן גמליאל אומר: אם היה רפוי\u0004 וניתן להרכבה בקלות — \u0003מותר.\u0004 ועל שיטה זו סמכו ר' אבא ורב הונא בר חייא.","וכן מסופר: \u0003בי\u0004 \u0005[בבית]\u0006 \u0003רב חמא\u0004 סבו של רבא \u0003הוה\u0004 \u0005[היתה]\u0006 \u0003מטה גללניתא\u0004 \u0005[מתפרקת].\u0006 \u0003הוה מהדרי לה ביומא טבא\u0004 \u0005[והיו מחזירים אותה\u0006 ומרכיבים ביום טוב\u0005].\u0006 \u0003אמר ליה ההוא מדרבנן\u0004 \u0005[לו אחד החכמים]\u0006 \u0003לרבא: מאי דעתיך\u0004 \u0005[מה דעתך]\u0006 שאתה מתיר — משום ש\u0003בנין מן הצד הוא?\u0004 כלומר, שאין זו מלאכת בניה, כיון שיש בה שינוי ואינה עשוייה כדרכה? \u0003נהי דאיסורא דאורייתא ליכא, איסורא דרבנן מיהא איכא\u0004 \u0005[אם אמנם איסור מן התורה אין\u0006 כאן \u0005אבל איסור מדברי חכמים בכל אופן יש]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003אנא\u0004 \u0005[אני]\u0006 \u0003כ\u0004שיטת \u0003רבן שמעון בן גמליאל סבירא לי\u0004 \u0005[סבור אני]\u0006 שאמר ש\u0003אם היה רפוי\u0004 — \u0003מותר\u0004 אף לכתחילה.","\u0003נותנין כלי תחת הנר\u0004 כדי \u0003לקבל ניצוצות\u0004 בוערים של שמן הנופלים ממנו כדי שלא יזיקו ויגרמו לשריפה. \u0003ולא יתן לתוכו\u0004 של הכלי \u0003מים, מפני שהוא מכבה\u0004 על ידי כך את הניצוצות.","שואלים: כיצד מותר לתת כלי זה שיכיל בתוכו את הניצוצות, \u0003והא\u0004 \u0005[והרי]\u0006 בכך \u0003קמבטל\u0004 \u0005[הוא מבטל]\u0006 את ה\u0003כלי מהיכנו,\u0004 ששוב אינו מוכן לכל שימוש בשבת, שמוקצה הוא בשל הניצוצות. וכבר הועלתה השיטה שכל ביטול כזה אסור! \u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: ניצוצות אין בהן ממש,\u0004 והם נשרפים מיד ואינם משאירים כל שמן בכלי, ולכן ראוי הכלי לטלטול לאחר מכן. במשנה שנינו ש\u0003לא יתן לתוכו,\u0004 לתוך הכלי שהניח מתחת לנר, \u0003מים מפני ש\u0004בכך הוא \u0003מכבה\u0004 את הניצוצות. ומעירים: \u0003לימא תנן סתמא\u0004 \u0005[האם לומר שלמדנו\u0006 במשנה \u0005סתמית]\u0006 \u0003כ\u0004שיטת \u0003ר' יוסי\u0004 ש\u0003אמר\u0004 שאף ה\u0003גורם לכיבוי\u0004 — \u0003אסור.\u0004 שהרי הכיבוי שמדובר בו כאן, שנותן מים בכלי, אינו כיבוי על ידי מעשה, כי אם רק גורם לכיבוי.","","שאלה זו דוחים בתמיהה: \u0003ותסברא\u0004 \u0005[וכי\u0006 יכול \u0005אתה לחשוב\u0006 דבר כעין זה\u0005]?\u0006 \u0003אימור\u0004 \u0005[אמור]\u0006 ש\u0003אמר ר' יוסי\u0004 שגרם כיבוי אסור — \u0003בשבת,\u0004 ואולם \u0003בערב שבת מי\u0004 \u0005[האם]\u0006 \u0003אמר? וכי תימא הכא נמי\u0004 \u0005[ואם תאמר\u0006 כי \u0005כאן גם כן]\u0006 מדובר שנתן את המים בתוך הכלי \u0003בשבת, והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003נותנין כלי תחת הנר לקבל ניצוצות\u0004 הנופלים מן הנר \u0003בשבת, ואין צריך לומר\u0004 שמותר לשים אותו \u0003בערב שבת. ולא יתן לתוכו מים, מפני שהוא מכבה,\u0004 אפילו אם הניחו \u0003מערב שבת, ואין צריך לומר\u0004 שאסור לעשות כן \u0003בשבת\u0004 עצמה. הרי שהדבר אינו קשור כלל בשיטת ר' יוסי. \u0003אלא אמר רב אשי: אפילו תימא רבנן\u0004 \u0005[תאמר\u0006 שמשנה זו כדעת \u0005חכמים]\u0006 היחא, ואולם \u0003שאני הכא\u0004 \u0005[שונה כאן]\u0006 — \u0003מפני\u0004 שבמקרה זה איננו רק גורם לכיבוי אלא \u0003שמקרב את כיבויו,\u0004 שהניצוצות כבים מיד כשנופלים במים (ר\"ח) ובענין זה אפילו חכמים אוסרים.","","במשנה זו נמנים דברים המותרים והאסורים בטמינה, כלומר, בהכנסת כלי שיש בו תבשיל שנתחמם מערב שבת למקום שלא יפיג את חומו. ומפרטים: \u0003במה טומנין ובמה אין טומנין?\u0004 — \u0003אין טומנין לא בגפת\u0004 שהיא הכוספה הנשארת מחמרים המכילים שמן, לאחר שהוציאו מהם את השמן, \u0003ולא בזבל, לא במלח, ולא בסיד ולא בחול, בין\u0004 שהם \u0003לחין\u0004 ו\u0003בין\u0004 שהם \u0003יבשין.\u0004 כי כל החומרים הללו מתחממים מעצמם כשהם שוהים זמן מה בערימה, ומוסיפים חום בקדירה שהונחה בהם, והרי זה כעין בישול. \u0003ו\u0004אין טומנים \u0003לא בתבן, ולא בזגין\u0004 (קליפות הענבים לאחר שנסחט מהם היין), \u0003ולא במוכין,\u0004 שהם בלואי בגדים רכים, \u0003ולא בעשבין.\u0004 ואולם זהו דווקא \u0003בזמן שהן לחין, אבל טומנין בהן כשהן יבשין.\u0004","","\u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 לבני הישיבה\u0005]\u0006 שאלה זו: האם \u0003גפת של זיתים תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005],\u0006 \u0003אבל\u0004 של \u0003שומשמין שפיר דמי\u0004 \u0005[יפה הוא,\u0006 מותר\u0005]\u0006 לטמון בה מערב שבת את התבשיל, \u0003או דילמא\u0004 \u0005[שמא]\u0006 של \u0003שומשמין תנן\u0004 \u0005[שנינו]\u0006 \u0003וכל שכן\u0004 שבשל \u0003זיתים\u0004 אסור, שהרי הבלו מרובה מזה של שומשומים?! \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ש\u0003אמר ר' זירא משום\u0004 (בשם) \u0003חד דבי\u0004 \u0005[אחד\u0006 החכמים \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ינאי: קופה\u0004 (סל) \u0003שטמן בה\u0004 תבשיל שנתחממם בערב שבת — \u0003אסור להניחה על\u0004 גבי \u0003גפת של זיתים\u0004 בשבת. ואם כן \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 כי בענין גפת \u0003של זיתים תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005].\u0006","","את ההוכחה הזאת דוחים: \u0003לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 כי \u0003לענין הטמנה\u0004 בתוך גפת, הרי בשל \u0003שומשמין נמי\u0004 \u0005[גם כן]\u0006 \u0003אסור\u0004 להטמין, ואולם \u0003לענין\u0004"],["\u0003אסוקי הבלא\u0004 \u0005[העלאת הבל]\u0006 עד כדי שהגפת תחמם דבר שאינו טמון בה אלא רק מונח עליה, הרי גפת של \u0003זיתים מסקי הבלא\u0004 \u0005[מעלה הבל],\u0006 ולכן אסור להניח עליה תבשיל, ואולם של \u0003שומשמין לא מסקי הבלא\u0004 \u0005[אינה מעלה הבל]\u0006 במדה זו, ולכן מותר להניח עליה.","בהקשר מסויים לדברים הקודמים מסופר: \u0003רבה ור' זירא איקלעו לבי ריש גלותא\u0004 \u0005[הזדמנו לבית ראש הגולה].\u0006 \u0003חזיוה לההוא עבדא דאנח כוזא דמיא אפומא דקומקומא\u0004 \u0005[ראו עבד אחד שמניח ספל מים על פי קומקום]\u0006 שהיו בו מים חמים. \u0003נזהיה\u0004 \u0005[גער בו]\u0006 \u0003רבה\u0004 שעושה הוא שלא כדין. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא: מאי שנא\u0004 \u0005[מה שונה\u0006 הדבר\u0005]\u0006 \u0003מ\u0004הלכה זו ששנינו שמותר להניח בשבת \u0003מיחם על גבי מיחם? אמר ליה\u0004 \u0005[לו]\u0006 רבה: \u0003התם\u0004 \u0005[שם]\u0006 כאשר הוא מניח מיחם על גבי מיחם \u0003אוקומי קא מוקים\u0004 \u0005[להעמיד\u0006 בלבד \u0005הוא שמעמיד]\u0006 ומחזיק את החום הקיים במיחם העליון, ואולם \u0003הכא\u0004 \u0005[כאן]\u0006 במקרה שלפנינו כאשר מניח ספל מים צוננים על גבי קומקום חם \u0003אולודי קא\u0004 \u0005[להוליד הוא]\u0006 ש\u0003מוליד\u0004 חום שלא היה אילולא היה עושה כן.","\u0003הדר חזייה דפרס דסתודר אפומיה דכובא ואנח נטלא עילויה.\u0004 \u0005[חזר וראה אותו\u0006 עבד \u0005שפורש סודר על פני גיגית מים ומניח ספל עליו].\u0006 \u0003נזהיה\u0004 \u0005[גער בו]\u0006 \u0003רבה. אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא: אמאי\u0004 \u0005[מדוע]\u0006 גוער אתה בו? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה: \u0003השתא חזית\u0004 \u0005[עכשיו תראה],\u0006 כלומר, המתן קצת וראה. \u0003לסוף חזייה דקא מעצר ליה\u0004 \u0005[לבסוף ראהו שהוא סוחטו,\u0006 את הסודר\u0005]\u0006 ועובר בכך על איסור מן התורה. ובכל זאת \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' זירא: \u0003מאי שנא מפרונקא\u0004 \u0005[\u0006ב\u0005מה שונה\u0006 דבר זה \u0005מבגד שנהוג לפרוש\u0006 על גבי גיגיות\u0005]\u0006 שמותר לפורסו אף בשבת? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה: יש להבדיל בין הדברים, \u0003התם לא קפיד עילויה\u0004 \u0005[שם\u0006 באותו בגד \u0005אינו מקפיד עליו]\u0006 אם יירטב וממילא אינו בא לסוחטו, ואולם \u0003הכא קפיד עילויה\u0004 \u0005[כאן\u0006 כששם סודר הריהו \u0005מקפיד עליו]\u0006 ובא לסוחטו.","שנינו במשנה שאין מטמינים \u0003לא בתבן\u0004 ולא בזגים ולא במוכין. \u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רב אדא בר מתנה מאביי: מוכין שטמן בהן\u0004 את הקדירה \u0003מהו לטלטלן בשבת?\u0004 האם המוכין שכרגיל הם מוקצה בשבת, מותרים בטלטול משום שהטמין בהם קדרתו ועשאן בשל כך לכלי?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003וכי מפני שאין לו\u0004 לאותו אדם לפי שעה \u0003קופה של תבן\u0004 כדי לטמון בה, \u0003עומד\u0004 הוא \u0003ומפקיר קופה של מוכין?\u0004 הלא בודאי השתמש במוכין להטמנה רק לפי שעה, ורצונו שלא יתקלקלו, ואינו רוצה לעשות בהם שימוש אחר בשבת, ואם כן הריהם מוקצים.","ומעירים \u0003לימא\u0004 \u0005[האם נאמר]\u0006 כי מה ששנינו במקום אחר \u0003מסייע ליה\u0004 \u0005[לו]\u0006 לשיטתו. ששנינו במשנה: \u0003טומנין בגיזי צמר ובציפי צמר\u0004 (צמר סרוק) \u0003ובלשונות של\u0004 צמר שנצבעו ב\u0003ארגמן, ובמוכין, ואין מטלטלין אותן.\u0004 והרי זה איפוא כדברי אביי.","ודוחים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום הא\u0004 \u0005[זה]\u0006 — \u0003לא איריא\u0004 \u0005[אין\u0006 זו \u0005ראיה],\u0006 כי משנה זו \u0003הכי קאמר\u0004 \u0005[כך אמרה]:\u0006 \u0003אם לא טמן בהן אין מטלטלין אותן\u0004 בשבת, שנותרו כפי שהם כרגיל והם מוקצים.","על טענה זו תוהים: \u0003אי הכי מאי למימרא\u0004 \u0005[אם כך\u0006 שאין שתי הלכות אלה קשורות זו בזו \u0005מהו\u0006 החידוש \u0005באמירתם],\u0006 שבודאי דינם כמוקצה! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי \u0003חזי למזגא עלייהו\u0004 \u0005[ראויים\u0006 כל הדברים הללו \u0005לשבת עליהם]\u0006 ובשל כך ייחשבו ככלים, ויותרו בטלטול, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין הדבר כן, ואסורים משום מוקצה.","מסופר כי \u0003רב חסדא שרא לאהדורי אודרא לבי סדיא בשבתא\u0004 \u0005[התיר להחזיר מוך לתוך הכר בשבת].\u0006 \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב חנן בר חסדא לרב חסדא\u0004 ממה ששנינו בברייתא: \u0003מתירין בית הצואר\u0004 של כתונת \u0003בשבת\u0004 אם נקשר על ידי הכובס, \u0003אבל לא פותחין\u0004 פתח הצואר לכתחילה. \u0003ואין נותנין את המוכין לא לתוך הכר ולא לתוך הכסת ביום טוב, ואין צריך לומר\u0004 שאין נותנים אותם \u0003בשבת.\u0004 והרי זה בניגוד לדברי רב חסדא!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא בחדתי\u0004 \u0005[זה\u0006 שאסרו, מדובר \u0005בחדשים]\u0006 שעל ידי הכנסת המוכין לתוך הכר יוצר הוא כלי חדש ו\u0003הא בעתיקי\u0004 \u0005[וזה\u0006 שהתיר רב חסדא, מדובר \u0005בעתיקים,\u0006 ישנים\u0005]\u0006 שאין איסור להחזירם לכר.","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנינו\u0006 בברייתא \u0005גם כן כך]:\u0006 \u0003אין נותנין את המוכין לא לתוך הכר ולא לתוך הכסת ביום טוב, ואין צריך לומר\u0004 שאין נותנים \u0003בשבת.\u0004 אבל אם \u0003נשרו\u0004 המוכין מהכר, \u0003מחזירין אותן\u0004 לכר אף \u0003בשבת, ואין צריך לומר\u0004 שמותר \u0003ביום טוב.\u0004","מאחר שהוזכר ענין פתיחת בית הצואר מביאים את מה ש\u0003אמר רב יהודה\u0004 שכך \u0003אמר רב: הפותח בית הצואר\u0004 בכתונת שלא היתה פתוחה, ובתוך כך חותך את האריג והחוטים המחברים \u0003בשבת\u0004 — \u0003חייב חטאת.\u0004 כי על ידי הפתיחה נעשתה הכתונת ראוייה ללבישה, ונמצא שהוא מתקן כלי בשבת.","\u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 \u0003רב כהנא:\u0004"],["\u0003מה בין זו למגופת חבית\u0004 שהתירו לפתוח את מגופת החבית כדי לתת יין לאורחים, והרי אף כאן בפתיחת המגופה הריהו כאילו יוצר את הכלי. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא:\u0004 אין לדמות את הדברים, כי \u0003זה\u0004 מיפתח החלוק הוא \u0003חיבור,\u0004 שהוא חלק מאריגתו של הבד, \u0003וזה,\u0004 מגופת החבית, \u0003אינו חיבור,\u0004 כי אף שמדביקים בטיט את מגופת החבית אל החבית, מכל מקום הריהי חלק נפרד, וכשפותחים אותה אין בכך משום יצירת כלי.","\u0003רמי ליה\u0004 \u0005[השליך,\u0006 הקשה \u0005לו,\u0006 הראה סתירה בין הדברים\u0005]\u0006 \u0003ר' ירמיה לר' זירא: תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003שלל של כובסין\u0004 (בגדים שהכובס מחבר אותם חיבור עראי זה לזה כדי שלא יאבדו), \u0003ושלשלת של מפתחות, והבגד שהוא תפור ב\u0004חוטי \u0003כלאים,\u0004 כגון בגד צמר התפור בחוטי פשתן שצריך להתירו, אף על פי שכל אלה אינם עתידים להתקיים, שכולם עשויים להתירם לאחר זמן, מכל מקום לפי שעה מהווים הם עדיין יחידה אחת שהיא \u0003חיבור לטומאה,\u0004 שאם נגעה טומאה באחד — גם האחרים נטמאים, \u0003עד שיתחיל להתיר\u0004 ויתברר שאין רצונו בחיבור זה. \u0003אלמא\u0004 \u0005[מכאן]\u0006 אתה למד כי אף \u0003שלא בשעת\u0004 עשיית אותה \u0003מלאכה\u0004 מסויימת לצורכה נוצר החיבור \u0003נמי\u0004 \u0005[גם כן]\u0006 נחשב הוא ל\u0003חיבור.\u0004","\u0003ורמינהו\u0004 \u0005[ואנו משליכים,\u0006 מקשים\u0005]\u0006 על כך ממה ששנינו במשנה אחרת: \u0003מקל שעשה\u0004 אותו \u0003יד לקורדום\u0004 — הרי זה \u0003חיבור לטומאה,\u0004 שאם נטמא הקרדום — נטמא גם המקל, וכן להיפך, \u0003בשעת מלאכה\u0004 שעושה בקרדום. ומכאן אפשר להסיק: שדווקא \u0003בשעת מלאכה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003שלא בשעת מלאכה\u0004 — \u0003לא!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 : \u0003התם\u0004 \u0005[שם,\u0006 בקרדום\u0005]\u0006 \u0003שלא בשעת מלאכה\u0004 אין אדם מקפיד על חיבור זה, ואותו מקל \u0003אדם עשוי לזורקו\u0004 אחר המלאכה \u0003לבין העצים\u0004 של הסקה, ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 בדברים שנמנו במשנה הראשונה \u0003שלא בשעת מלאכה נמי ניחא ליה\u0004 \u0005[גם כן נוח לו]\u0006 שישארו מחוברים, \u0003דאי מיטנפו הדר מחוור להו\u0004 \u0005[שאם נתלכלכו\u0006 כשהם יחד \u0005יחזור ויכבס אותם],\u0006 שיותר קל לכבס אריג אחד גדול מכמה פיסות אריג קטנות.","\u0003בסורא מתנו לה להא שמעתא משמיה\u0004 \u0005[היו שונים הלכה זו,\u0006 שתיאמר מיד, \u0005משמו]\u0006 של \u0003רב חסדא,\u0004 ואילו \u0003בפומבדיתא מתנו משמיה\u0004 \u0005[היו שונים\u0006 אותה \u0005משמו]\u0006 של \u0003רב כהנא, ואמרי לה משמיה\u0004 \u0005[ויש אומרים\u0006 שהיו שונים אותה \u0005משמו]\u0006 של \u0003רבא. מאן תנא הא מלתא דאמור רבנן\u0004 \u0005[מי שנה,\u0006 מיהו התנא שהגה \u0005אותו דבר שאומרים חכמים\u0006 בכלל\u0005]\u0006 כי \u0003כל המחובר לו\u0004 לדבר \u0003הרי הוא כמוהו?\u0004","\u0003אמר רב יהודה אמר רב:\u0004 הלכה זו שיטת \u0003ר' מאיר היא. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 \u0003בית הפך\u0004 ששמים בו שמן, \u0003ובית התבלין ובית הנר\u0004 שכולם הם חללים קטנים בצידיה של הכירה, אם נטמאו דפנות הכירה במגע שרץ הרי אף הם \u0003מטמאין ב\u0004אותו \u0003מגע. ו\u0004אולם \u0003אין\u0004 הם \u0003מטמאין באויר,\u0004 שאם היה שרץ טמא בחלל הכירה, אף שהכירה עצמה נטמאה, אין בית הפך ובית התבלין נטמאים, אלו \u0003דברי ר' מאיר. ור' שמעון מטהר\u0004 אותם אף מגע השרץ בכירה.","ומעתה דנים בנושא. \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003ר' שמעון\u0004 הרי \u0003קסבר\u0004 \u0005[הוא סבור]\u0006 כי חללים אלה \u0003לאו\u0004 \u0005[לא]\u0006 \u0003ככירה\u0004 עצמה \u0003דמו\u0004 \u0005[\u0006הם \u0005נחשבים]\u0006 ומשום כך לדעתו אינם נטמאים כשהיא נטמאת. \u0003אלא ל\u0004שיטת \u0003ר' מאיר, אי\u0004 \u0005[אם]\u0006 לדעתו \u0003ככירה\u0004 עצמה \u0003דמו\u0004 \u0005[\u0006הם \u0005נחשבים]\u0006 — \u0003אפילו\u0004 אם היה השרץ \u0003באויר\u0004 הכירה \u0003נמי ליטמו\u0004 \u0005[גם כן יטמאו],\u0006 ו\u0003אי לאו ככירה\u0004 עצמה \u0003דמו\u0004 \u0005[\u0006הם \u0005נחשבים]\u0006 — \u0003אפילו במגע נמי\u0004 \u0005[גם כן]\u0006 ש\u0003לא ליטמו\u0004 \u0005[יטמאו]!\u0006","ומשיבים: \u0003לעולם לאו\u0004 \u0005[לא]\u0006 \u0003ככירה\u0004 עצמה \u0003דמו\u0004 \u0005[\u0006הם \u0005נחשבים]\u0006 \u0003ורבנן הוא דגזרו בהו\u0004 \u0005[ו\u0006אולם \u0005חכמים הם שגזרו בהם\u0006 טומאה\u0005]\u0006 בשל היותם סמוכים לכירה. על כך מקשים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003גזרו בהו\u0004 \u0005[בהם]\u0006 חכמים טומאה, אם כן \u0003אפילו\u0004 כאשר השרץ נמצא \u0003באויר\u0004 הכירה \u0003נמי ליטמו\u0004 \u0005[גם כן ייטמאו]!\u0006","ומשיבים: \u0003עבדו בהו רבנן היכרא, כי היכי\u0004 \u0005[עשו בהם חכמים היכר,\u0006 \u0003כדי]\u0004 ש\u0003לא אתי למשרף עליה\u0004 \u0005[יבואו לשרוף עליהם]\u0006 \u0003תרומה וקדשים.\u0004 כי איסור חמור הוא לאבד תרומה או קדשים. אף כי אמנם תרומה הטמאה מן התורה מצווים לשורפה, אך דברים הטמאים רק מדברי חכמים, כיון שמן התורה הם כשרים — אסור לאבדם. וכיון שיש לחשוש שיבואו לשורפם תקנו חכמים לעשות היכר והבדל בטומאה זו, כדי שידעו הכל שהיא מדברי חכמים בלבד, ולא ישרפו תרומה וקדשים בשל טומאה זו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003מספורת\u0004 (מספריים) של \u0003פרקים,\u0004 שכל אחד מחלקי המספריים עשוי להתפרק, \u0003ואיזמל של רהיטני\u0004 (הלהב שבמקצוע) הם \u0003חיבור\u0004 זה לזה \u0003ל\u0004ענין קבלת \u0003טומאה,\u0004 שאם נטמא חלק אחד נטמא גם חבירו, \u0003ו\u0004אולם \u0003אין\u0004 הם \u0003חיבור להזאה,\u0004 שכאשר מזים מי חטאת על הכלים כדי לטהרם מטומאת מת (ראה במדבר יט, יז–יט) אין בהזאה על אחד מהם כדי לטהר את כולם, ויש להזות על כל חלק לחוד.","על כך תוהים: מ\u0003מה נפשך, אי\u0004 \u0005[אם]\u0006 \u0003חיבור הוא\u0004 — \u0003אפילו להזאה נמי\u0004 \u0005[גם כן]\u0006 ייחשב חיבור, ו\u0003אי לאו\u0004 \u0005[אם לא]\u0006 \u0003חיבור הוא\u0004 — \u0003אפילו לטומאה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 ייחשב הדבר כחיבור! \u0003אמר רבא: דבר תורה\u0004 ש\u0003בשעת מלאכה\u0004 החלקים הללו מהווים \u0003חיבור\u0004 גמור, \u0003בין לטומאה בין להזאה. ושלא בשעת מלאכה,\u0004 אפילו נמצאים החלקים יחד, כיון שהם עשויים להתפרק ורגילים לפרקם \u0003אינו חיבור לא לטומאה ולא להזאה.\u0004"],["\u0003וגזרו רבנן על\u0004 ה\u0003טומאה אף שלא בשעת מלאכה משום טומאה שבשעת מלאכה\u0004 שייטמאו שני החלקים, \u0003ו\u0004לחומרה גזרו אף \u0003על הזאה שבשעת מלאכה\u0004 שיצטרכו להזות על כל חלק \u0003משום הזאה שלא בשעת מלאכה.\u0004","במשנה נמנו דברים אחדים שאסור לטמון בהם את התבשיל בערב שבת \u0003בזמן שהן לחין. איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 לבני הישיבה\u0005]\u0006 שאלה זו: האם המדובר דווקא שהיו הדברים \u0003לחין מחמת עצמן,\u0004 שזה טבעם והרטיבות היתה בהם מתחילת בריאתם, \u0003או דילמא\u0004 \u0005[שמא]\u0006 אפילו כאשר היו \u0003לחין מחמת דבר אחר,\u0004 שנשפכו נוזלים עליהם.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה שבמשנה פורטו הדברים: \u0003לא בתבן ולא בזגים ולא במוכין ולא בעשבים בזמן שהם לחין.\u0004 ומעתה \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 כי מדובר ב\u0003לחין מחמת דבר אחר\u0004 — \u0003שפיר\u0004 \u0005[יפה,\u0006 מובן \u0005הדבר\u0006\u0005],\u0006 שכולם יכולים להירטב. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי מדובר ב\u0003לחין מחמת עצמם, מוכין לחין מחמת עצמן היכי משכחת לה\u0004 \u0005[כיצד מוצא אתה אותה]\u0006 אפשרות שיהיה המוך רטוב מתחילתו? שהרי הצמר הוא דבר יבש מעיקרו! ומשיבים: \u0003ממרטא דביני אטמי\u0004 \u0005[מן\u0006 הצמר \u0005הנמרט מבין הירכיים],\u0006 שצמר זה כרגיל רטוב מחמת זיעה.","\u0003והא דתני\u0004 \u0005[וזו ששנה]\u0006 \u0003ר' אושעיא\u0004 הלכה ש\u0003טומנין בכסות יבשה\u0004 או \u0003בפירות יבשים, אבל לא בכסות לחה ולא בפירות לחין,\u0004 ולדברנו לכאורה הדבר תמוה, שכן \u0003כסות לחה מחמת עצמה היכי משכחת לה\u0004 \u0005[כיצד מוצא אתה אותה]?\u0006 ומשיבים: אף בזה יתכן לומר כי אותה כסות עשוייה \u0003ממרטא דביני אטמי\u0004 \u0005[מ\u0006צמר \u0005הנמרט מבין הירכיים],\u0006 שטוו וארגו צמר זה בעודו לח. ואם כן לא הצליחו להוכיח הוכחה מכרעת אם חומרים אלה צריכים להיות לחים מחמת עצמם, או אף מחמת דבר אחר.","\u0003טומנין בכסות ובפירות, בכנפי יונה, ובנסרת\u0004 עץ \u0003של חרשים\u0004 (נגרים) \u0003ובנעורת של פשתן דקה. ר' יהודה אוסר בדקה ומתיר בגסה\u0004 (עבה).","כיון שהוזכרו כאן כנפי יונה, מובא סיפור הקשור בהן. \u0003אמר ר' ינאי: תפילין צריכין גוף\u0004 נקי \u0003כ\u0004מו זה של \u0003אלישע \"בעל כנפים\".\u0004 ושואלים: \u0003מאי היא\u0004 \u0005[מה הוא]\u0006 הענין שבו יש לשמור על גוף נקי? \u0003אביי אמר: שלא יפיח בהן. רבא אמר: שלא יישן בהן.\u0004","ומסבירים: \u0003ואמאי קרי ליה\u0004 \u0005[ומדוע קורא לו\u0006 לאלישע\u0005]\u0006 \u0003\"בעל כנפים\"?\u0004 — \u0003שפעם אחת גזרה מלכות רומי הרשעה גזירה על ישראל שכל המניח תפילין ינקרו\u0004 כעונש \u0003את מוחו, והיה אלישע מניחם ויוצא לשוק. ראהו קסדור\u0004 (פקיד) \u0003אחד ורץ\u0004 (ברח) אלישע \u0003מפניו ורץ\u0004 הקסדור \u0003אחריו. וכיון שהגיע\u0004 הקסדור \u0003אצלו נטלן אלישע\u0004 לתפילין \u0003מראשו ואחזן בידו. אמר לו\u0004 הקסדור: \u0003מה זה בידך? אמר לו: כנפי יונה. פשט את ידו ונמצאו\u0004 בידו \u0003כנפי יונה. לפיכך קורין אותו\u0004 בשל נס זה \u0003\"אלישע בעל כנפים\".\u0004","ושואלים: \u0003ומאי שנא\u0004 \u0005[ומה שונה,\u0006 מיוחד\u0005]\u0006 \u0003כנפי יונה משאר עופות\u0004, שאמר אלישע שכנפי יונה בידו? ענו על כך: \u0003משום דאמתיל\u0004 \u0005[שנמשלה]\u0006 \u0003כנסת ישראל ליונה, שנאמר: \"כנפי יונה נחפה בכסף\u0004 ואברותיה בירקרק חרוץ\u0003\"\u0004 (תהילים סח, יד) וביאורו: \u0003מה יונה כנפיה\u0004 הן ה\u0003מגינות עליה,\u0004 שאין לה נשק אחר להלחם בו, \u0003אף ישראל מצות\u0004 הן ה\u0003מגינות עליהן.\u0004","שנינו במשנה שלדעת התנא הראשון טומנים את התבשיל \u0003בנסורת של חרשין,\u0004 ר' יהודה מחלק בין הטמנה בנסורת דקה לגסה. \u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 לבני הישיבה\u0005]\u0006 שאלה זו: האם דברי \u0003ר' יהודה\u0004 על \u0003נסורת של חרשין קאי\u0004 \u0005[עומדים,\u0006 מוסבים\u0005],\u0006 \u0003או\u0004 על ענין \u0003נעורת של פשתן קאי\u0004 \u0005[עומדים,\u0006 מוסבים\u0005]?\u0006","ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]\u0006 ש\u0003ר' יהודה אומר: נעורת של פשתן דקה הרי היא כזבל,\u0004 שמוסיף חום. ואם כן \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 כי על \u0003נעורת של פשתן קאי\u0004 \u0005[עומדים,\u0006 מוסבים\u0005]\u0006 דברי ר' יהודה. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד ממנה].\u0006","\u0003טומנין\u0004 את התבשיל בערב שבת \u0003בשלחין\u0004 (עורות) \u0003ומטלטלין אותן\u0004 בשבת. וכן טומנים \u0003בגיזי צמר\u0004 (צרורות צמר גזוז), \u0003ו\u0004אולם שלא כבשלחים \u0003אין מטלטלין אותן,\u0004 ו\u0003כיצד הוא עושה\u0004 כשטמן באלה ורצונו להוציא את הקדירה? \u0003נוטל את הכסוי\u0004 של הקדירה, שאותו מותר לטלטל, \u0003והן,\u0004 גיזי הצמר, \u0003נופלות\u0004 מאליהן, בלא שיצטרך לנגוע בהן.","\u0003ר' אלעזר בן עזריה אומר:\u0004 אם טמן את הקדירה בתוך \u0003קופה\u0004 (סל) המלאה בגיזי צמר, \u0003מטה\u0004 את אותה קופה \u0003על צדה\u0004 כדי שתיפולנה גיזי הצמר לצד הקדירה, \u0003ונוטל\u0004 אותה ממקומה, \u0003שמא יטול\u0004 את הקדירה, ויפלו גיזי הצמר לתוך החלל שנוצר בצמר כתוצאה מהנחת הקדירה \u0003ואינו יכול להחזיר,\u0004 שהרי אסור להזיז את הצמר משום מוקצה. \u0003וחכמים אומרים: נוטל ומחזיר.\u0004","מסופר: \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003ר' יונתן בן עכינאי ור' יונתן בן אלעזר, ויתיב\u0004 \u0005[וישב]\u0006 \u0003ר' חנינא בר חמא גבייהו\u0004 \u0005[אצלם,\u0006 לידם\u0005],\u0006 \u0003וקא מיבעיא להו\u0004 \u0005[ונשאלה להם]\u0006 שאלה זו: האם במשנה ב\u0003שלחין של בעל הבית תנן\u0004 \u0005[שנינו]\u0006 אותה הלכה, \u0003אבל\u0004 אם היו השלחים \u0003של אומן\u0004 שמקצועו בעורות \u0003כיון דקפיד עלייהו\u0004 \u0005[שהוא מקפיד עליהם]\u0006 שלא יתקלקלו שהרי הם נחוצים לו למלאכתו \u0003לא מטלטלינן להו\u0004 \u0005[מטלטלים אנו אותם].\u0006 \u0003או דילמא\u0004 \u0005[שמא]\u0006 שלחים \u0003של אומן תנן\u0004 \u0005[שנינו]\u0006 שמותר לטלטלם, \u0003וכל שכן של בעל הבית?\u0004","\u0003אמר\u0004 להם \u0003ר' יונתן בן אלעזר: מסתברא\u0004 \u0005[מסתבר]\u0006 לומר ששלחים \u0003של בעל הבית תנן\u0004 \u0005[שנינו]\u0006 \u0003אבל\u0004 ב\u0003של אומן\u0004 אסור כי הוא \u0003קפיד עלייהו\u0004 \u0005[מקפיד עליהם].\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003ר' חנינא בר חמא, כך אמר ר' ישמעאל בר' יוסי:\u0004"],["\u0003אבא שלחא הוה\u0004 \u0005[אבי מעבד עורות היה]\u0006 \u0003ואמר\u0004 פעם בשבת \u0003הביאו שלחין ונשב עליהן\u0004 (ר\"ח). שלדעתו אף שלחים של אומן מותרים בטלטול.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא: \u0003נסרין\u0004 של עץ \u0003של בעל הבית מטלטלין אותן\u0004 בשבת, \u0003ושל אומן אין מטלטלין אותן. ואם חישב לתת עליהן פת לאורחין\u0004 — \u0003בין כך ובין כך מטלטלין\u0004 אותם. הרי שחומרים השייכים לאומן אין מטלטלין! ומשיבים: \u0003שאני\u0004 \u0005[שונים]\u0006 ה\u0003נסרים דקפיד עלייהו\u0004 \u0005[ש\u0006הוא \u0005מקפיד עליהם]\u0006 שלא יתקלקלו, מה שאין כך בעורות שאינם מתקלקלים בישיבה.","ועוד \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראייה לדבר ממה ששנינו בברייתא אחרת: \u0003עורות, בין\u0004 שהם \u0003עבודין\u0004 (מעובדים), \u0003בין שאין\u0004 הם \u0003עבודין מותר לטלטלן בשבת. לא אמרו\u0004 כי לעורות ה\u0003עבודין\u0004 יש בהם דין מיוחד המבדילם מעורות שאינם מעובדים \u0003אלא לענין טומאה בלבד,\u0004 שרק עור מעובד ראוי לקבל טומאה. ולענייננו \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 נאמר כי \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 אם העורות \u0003של בעל הבית, ולא שנא\u0004 \u0005[ואינו שונה]\u0006 אם העורות \u0003של אומן?\u0004 ודוחים: \u0003לא,\u0004 מדובר כאן רק בעורות \u0003של בעל הבית.\u0004","ומקשים: אם כן, \u0003אבל\u0004 אם הם \u0003של אומן מאי\u0004 \u0005[מה\u0006 דינם\u0005]?\u0006 אם תאמר כי \u0003אין מטלטלין\u0004 אותם בשבת, \u0003אי הכי הא דתני\u0004 \u0005[אם כך זה ששנינו]\u0006 כי \u0003לא אמרו\u0004 שיש הבדל להלכה בין \u0003עבודין\u0004 לשאינם מעובדים \u0003אלא לענין טומאה בלבד,\u0004 אם כן \u0003לפלוג וליתני בדידה\u0004 \u0005[שיחלוק וישנה\u0006 חלוקה דקה יותר \u0005בה,\u0006 בתוכה\u0005]:\u0006 \u0003במה דברים אמורים\u0004 שאין מחלקים בין סוגי העורות — הרי זה דווקא \u0003ב\u0004עורות \u0003של בעל הבית, אבל בשל אומן\u0004 — \u0003לא!\u0004 ומתרצים: כל הברייתא \u0003כולה ב\u0004עורות של \u0003בעל הבית קמיירי\u0004 \u0005[עוסקת]\u0006 ולכן אין מקום לשאול מדוע אין דנים בעורות של אומן.","על עיקר השאלה מעירים שהיא \u0003כתנאי\u0004 \u0005[כתנאים]\u0006 שנחלקו בדבר זה, ששנינו בברייתא: \u0003עורות של בעל הבית מטלטלין אותן\u0004 בשבת, \u0003ושל אומן אין מטלטלין אותן. ר' יוסי אומר: אחד זה ואחד זה מטלטלין אותן.\u0004","אותם חכמים שישבו ודנו בענין העורות \u0003הדור יתבי וקמיבעיא להו\u0004 \u0005[חזרו\u0006 ו\u0005ישבו ונשאלה להם]\u0006 שאלה זו: \u0003הא דתנן\u0004 \u0005[זו ששנינו\u0006 במשנה\u0005]\u0006 שמספר \u0003אבות\u0004 ה\u0003מלאכות\u0004 האסורות בשבת מן התורה הן \u0003ארבעים חסר אחת, כנגד מי?\u0004 כלומר, מה מקורו של מנין זה?","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003ר' חנינא בר חמא: כנגד עבודות המשכן.\u0004 שכל אותן העבודות שהיו במשכן הרי הן חשובות ונמנו כאבות מלאכות לדיני שבת. ומלאכות אחרות, אף שהן חשובות, כיון שלא היו במשכן — אינן נמנות בין אבות המלאכות. \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003ר' יונתן בר' אלעזר, כך אמר ר' שמעון בר' יוסי בן לקוניא:\u0004 מספר זה של ארבעים חסר אחת הוא \u0003כנגד\u0004 מספר הפעמים שהמילים \u0003\"מלאכה\" \"מלאכתו\" ו\"מלאכת\"\u0004 כתובים בתורה, \u0003ש\u0004מניינם בסך הכל \u0003בתורה ארבעים חסר אחת.\u0004","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב יוסף:\u0004 האם הלשון \"מלאכתו\" הכתוב ביוסף \"ויהי כהיום הזה \u0003ויבא הביתה לעשות מלאכתו\u0004 ואין איש מאנשי הבית שם בבית\" (בראשית לט, יא) \u0003ממנינא\u0004 \u0005[ממנין]\u0006 שלושים ותשע הפעמים \u0003הוא, או לא? אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003וליתי\u0004 \u0005[ושיביאו]\u0006 \u0003ספר תורה ולימני\u0004 \u0005[וימנו],\u0006 ואפשר לבדוק מיד אם בלא פסוק זה יש שלושים ותשע לשונות \"מלאכה\". \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא אמר רבה בר בר חנה אמר ר' יוחנן\u0004 שבמקרה של ספק כזה \u0003לא זזו משם עד שהביאו ספר תורה ומנאום!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 : אין אני יכול לקבוע את הדבר על סמך מנין בלבד, משום שיש עוד פעם אחת לשון \"מלאכה\" שאין משמעותה ברורה בעיני, \u0003כי קא מספקא לי\u0004 \u0005[כאשר מסופק אני]\u0006 הרי זה \u0003משום דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והמלאכה היתה דים\u0004 לכל המלאכה לעשות אותה והותר\u0003\"\u0004 (שמות לה ז), והשאלה היא האם \u0003ממנינא\u0004 \u0005[ממנין]\u0006 שלושים ותשע לשונות ה\"מלאכה\" \u0003הוא\u0004 או לא? ומהות השאלה היא: האם לשון \"המלאכה\" הראשונה (\"והמלאכה היתה דים\") נחשב במשמעות של מלאכה ממש, \u0003והא\u0004 \u0005[ו\u0006פסוק \u0005זה]\u0006 בענין יוסף הריהו \u0003כמאן דאמר\u0004 \u0005[כ\u0006שיטת \u0005מי שאומר]\u0006 ש\"לעשות מלאכתו\" כאן היא בלשון נקיה, וכוונתה \u0003לעשות צרכיו\u0004 עמה בתשמיש נכנס.","\u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003\"ויבא הביתה לעשות מלאכתו\" ממנינא\u0004 \u0005[מן המנין]\u0006 \u0003הוא,\u0004 שכוונתו למלאכה ממש, \u0003והאי\u0004 \u0005[\u0006פסוק \u0005זה]\u0006 \u0003\"והמלאכה היתה דים\" הכי קאמר\u0004 \u0005[כך אמר,\u0006 כך יש להבינו\u0005]:\u0006 \u0003דשלים ליה עבידתא\u0004 \u0005[שהושלמה לה מלאכת\u0006 ההכנה, הבאת הנדבות\u0005],\u0006 ואין משמעו מלאכה ממש. בסיכומו של דבר לא נמצא פתרון לבעיה זו, ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","ולגופם של דברים: \u0003תניא כמאן דאמר\u0004 \u0005[שנויה\u0006 ברייתא \u0005כ\u0006דעת \u0005מי שאמר]\u0006 ששלושים ותשע מלאכות שבת הרי הן \u0003כנגד עבודות המשכן. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין חייבין\u0004 בשבת \u0003אלא על מלאכה שכיוצא בה היתה במשכן. הם זרעו\u0004 כדי לגדל צמחים מהם הפיקו צבע כהכנה לבנין המשכן, \u0003ואתם לא תזרעו\u0004 בשבת. \u0003הם קצרו\u0004 לצורך המשכן, \u0003ואתם לא תקצרו\u0004 בשבת.","\u0003הם העלו את הקרשים מקרקע\u0004 המדבר שהיא רשות הרבים \u0003לעגלה\u0004 שהיא רשות היחיד, \u0003ואתם לא תכניסו\u0004 בשבת \u0003מרשות הרבים לרשות היחיד. הם הורידו את הקרשים מעגלה לקרקע, ואתם לא תוציאו מרשות היחיד לרשות הרבים. הם הוציאו\u0004 קרשים וחפצים אחרים והעבירום \u0003מעגלה לעגלה,\u0004 כלומר, מרשות היחיד לרשות היחיד, \u0003ואתם לא תוציאו\u0004 בשבת \u0003מרשות היחיד לרשות היחיד.\u0004","על המשפט האחרון תוהים: \u0003מרשות היחיד לרשות היחיד, מאי קעביד\u0004 \u0005[מה הוא עושה]\u0006 שיהא בכך איסור? ומשיבים, \u0003אביי ורבא דאמרי תרוויהו\u0004 \u0005[שאמרו שניהם],\u0006 \u0003ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003רב אדא בר אהבה:\u0004 שיש להבין שהיה זה טלטול \u0003מרשות היחיד לרשות היחיד דרך רשות הרבים,\u0004 שהרי בית שתי העגלות היה המדבר שהוא רשות הרבים.","שנינו במשנה שטומנים \u0003בגיזי צמר ו\u0004אולם \u0003אין מטלטלין\u0004 אותם. \u0003אמר רבא,\u0004 יש להבין את המשנה כך: הדין שאין מטלטלים בגיזי צמר הוא הוראה כללית בדיני מוקצה, ו\u0003לא שנו\u0004 הלכה זו \u0003אלא\u0004 באופן \u0003שלא טמן\u0004 את התבשיל \u0003בהן, אבל\u0004 אם \u0003טמן בהן\u0004 את התבשיל — \u0003מטלטלין אותן,\u0004 כיון שבאותו זמן שטמן גילה דעתו שרצונו להשתמש בהם בשבת.","\u0003איתיביה ההוא מרבנן בר יומיה\u0004 \u0005[הקשה לו אחד החכמים\u0006 בן יומו שהיה זה יומו הראשון בבית המדרש\u0005]\u0006 \u0003לרבא\u0004 ממה ששנינו במשנתנו: \u0003טומנין בגיזי צמר ו\u0004אולם \u0003אין מטלטלין אותן. כיצד הוא עושה?\u0004 —"]]};
